    // ---------- ⑩ 자동 백업 내려받기 ----------
    // ==========================================================
    //  단어 빈도 분석 — 중요어 히트맵 (Task 31)
    //  자주 나온 낱말일수록 진한 파랑으로 물들여, 문서의 핵심어를
    //  한눈에 알아볼 수 있게 한다. (화면 표시 전용 · 원문 변경 없음)
    // ==========================================================
    // 화면 색칠용 <span class="wf"> 를 걷어내 원래 글자로 되돌린다.
    // (저장 경로에서 항상 통과시켜 색이 문서에 스며들지 않게 한다)
    function stripWF(html){
        if(!html||html.indexOf('class="wf')<0&&html.indexOf("class='wf")<0) return html;
        const d=document.createElement('div');
        d.innerHTML=html;
        d.querySelectorAll('span.wf').forEach(s=>{
            s.replaceWith(document.createTextNode(s.textContent));
        });
        d.normalize();
        return d.innerHTML;
    }

    // 조사·접속사 등 뜻이 옅은 말은 세지 않는다
    const WF_STOP=new Set([
        '그리고','그러나','하지만','그래서','또한','또는','및','등','수','것','때','더','좀','매우',
        '하다','한다','했다','합니다','입니다','이다','있다','없다','되다','된다','같다','통해','대한',
        '위해','대해','에서','에게','으로','까지','부터','보다','처럼','이런','저런','그런','어떤',
        '우리','저희','당신','자신','여기','거기','저기','오늘','내일','어제','정말','아주','너무',
        '이것','그것','저것','이때','그때','경우','가지','통한','따라','따른','관련','기타','이상','이하',
        '때문','대하','위하','그림','다음','이번','지금','모두','각각','서로','다시','먼저','또','즉',
        'the','and','for','are','but','not','you','all','any','can','has','had','was','were',
        'this','that','with','from','have','will','your','they','their','then','than','into',
        'been','when','what','which','also','more','some','such','only','over','very','just'
    ]);

    // 한글은 조사를 떼어 어간을 얻는다 (형태소 분석기 없이 쓰는 간단한 방법)
    // ※ 긴 것부터 검사해야 '으로서'가 '로'로 잘못 잘리지 않는다.
    const WF_JOSA=['으로서','으로써','에서는','에게서','이라고','라고는','까지도','부터는',
                   '에서도','에게는','으로는','이라는','에게도','으로도','만으로','라는',
                   '에서','에게','께서','으로','로서','로써','이라','까지','부터','마다',
                   '조차','밖에','처럼','보다','하고','이나','거나','와의','과의','에는','에도',
                   '의','를','을','이','가','은','는','에','도','만','로','과','와','랑'];
    // 용언 어미 (검토하였습니다 → 검토). 긴 것부터.
    const WF_VERB=['하였습니다','되었습니다','하겠습니다','되겠습니다','했습니다','합니다','됩니다',
                   '하였다','되었다','하였고','하였으며','시켰다','시키는','하려는','하려고','하면서',
                   '하기로','했지만','하지만','했었다','되어야','해야만',
                   '했다','한다','하고','하는','하며','하면','해서','해야','했던','하러','하자','하지',
                   '되는','되어','된다','됐다','되고','되며','있다','있는','없다','없는'];
    // 그 자체가 통째로 기능어인 말 (조사·어미를 떼면 껍데기만 남는 것)
    const WF_FUNC=new Set(['것이다','것이','것은','것을','수가','수는','수를','있다','없다',
        '되었습니다','하였습니다','합니다','됩니다','했습니다','이었다','이라','에서','으로']);
    function wfStem(w){
        if(!/[가-힣]/.test(w)) return wfStemEn(w);
        if(WF_FUNC.has(w)) return '';        // 통째로 버린다
        let prev=w;
        // 어미 → 조사 순으로 각 1회 (분석하였다 → 분석)
        for(let pass=0;pass<2;pass++){
            for(const v of WF_VERB){
                if(prev.length>v.length+1 && prev.endsWith(v)){ prev=prev.slice(0,-v.length); break; }
            }
            for(const j of WF_JOSA){
                if(prev.length>j.length+1 && prev.endsWith(j)){ prev=prev.slice(0,-j.length); break; }
            }
        }
        // 복수 접미사 '들' (학생들 → 학생)
        if(prev.length>2 && prev.endsWith('들')) prev=prev.slice(0,-1);
        return prev;
    }
    // 영문은 단·복수와 흔한 어미를 합쳐 같은 말로 센다 (Systems = system)
    function wfStemEn(w){
        const s=w.toLowerCase();
        if(s.length<4) return s;
        if(/[^aeiou]ies$/.test(s)) return s.slice(0,-3)+'y';   // studies → study
        if(/(s|x|z|ch|sh)es$/.test(s)) return s.slice(0,-2);   // analyses → analys
        if(/[^s]s$/.test(s)) return s.slice(0,-1);             // systems → system
        return s;
    }
    // 뜻이 옅어 세어도 의미 없는 말 (조사를 뗀 뒤에도 남는 것들)
    const WF_THIN=new Set(['것','수','때','곳','점','바','줄','things','thing','way','ways']);
    function wfValid(w){
        if(!w) return false;
        const s=w.toLowerCase();
        if(WF_STOP.has(s)||WF_THIN.has(s)) return false;
        if(/^[0-9]+$/.test(s)) return false;             // 숫자만
        if(/^[0-9]+[a-z가-힣]?$/.test(s)) return false;   // 1, 2쪽 같은 것
        if(/[가-힣]/.test(w)) return w.length>=2;         // 한글은 2글자 이상
        return /[a-z]/i.test(w) && w.length>=3;           // 영문은 3글자 이상
    }
    // 글자에서 낱말을 뽑는다 → [{raw, key, start}]
    function wfTokens(text){
        const out=[];
        const re=/[0-9A-Za-z가-힣]+/g;
        let m;
        while((m=re.exec(text))){
            const raw=m[0];
            const key=wfStem(raw).toLowerCase();
            if(wfValid(wfStem(raw))) out.push({raw,key,start:m.index,len:raw.length});
        }
        return out;
    }

    // 문서 전체를 훑어 낱말별 등장 횟수를 센다
    function wfAnalyze(){
        const count=new Map(), label=new Map();
        doc.pages.forEach(pg=>{
            (pg.els||[]).forEach(el=>{
                if(el.type!=='text') return;
                wfTokens(elPlainText(el)).forEach(t=>{
                    count.set(t.key,(count.get(t.key)||0)+1);
                    // 보여 줄 이름은 조사를 뗀 기본형 (보고서를 → 보고서)
                    if(!label.has(t.key)) label.set(t.key,wfStem(t.raw));
                });
            });
        });
        wfStats=[...count.entries()]
            .map(([k,n])=>({key:k,word:label.get(k),n}))
            .sort((a,b)=>b.n-a.n||a.word.localeCompare(b.word));
        wfMap=new Map(wfStats.map(s=>[s.key,s.n]));
        wfBuildLevels();
        return wfStats;
    }
    // 횟수 → 파랑 농도 (적으면 연하게, 많으면 진하게)
    // 등장 횟수 → 0~1 단계값.
    // 횟수만 쓰면 '5번'과 '4번'이 거의 같은 색이 되어 구분이 안 된다.
    // → 실제 존재하는 '횟수의 종류'를 줄 세워 단계를 고르게 벌린다.
    let wfLevels=[];              // [2,3,4,6,9] 처럼 오름차순
    function wfBuildLevels(){
        wfLevels=[...new Set(wfStats.filter(s=>s.n>=wfMin).map(s=>s.n))].sort((a,b)=>a-b);
    }
    function wfTone(n){
        if(!wfLevels.length) return 1;
        // 단계가 하나뿐이면 가장 진하게
        if(wfLevels.length===1) return 1;
        const i=wfLevels.indexOf(n);
        const rank=i<0?wfLevels.length-1:i;
        // 순위를 0~1 로 고르게 편다 (최저=연한 하늘, 최고=짙은 남색)
        let t=rank/(wfLevels.length-1);
        // 단계가 많으면 아래쪽이 몰려 보이므로 살짝 밀어 올려 대비를 키운다
        if(wfLevels.length>4) t=Math.pow(t,0.78);
        return t;
    }
    // 0~1 → 파랑 그라데이션.
    //  · 가장 적게 나온 말  = 아주 연한 하늘색
    //  · 가장 많이 나온 말  = 짙은 남색
    // 사이 단계도 확실히 구분되도록 밝기를 큰 폭으로 벌린다.
    // (완전한 검정까지는 가지 않아 본문 검은 글자와 구분된다)
    const WF_RAMP=[
        [0.00,[168,214,255]],   // 아주 연한 하늘
        [0.20,[109,178,250]],   // 하늘
        [0.40,[56,130,246]],    // 파랑
        [0.60,[29,86,214]],     // 진한 파랑
        [0.80,[18,48,140]],     // 감청
        [1.00,[10,22,72]]       // 짙은 남색
    ];
    function wfColor(n,max){
        const t=wfTone(n);
        let a=WF_RAMP[0], b=WF_RAMP[WF_RAMP.length-1];
        for(let i=0;i<WF_RAMP.length-1;i++){
            if(t>=WF_RAMP[i][0]&&t<=WF_RAMP[i+1][0]){ a=WF_RAMP[i]; b=WF_RAMP[i+1]; break; }
        }
        const k=(t-a[0])/Math.max(.0001,(b[0]-a[0]));
        const rgb=[0,1,2].map(i=>Math.round(a[1][i]+(b[1][i]-a[1][i])*k));
        // 굵기도 함께 5단계로 → 색과 겹쳐 차이가 더 또렷해진다
        const w = t>=.85?900 : t>=.65?800 : t>=.45?700 : t>=.22?600 : 500;
        return {c:`rgb(${rgb.join(',')})`, w, t};
    }

    function toggleWordFreq(){ wfOn?wfOff():wfRun(); }
    function wfRun(){
        if(!doc){ return; }
        commitEditingText(); deselectAll(true); clearMulti();
        wfAnalyze();
        const rep=wfStats.filter(s=>s.n>=wfMin);
        if(!wfStats.length){ toast('분석할 글자가 없습니다',2000); return; }
        wfOn=true; wfPick=null;
        document.getElementById('editorView').classList.add('wf-on');
        document.querySelectorAll('.js-wf').forEach(b=>b.classList.add('active'));
        wfPaint();
        document.getElementById('wfBar').classList.add('show');
        // 심플하게: 가장 많이 나온 말 하나만
        document.getElementById('wfInfo').innerHTML=
            `<b>${esc(wfStats[0].word)}</b> ${wfStats[0].n}번 · 낱말 ${rep.length}개`;
        if(sidePanel!=='words') openPanel('words'); else renderPanel();
    }
    function wfOff(){
        wfOn=false; wfPick=null;
        document.getElementById('editorView').classList.remove('wf-on');
        document.querySelectorAll('.js-wf').forEach(b=>b.classList.remove('active'));
        document.getElementById('wfBar').classList.remove('show');
        wfClear();
        if(sidePanel==='words') renderPanel();
    }
    // 색칠 제거 → 원래 글자 그대로 다시 그린다
    function wfClear(){
        if(!doc) return;
        doc.pages.forEach((p,i)=>{ if(paperAt(i)) renderPageEls(i); });
    }
    // 화면의 글자에만 색을 입힌다 (문서 데이터는 절대 건드리지 않음)
    function wfPaint(){
        if(!doc||!wfMap) return;
        const max=wfStats.length?wfStats[0].n:1;
        doc.pages.forEach((pg,pi)=>{
            const paper=paperAt(pi); if(!paper) return;
            (pg.els||[]).forEach(el=>{
                if(el.type!=='text') return;
                const node=paper.querySelector(`.tb[data-id="${el.id}"] .tb-content`);
                if(!node) return;
                wfPaintNode(node,max);
            });
        });
    }
    function wfPaintNode(root,max){
        const texts=[];
        const walk=(n)=>{
            for(const ch of Array.from(n.childNodes)){
                if(ch.nodeType===3){ if(ch.nodeValue.trim()) texts.push(ch); }
                else if(ch.nodeType===1 && !ch.classList.contains('wf')) walk(ch);
            }
        };
        walk(root);
        texts.forEach(tn=>{
            const text=tn.nodeValue;
            const toks=wfTokens(text).filter(t=>(wfMap.get(t.key)||0)>=wfMin);
            if(!toks.length) return;
            const frag=document.createDocumentFragment();
            let at=0;
            toks.forEach(t=>{
                if(t.start>at) frag.appendChild(document.createTextNode(text.slice(at,t.start)));
                const n=wfMap.get(t.key)||0;
                const col=wfColor(n,max);
                const s=document.createElement('span');
                s.className='wf'+(col.t>=.75?' top':col.t>=.45?' hot':'')
                            +(wfPick===t.key?' pick':'');
                s.dataset.k=t.key;
                s.style.color=col.c;
                s.style.fontWeight=col.w;
                s.title=`'${wfStats.find(x=>x.key===t.key)?.word||t.raw}' · ${n}번 나옴`;
                s.textContent=text.substr(t.start,t.len);
                frag.appendChild(s);
                at=t.start+t.len;
            });
            if(at<text.length) frag.appendChild(document.createTextNode(text.slice(at)));
            tn.parentNode.replaceChild(frag,tn);
        });
    }
    // 특정 낱말만 노랗게 집어내기
    function wfPickWord(key){
        if(!wfOn) wfRun();
        wfPick=(wfPick===key)?null:key;
        document.querySelectorAll('.wf').forEach(s=>
            s.classList.toggle('pick', !!wfPick && s.dataset.k===wfPick));
        if(sidePanel==='words') renderPanel();
        if(wfPick){
            const first=document.querySelector(`.wf.pick`);
            if(first){
                const wrap=first.closest('.page-wrap');
                const pi=wrap?+wrap.dataset.pageIdx:curPageIdx;
                goToPage(pi+1);
            }
            const s=wfStats.find(x=>x.key===wfPick);
            if(s) toast(`'${s.word}' · 문서에서 ${s.n}번 나왔습니다`,2400);
        }
    }
    // 최소 등장 횟수 조절
    function wfSetMin(v){
        wfMin=Math.max(1,Math.min(9,v));
        wfBuildLevels();
        if(wfOn){ wfClear(); wfPaint(); renderPanel(); }
        const lb=document.getElementById('wfMinLbl');
        if(lb) lb.textContent=wfMin+'번';
    }
    // ---------- 패널 ----------
    function panelWords(){
        if(!doc) return '';
        if(!wfStats.length) wfAnalyze();
        const list=wfStats.filter(s=>s.n>=wfMin);
        const max=wfStats.length?wfStats[0].n:1;
        let html=`<div class="wf-top">
                    <button class="wf-toggle${wfOn?' on':''}" onclick="toggleWordFreq()">
                      <i class="ri-${wfOn?'eye-off-line':'contrast-2-line'}"></i>${wfOn?'색칠 끄기':'색칠하기'}</button>
                    <span class="wf-min">
                      <button class="sp-mini" onclick="wfSetMin(wfMin-1)">−</button>
                      <b>${wfMin}</b>번↑
                      <button class="sp-mini" onclick="wfSetMin(wfMin+1)">＋</button>
                    </span>
                  </div>`;
        if(!list.length)
            return html+'<div class="sp-empty">여러 번 나온 낱말이 없습니다</div>';
        list.slice(0,60).forEach((s,i)=>{
            const col=wfColor(s.n,max);
            html+=`<div class="wf-item${wfPick===s.key?' on':''}" onclick="wfPickWord('${s.key}')">
                     <span class="bar" style="width:${Math.max(6,(s.n/max)*100)}%"></span>
                     <span class="wf-rank">${i+1}</span>
                     <span class="w" style="color:${col.c};font-weight:${col.w}">${esc(s.word)}</span>
                     <span class="c">${s.n}</span>
                   </div>`;
        });
        if(list.length>60) html+=`<div class="sp-item sp-dim">… 외 ${list.length-60}개</div>`;
        return html;
    }

    function openTableModal(){
        const v=prompt('표 크기를 입력하세요 (행 x 열)','3 x 3');
        if(!v) return;
        const m=String(v).match(/(\d+)\s*[x\u00d7,\s]\s*(\d+)/);
        if(!m){ toast('예: 3 x 4 형식으로 입력해 주세요',2200); return; }
        beginTablePlacement(+m[1],+m[2]);
    }
    function beginTablePlacement(rows,cols){
        const dim=tableInsertSize(rows,cols),g=document.getElementById('tableGhost');
        setTextTool(false);
        if(penActive) finishDrawing();
        cancelPlaceMode();
        tablePlace=dim;
        if(!g) return;
        g.style.setProperty('--tbl-rows',dim.rows);
        g.style.setProperty('--tbl-cols',dim.cols);
        g.style.display='block';
        const lb=document.getElementById('tableGhostLabel');
        if(lb) lb.textContent=dim.rows+' × '+dim.cols+' 표';
        document.body.classList.add('placing-table');
        const p=paperAt(curPageIdx),r=p&&p.getBoundingClientRect();
        moveTableGhost(r?r.left+r.width/2:innerWidth/2,
                       r?r.top+Math.min(r.height*.25,200):innerHeight/2);
        toast('종이에서 원하는 위치를 눌러 표를 배치하세요',2200);
    }
    function moveTableGhost(clientX,clientY){
        const g=document.getElementById('tableGhost'); if(!g||!tablePlace) return;
        // 포인터 아래 종이의 실제 화면 배율을 사용한다. 브라우저 90% zoom이나
        // 사용자 확대 상태에서도 클릭 후 만들어지는 표와 픽셀 단위로 일치한다.
        const hit=typeof document.elementFromPoint==='function'
            ?document.elementFromPoint(clientX,clientY):null;
        const paper=(hit&&hit.closest&&hit.closest('.paper'))||paperAt(curPageIdx);
        if(!paper) return;
        const pi=+paper.dataset.pageIdx;
        const p=pageLocal({clientX,clientY},pi);
        const origin=clampTableOrigin(tablePlace,p.x-tablePlace.w/2,p.y-tablePlace.h/2);
        const r=paper.getBoundingClientRect(),sc=uiPageScale(pi),k=uiCssZoom();
        g.style.width=Math.round(tablePlace.w*sc.x)+'px';
        g.style.height=Math.round(tablePlace.h*sc.y)+'px';
        // 종이 원점(화면 px)도 고스트가 쓰는 CSS px 로 바꾼 뒤 문서 좌표를 더한다.
        g.style.left=Math.round(r.left/k+origin.x*sc.x)+'px';
        g.style.top=Math.round(r.top/k+origin.y*sc.y)+'px';
        g.dataset.pageIdx=String(pi);
    }
    // 텍스트 상자 고스트 — '눌렀을 때 실제로 생길 자리'를 그대로 미리 보인다.
    // 삽입 경로(pageLocal → clampEl → addTextBox)와 같은 계산을 쓰기 때문에
    // 배율이 몇 %이든, 커서가 종이 어디에 있든 고스트 = 만들어질 상자 다.
    // 예전엔 커서 clientX 를 곧장 style.left 에 넣고 화면 가장자리로 clamp 해서
    //  · 사이트 기본 배율(90%) 만큼 커서에서 어긋나고
    //  · 확대가 클수록 화면 끝에서 고스트만 안으로 밀려
    // 만들어진 상자와 고스트가 서로 다른 자리에 있었다.
    function moveTextGhost(clientX,clientY){
        const g=document.getElementById('textGhost'); if(!g||!textToolActive) return;
        const hit=typeof document.elementFromPoint==='function'
            ?document.elementFromPoint(clientX,clientY):null;
        const over=hit&&hit.closest&&hit.closest('.paper');
        const paper=over||paperAt(curPageIdx);
        if(!paper) return;
        const pi=+paper.dataset.pageIdx, s=paperSize();
        // 종이 밖(도구막대 위 등)에서는 지금 쪽 위쪽 중앙에 '준비' 미리보기를 둔다.
        const p=over?pageLocal({clientX,clientY},pi):{x:s.w/2,y:Math.min(s.h*.22,180)};
        const o=clampEl(p.x-TB_W/2,p.y-TB_H/2,TB_W,TB_H);
        const r=paper.getBoundingClientRect(),sc=uiPageScale(pi),k=uiCssZoom();
        g.style.width=Math.round(TB_W*sc.x)+'px';
        g.style.height=Math.round(TB_H*sc.y)+'px';
        const c=g.querySelector('.tg-caret');
        if(c) c.style.height=Math.round((curFontSize*1.4)*sc.y)+'px';
        g.style.left=Math.round(r.left/k+o.x*sc.x)+'px';
        g.style.top=Math.round(r.top/k+o.y*sc.y)+'px';
        g.dataset.pageIdx=String(pi);
    }
    function cancelTablePlacement(){
        tablePlace=null;
        const g=document.getElementById('tableGhost'); if(g) g.style.display='none';
        document.body.classList.remove('placing-table');
    }

    // ============ 요소 배치 모드 (그림·수식) ============
    // 예전엔 텍스트 상자·표만 '누른 자리 = 생기는 자리' 보정(pageLocal)이 돼 있었고
    //  · 그림은 도구막대에서 넣으면 늘 쪽 한가욵데에,
    //  · 수식은 마우스가 마지막으로 스쳐 지나간 자리(오래된 lastMouse)에 들어갔다.
    // 사이트 기본 배율(html zoom 90%) 아래서는 기준점과 결과의 단위가 엇갈려
    // '커서보다 한 뼘(≈1cm) 오른쪽에 생긴다'고 느껴지던 것의 실제 원인이다.
    // 그림·수식도 상자·표와 같은 방식으로 바꾼다: 커서를 따라다니는 고스트를
    // 문서 좌표로 그리고(moveTextGhost 와 같은 변환), 누른 그 지점에 똑같이 넣는다.
    let placeMode=null;   // {kind:'image',items:[{file,url,box}],idx,w,h}
                          // {kind:'latex',src,display,fontSize,w,h}
    function beginImgPlacement(items){
        if(!items||!items.length) return;
        cancelPlaceMode();
        if(penActive) finishDrawing();
        setTextTool(false); if(tablePlace) cancelTablePlacement();
        if(pinMode) togglePinMode();
        deselectAll();
        placeMode={kind:'image',items,idx:0,w:items[0].box.w,h:items[0].box.h};
        placeGhostShow();
        toast(items.length>1
            ? `종이를 눌러 그림을 차례로 배치하세요 (총 ${items.length}장)`
            : '종이에서 원하는 위치를 눌러 그림을 배치하세요',2200);
    }
    function beginLatexPlacement(src,display){
        cancelPlaceMode();
        if(penActive) finishDrawing();
        setTextTool(false); if(tablePlace) cancelTablePlacement();
        if(pinMode) togglePinMode();
        deselectAll();
        placeMode={kind:'latex',src,display,
            w:display?400:230, h:display?82:48, fontSize:display?22:18};
        placeGhostShow();
        toast('종이에서 원하는 위치를 눌러 수식을 배치하세요',2200);
    }
    function placeGhostShow(){
        const pm=placeMode, g=document.getElementById('placeGhost');
        if(!pm||!g) return;
        const body=document.getElementById('placeGhostBody');
        const ic=document.getElementById('placeGhostIcon'), lb=document.getElementById('placeGhostLabel');
        if(pm.kind==='image'){
            const it=pm.items[pm.idx];
            pm.w=it.box.w; pm.h=it.box.h;
            if(ic) ic.className='ri-image-add-line';
            if(lb) lb.textContent=pm.items.length>1?`그림 ${pm.idx+1}/${pm.items.length}`:'그림 넣기';
            body.innerHTML=`<div class="pg-scale" style="width:${it.box.w}px;height:${it.box.h}px;`+
                `background-image:url('${it.url}')"></div>`;
        }else{
            if(ic) ic.className='ri-function-line';
            if(lb) lb.textContent='수식 넣기';
            body.innerHTML=`<div class="pg-scale pg-latex" style="width:${pm.w}px;height:${pm.h}px;`+
                `font-size:${pm.fontSize}px;line-height:1.05">${latexHTML(pm.src,pm.display)}</div>`;
        }
        g.style.display='block';
        document.body.classList.add('placing-el');
        // 첫 위치: 현재 쪽 위쪽 중앙 (상자·표 고스트와 같은 규칙)
        const p=paperAt(curPageIdx), r=p&&p.getBoundingClientRect();
        movePlaceGhost(r?r.left+r.width/2:innerWidth/2,
                       r?r.top+Math.min(r.height*.22,200):innerHeight/3);
    }
    function movePlaceGhost(clientX,clientY){
        const g=document.getElementById('placeGhost'); if(!g||!placeMode) return;
        // moveTextGhost 와 같은 변환: 포인터 아래 종이의 실제 화면 사각형을 기준으로
        // 문서 좌표를 구하고, 고스트는 화면 UI CSS px 로 놓는다. 배율이 몇 %이든
        // 고스트 = 만들어질 요소 다.
        const hit=typeof document.elementFromPoint==='function'
            ?document.elementFromPoint(clientX,clientY):null;
        const over=hit&&hit.closest&&hit.closest('.paper');
        const paper=over||paperAt(curPageIdx);
        if(!paper) return;
        const pi=+paper.dataset.pageIdx, s=paperSize();
        const p=over?pageLocal({clientX,clientY},pi):{x:s.w/2,y:Math.min(s.h*.22,180)};
        const o=clampEl(p.x-placeMode.w/2,p.y-placeMode.h/2,placeMode.w,placeMode.h);
        const r=paper.getBoundingClientRect(),sc=uiPageScale(pi),k=uiCssZoom();
        g.style.width=Math.round(placeMode.w*sc.x)+'px';
        g.style.height=Math.round(placeMode.h*sc.y)+'px';
        g.style.left=Math.round(r.left/k+o.x*sc.x)+'px';
        g.style.top=Math.round(r.top/k+o.y*sc.y)+'px';
        g.dataset.pageIdx=String(pi);
        const inner=g.querySelector('.pg-scale');
        if(inner) inner.style.transform=`scale(${sc.x})`;
    }
    // 배치 모드에서 종이를 눌렀다 — 미리보기와 똑같은 문서 좌표에 넣는다.
    function commitPlaceAt(pi,x,y){
        const pm=placeMode; if(!pm) return;
        if(pm.kind==='image'){
            const it=pm.items[pm.idx];
            if(it) placeImgItem(it,pi,x,y);
            pm.idx++;
            saveDoc(); runUploadQueue();
            if(pm.idx>=pm.items.length){ cancelPlaceMode(); toast('그림을 넣었습니다',1300); }
            else placeGhostShow();      // 다음 장 크기·미리보기로 교체
            return;
        }
        if(pm.kind==='latex'){
            pushHistory();
            const c=clampEl(x-pm.w/2,y-pm.h/2,pm.w,pm.h);
            doc.pages[pi].els.push({type:'latex',id:uid('m'),latex:pm.src,
                x:Math.round(c.x),y:Math.round(c.y),w:pm.w,h:pm.h,
                fontSize:pm.fontSize,displayMath:pm.display?1:0});
            if(renderedPages.has(pi)) renderPageEls(pi);
            saveDoc(); cancelPlaceMode(); toast('수식을 넣었습니다',1300);
            return;
        }
        cancelPlaceMode();
    }
    function cancelPlaceMode(){
        if(!placeMode) return;
        // 아직 배치하지 않은 그림의 로컬 미리보기 URL 은 주인이 없으니 돌려준다.
        if(placeMode.kind==='image'&&placeMode.items){
            placeMode.items.slice(placeMode.idx).forEach(it=>{ try{ URL.revokeObjectURL(it.url); }catch(e){} });
        }
        placeMode=null;
        const g=document.getElementById('placeGhost');
        if(g){ g.style.display='none'; const b=document.getElementById('placeGhostBody'); if(b) b.innerHTML=''; }
        document.body.classList.remove('placing-el');
    }

    function toggleTextTool(){ setTextTool(!textToolActive); }
    function setTextTool(on){
        textToolActive=!!on;
        if(on&&tablePlace) cancelTablePlacement();
        if(on) cancelPlaceMode();
        if(on&&penActive) finishDrawing();
        const g=document.getElementById('textGhost');
        g.style.display=on?'block':'none';
        document.body.classList.toggle('placing-text',!!on);
        document.getElementById('textToolBtn').classList.toggle('active',on);
        if(on){
            // 마우스를 아직 움직이지 않아도 현재 종이 위쪽 중앙에 미리보기를 보인다.
            // (좌표는 화면 px → 아래 moveTextGhost 가 문서 좌표로 바꿔 똑같이 놓는다)
            const p=paperAt(curPageIdx), r=p&&p.getBoundingClientRect();
            moveTextGhost(r?r.left+r.width/2:(lastMouse.clientX||innerWidth/2),
                          r?r.top+Math.min(r.height*.22,180):(lastMouse.clientY||innerHeight/2));
        }
    }
    // 배율이 바뀌면 고스트를 '지금 커서 자리'에 크기와 위치 모두 다시 맞춘다.
    // 예전엔 pageScale 로 크기만 다시 쟀다 — 위치는 clientX 를 그대로 style.left 에
    // 넣어 둔 값이라 배율 전환 뒤에도 어긋난 채로 남아 있었다.
    function sizeTextGhost(){
        if(textToolActive) moveTextGhost(lastMouse.clientX||0,lastMouse.clientY||0);
        if(tablePlace) moveTableGhost(lastMouse.clientX||0,lastMouse.clientY||0);
        if(placeMode) movePlaceGhost(lastMouse.clientX||0,lastMouse.clientY||0);
    }
    const TB_W=200, TB_H=48;

    // ============ 뒤로가기(브라우저 히스토리) 처리 ============
    // 에디터·폴더·모달을 열 때 히스토리 항목을 쌓아, 뒤로가기를 누르면
    // 사이트를 빠져나가는 대신 열려 있던 화면/모달이 닫히게 한다.
    const _nav=[];
    function openNav(close){ _nav.push({close}); try{ history.pushState({sdy:_nav.length},''); }catch(e){} }
    function navDrop(close){ const i=_nav.findIndex(x=>x.close===close); if(i>=0) _nav.splice(i,1); }
    function navBack(){
        if(!_nav.length) return;
        try{ history.back(); }
        catch(e){ const it=_nav.pop(); if(it&&it.close){ try{ it.close(); }catch(err){} } }
    }
    window.addEventListener('popstate',(e)=>{
        const target=(e.state&&typeof e.state.sdy==='number')?e.state.sdy:0;
        while(_nav.length>target){
            const it=_nav.pop();
            if(it&&it.close){ try{ it.close(); }catch(err){} }
        }
    });
    // 열려 있는 것 중 가장 위를 닫는다 (Esc / 뒤로가기 공용). 닫았으면 true.
    function closeTopOverlay(){
        if(ctxMenuOpen()){ closeCtxMenu(); return true; }
        if(presentOn){ endPresent(); return true; }
        if(wfOn){ wfOff(); return true; }
        if(document.getElementById('pinPop').classList.contains('show')){ closePin(); return true; }
        if(document.getElementById('latexModal').style.display==='flex'){ closeLatexModal(); return true; }
        if(pinMode){ togglePinMode(); return true; }
        if(findOpen){ closeFind(); return true; }
        if(tablePlace){ cancelTablePlacement(); return true; }
        if(placeMode){ cancelPlaceMode(); return true; }
        if(activeTbl){ clearActiveTbl(); return true; }
        if(focusMode){ toggleFocus(); return true; }
        if(sidePanel){ closePanel(); return true; }
        if(document.getElementById('viewer').style.display==='flex'){document.getElementById('viewer').style.display='none';return true;}
        if(textToolActive){ setTextTool(false); return true; }
        if(penActive){ finishDrawing(); return true; }
        // 변환 중에는 닫지 않는다
        if(document.getElementById('importProg').style.display==='flex') return false;
        // 주요 모달·에디터는 히스토리와 함께 닫는다 (뒤로가기와 일관)
        if(document.getElementById('cpModal').style.display==='flex'){ navBack(); return true; }
        if(document.getElementById('exportModal').style.display==='flex'){ navBack(); return true; }
        if(document.getElementById('pwModal').style.display==='flex'){ navBack(); return true; }
        if(document.getElementById('createModal').style.display==='flex'){ navBack(); return true; }
        if(document.getElementById('vaultModal').style.display==='flex'){ navBack(); return true; }
        if(document.getElementById('folderStyleModal').style.display==='flex'){ navBack(); return true; }
        if(document.getElementById('keyModal').style.display==='flex'){ navBack(); return true; }
        if(document.getElementById('delModal').style.display==='flex'){ navBack(); return true; }
        if(document.getElementById('setModal').style.display==='flex'){ navBack(); return true; }
        if(document.getElementById('stickerModal').style.display==='flex'){ navBack(); return true; }
        if(document.getElementById('infoModal').style.display==='flex'){ navBack(); return true; }
        if(document.getElementById('trashModal').style.display==='flex'){ navBack(); return true; }
        if(document.getElementById('editorView').classList.contains('open')){ navBack(); return true; }
        if(curFolder){ openFolder(folderParent(curFolder), true); return true; }
        return false;
    }

    document.addEventListener('keydown',e=>{
        // 발표 모드 조작
        if(presentOn){
            if(e.key==='ArrowRight'||e.key===' '||e.key==='PageDown'){ e.preventDefault(); presentStep(1); return; }
            if(e.key==='ArrowLeft'||e.key==='PageUp'){ e.preventDefault(); presentStep(-1); return; }
            if(e.key==='Escape'){ e.preventDefault(); endPresent(); return; }
        }
        if(e.ctrlKey&&!e.shiftKey&&(e.key==='h'||e.key==='H')){
            if(document.getElementById('editorView').classList.contains('open')){
                e.preventDefault();
                if(!findOpen) openFind();
                const bar=document.getElementById('findBar');
                if(!bar.classList.contains('rep')) toggleReplace();
                else document.getElementById('repInput').focus();
                return;
            }
        }
        if(e.ctrlKey&&e.shiftKey&&(e.key==='c'||e.key==='C')){
            if(document.getElementById('editorView').classList.contains('open')){
                e.preventDefault(); countSelection(); return;
            }
        }
        if(e.ctrlKey&&!e.shiftKey&&(e.key==='f'||e.key==='F')){
            if(document.getElementById('editorView').classList.contains('open')){
                e.preventDefault(); openFind(); return;
            }
        }
        // ===== 스프레드시트식: 편집 중 Enter/Tab/Escape (커밋 + 셀 이동) =====
        if(document.querySelector('.tb.edit') && document.activeElement
           && document.activeElement.classList
           && document.activeElement.classList.contains('tb-content')){
            const w=document.activeElement.closest('.tb');
            // 한글 IME 조합 중에는 Enter(확정)를 가로채면 입력이 깨진다 → 그대로 둠
            const composing=e.isComposing||e.keyCode===229;
            if(w){
                if(e.key==='Tab' && !composing){
                    e.preventDefault();
                    exitEditKeepSel(w);
                    moveCellFrom(w, e.shiftKey?'prev':'next');
                    return;
                }
                if(e.key==='Escape' && !composing){
                    e.preventDefault();
                    exitEditKeepSel(w);
                    return;
                }
            }
        }
        if(e.key==='Escape'){
            if(closeTopOverlay()) return;
        }
        // 표 셀 범위: 방향키로 이동, Shift+방향키로 직사각형 확장.
        // Delete는 표 전체를 제거하고 Backspace는 선택한 칸의 내용만 비운다.
        if(tblCellSelection&&!document.querySelector('.tb.edit')&&doc
           &&document.getElementById('editorView').classList.contains('open')
           &&!/^(INPUT|TEXTAREA|SELECT)$/.test((document.activeElement||{}).tagName||'')){
            const dirs={ArrowLeft:[0,-1],ArrowRight:[0,1],ArrowUp:[-1,0],ArrowDown:[1,0]};
            if(dirs[e.key]){
                e.preventDefault(); moveTblCellSelection(dirs[e.key][0],dirs[e.key][1],e.shiftKey); return;
            }
            if(e.key==='Tab'){
                e.preventDefault();
                const s=tblCellSelection,t=findTbl(s.pageIdx,s.tid),n=t&&t.cw.length;
                if(t&&n){
                    const total=t.ch.length*n;
                    const at=Math.max(0,Math.min(total-1,s.r1*n+s.c1+(e.shiftKey?-1:1)));
                    s.r0=s.r1=Math.floor(at/n); s.c0=s.c1=at%n;
                    setActiveTbl(s.pageIdx,s.tid,s.r1,s.c1); paintTblCellSelection();
                }
                return;
            }
            if(e.key==='Enter'||e.key==='F2'){ e.preventDefault(); editTblSelectionCell(); return; }
            if(e.key==='Delete'){
                e.preventDefault();
                const s=tblCellSelection;
                tblDelAll(true,s.tid,s.pageIdx);
                return;
            }
            if(e.key==='Backspace'){ e.preventDefault(); clearTblCellContents(); return; }
        }
        // 단축키 도움말
        // 사용법은 설정에서만 연다 (노트 안에서는 뜨지 않음)
        if((e.key==='?'||e.key==='F1')
           && !document.getElementById('editorView').classList.contains('open')
           && !/^(INPUT|TEXTAREA|SELECT)$/.test((document.activeElement||{}).tagName||'')){
            e.preventDefault();
            document.getElementById('keyModal').style.display==='flex'?closeKeys():openKeys();
            return;
        }
        // 방향키: 단일 텍스트 상자 = 스프레드시트식 셀 이동, 그 외/Shift·Alt = 미세 이동
        if(/^Arrow(Up|Down|Left|Right)$/.test(e.key) && !document.querySelector('.tb.edit')
           && (selected||multiSel.length) && doc
           && document.getElementById('editorView').classList.contains('open')
           && !/^(INPUT|TEXTAREA|SELECT)$/.test((document.activeElement||{}).tagName||'')){
            const _curBox=currentSelText();
            if(_curBox && !e.shiftKey && !e.altKey){
                e.preventDefault();
                const _dir={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down'}[e.key];
                const _nb=nearestBox(_curBox,_dir);
                if(_nb){ selectTextBoxById(_nb.pi,_nb.id); try{_nb.node.scrollIntoView({block:'nearest'});}catch(_e){} }
                return;
            }
            e.preventDefault();
            const step=e.shiftKey?10:1;
            const dx=e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0;
            const dy=e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0;
            if(!nudgeTimer) pushHistory();
            clearTimeout(nudgeTimer);
            nudgeTimer=setTimeout(()=>{ nudgeTimer=null; saveDoc(); },500);
            const move=(id,pi,node)=>{
                const el=findEl(pi,id); if(!el) return;
                if(el.type==='stroke'){
                    el.dx=(el.dx||0)+dx; el.dy=(el.dy||0)+dy;
                    node.setAttribute('transform',`translate(${el.dx},${el.dy})`);
                }else{
                    const c=clampEl(el.x+dx,el.y+dy,el.w,el.h);
                    el.x=Math.round(c.x); el.y=Math.round(c.y);
                    node.style.left=el.x+'px'; node.style.top=el.y+'px';
                }
            };
            if(multiSel.length) multiSel.forEach(m=>move(m.id,m.pageIdx,m.node));
            else move(selected.el.dataset.id,+selected.el.dataset.pageIdx,selected.el);
            return;
        }
        // ===== 스프레드시트식: 셀 선택 상태에서 Tab/Enter/F2 =====
        if(!document.querySelector('.tb.edit') && doc
           && document.getElementById('editorView').classList.contains('open')
           && !/^(INPUT|TEXTAREA|SELECT)$/.test((document.activeElement||{}).tagName||'')){
            const curBox=currentSelText();
            if(curBox){
                if(e.key==='Tab'){
                    e.preventDefault();
                    const nb=nextBoxInOrder(curBox, e.shiftKey?-1:1);
                    if(nb){ selectTextBoxById(nb.pi,nb.id); try{nb.node.scrollIntoView({block:'nearest'});}catch(_e){} }
                    return;
                }
                if(e.key==='Enter' || e.key==='F2'){
                    e.preventDefault();
                    enterEdit(curBox.node, true);
                    return;
                }
            }
        }
        // 요소 복사 / 잘라내기 / 붙여넣기 / 복제
        if((e.ctrlKey||e.metaKey)&&!document.querySelector('.tb.edit')&&doc
           && document.getElementById('editorView').classList.contains('open')){
            const k=e.key.toLowerCase();
            // 텍스트가 드래그 선택돼 있으면 '글자 복사'가 우선 (요소 복사로 가로채지 않는다)
            const _sel=window.getSelection();
            const textPicked=_sel&&!_sel.isCollapsed&&String(_sel).trim().length>0
                             &&_sel.anchorNode&&_sel.anchorNode.parentElement
                             &&_sel.anchorNode.parentElement.closest('.tb-content');
            if((k==='c'||k==='x')&&textPicked){
                // 아래 copy 리스너가 '순수 글자'만 클립보드에 넣는다
                if(k==='c') setTimeout(()=>toast('텍스트 복사됨',1200),0);
                return;
            }
            // 텍스트 상자를 골라 Ctrl+C → 안의 '글자만' 선택한 순서대로 복사.
            // 상자 1개만 골랐을 때도 똑같이 글자를 준다 (예전엔 요소 복사로 빠졌다).
            if(k==='c'&&(multiSel.length||selected)){
                const _ms=selectedElsData();
                if(_ms.length&&_ms.every(x=>x.type==='text')){
                    e.preventDefault(); copySelectedTextAsText(_ms); return;
                }
            }
            if(k==='c'&&(selected||multiSel.length)){ e.preventDefault(); copyElements(false); return; }
            if(k==='x'&&(selected||multiSel.length)){ e.preventDefault(); copyElements(true);  return; }
            if(k==='j'&&(selected||multiSel.length)){e.preventDefault(); duplicateSelection();  return; }
            if(k==='a'){
                e.preventDefault(); selectAllOnPage(); return;
            }
        }
        // 표가 선택된 상태면 Delete 로 표 통째 삭제
        if((e.key==='Delete'||e.key==='Backspace')&&tblSelectedForDelete()
           && !/^(INPUT|TEXTAREA|SELECT)$/.test((document.activeElement||{}).tagName||'')){
            e.preventDefault(); tblDelAll(true); return;
        }
        if((e.key==='Delete'||e.key==='Backspace')&&multiSel.length&&!document.querySelector('.tb.edit')){
            e.preventDefault(); deleteMulti(); return;
        }
        if(e.key==='Escape'&&multiSel.length){ clearMulti(); return; }
        if((e.key==='Delete'||e.key==='Backspace')&&selected&&!document.querySelector('.tb.edit')){
            e.preventDefault();
            const lid=selected.el.dataset.id, lpi=+selected.el.dataset.pageIdx;
            const hel=findEl(lpi,lid);
            if(hel&&tblOf(hel)){
                tblDelAll(true, tblOf(hel), lpi);
                return;
            }
            if(isElLocked(lpi,lid)){ toast('잠긴 요소는 지울 수 없습니다',1800); return; }
            pushHistory();
            const id=lid, pi=lpi;
            const gone=(doc.pages[pi].els||[]).filter(x=>x.id===id);
            doc.pages[pi].els=doc.pages[pi].els.filter(x=>x.id!==id);
            selected.el.remove(); selected=null; saveDoc();
            purgeElements(gone);
        }
        if(e.ctrlKey&&(e.key==='s'||e.key==='S')){
            e.preventDefault();
            // input 디바운스(300ms)가 아직 끝나기 전에도 Ctrl+S는 현재
            // contenteditable 내용을 먼저 문서에 반영해야 한다.
            // 완료 전 '저장됨' 토스트를 띄우지 않고 flushSync의 실제 결과를 쓴다.
            if(doc){
                commitEditingText();
                flushSaveDoc();
                flushSync().catch(()=>{});
            }
            return;
        }
        if(e.ctrlKey&&(e.key==='d'||e.key==='D')){
            if(doc&&!document.querySelector('.tb.edit')){ e.preventDefault(); duplicatePage(); }
            return;
        }
        if(e.ctrlKey&&(e.key==='e'||e.key==='E')){
            if(doc){ e.preventDefault(); openExportModal(); }
            return;
        }
        if(e.ctrlKey&&(e.key==='p'||e.key==='P')){
            if(doc){ e.preventDefault(); exportPDF(); }
            return;
        }
        if(e.ctrlKey&&e.key==='Enter'){
            if(doc){ e.preventDefault(); addPage(); }
            return;
        }
        if((e.ctrlKey||e.metaKey)&&(e.key==='z'||e.key==='Z')){
            if(document.querySelector('.tb.edit')&&document.activeElement.classList.contains('tb-content')) return;
            e.preventDefault();
            if(e.shiftKey) redo(); else undo();
            return;
        }
        if((e.ctrlKey||e.metaKey)&&(e.key==='y'||e.key==='Y')){
            if(document.querySelector('.tb.edit')&&document.activeElement.classList.contains('tb-content')) return;
            e.preventDefault(); redo(); return;
        }
    });

    // ============ 펜 / 지우개 ============
    let penActive=false, eraserActive=false, drawColor='#111', drawSize=2;
    let shapeMode='free', markerMode=false;
    let drawing=false, curPts=null, curPathNode=null, drawPageIdx=0;
    const ERASER_MULT=6;   // 지우개 반경 = drawSize * ERASER_MULT

    function eraserRadius(){ return (drawSize*ERASER_MULT)/2; }

    function togglePen(){
        if(penActive){ finishDrawing(); return; }
        setTextTool(false);
        cancelPlaceMode();
        deselectAll();
        penActive=true;
        document.getElementById('penBtn').classList.add('active');
        document.getElementById('drawToolbar').style.display='flex';
        editorPapers().forEach(p=>p.classList.add('drawing'));
        updateToolCursor();
    }
    function finishDrawing(){
        penActive=false; eraserActive=false; drawing=false;
        document.getElementById('penBtn').classList.remove('active');
        document.getElementById('eraserBtn').classList.remove('active');
        document.getElementById('drawToolbar').style.display='none';
        editorPapers().forEach(p=>p.classList.remove('drawing'));
        document.getElementById('toolCursor').style.display='none';
        saveDoc();
    }
    function setShape(m){
        shapeMode=m; eraserActive=false;
        document.getElementById('eraserBtn').classList.remove('active');
        document.querySelectorAll('.shp').forEach(b=>b.classList.remove('active'));
        const map={free:'shpFree',line:'shpLine',arrow:'shpArrow',rect:'shpRect',ellipse:'shpEllipse'};
        const b=document.getElementById(map[m]); if(b) b.classList.add('active');
        updateToolCursor();
    }
    function toggleMarker(){
        markerMode=!markerMode;
        document.getElementById('markerBtn').classList.toggle('active',markerMode);
        updateToolCursor();
        toast(markerMode?'형광펜 모드 (반투명·굵게)':'일반 펜',1200);
    }
    function setDrawColorVal(v){
        drawColor=v; eraserActive=false;
        document.querySelectorAll('.color-pick').forEach(c=>c.classList.remove('sel'));
        document.getElementById('eraserBtn').classList.remove('active');
        updateToolCursor();
    }
    function setDrawColor(el){
        drawColor=el.dataset.c; eraserActive=false;
        const pc=document.getElementById('penCustom'); if(pc) pc.value=el.dataset.c;
        document.querySelectorAll('.color-pick').forEach(c=>c.classList.remove('sel'));
        el.classList.add('sel');
        document.getElementById('eraserBtn').classList.remove('active');
        updateToolCursor();
    }
    function setDrawSize(el){
        drawSize=+el.dataset.s;
        document.querySelectorAll('.size-opt').forEach(s=>s.classList.remove('sel'));
        el.classList.add('sel');
        updateToolCursor();
    }
    function toggleEraser(){
        eraserActive=!eraserActive;
        document.getElementById('eraserBtn').classList.toggle('active',eraserActive);
        updateToolCursor();
    }

    // 펜촉/지우개 크기를 화면 배율에 맞춰 '실제 크기' 그대로 표시
    function updateToolCursor(){
        const tc=document.getElementById('toolCursor');
        if(!penActive){ tc.style.display='none'; return; }
        const d=(eraserActive? eraserRadius()*2 : drawSize)*pageScale;
        const px=Math.max(eraserActive?10:4, d);
        tc.style.width=px+'px'; tc.style.height=px+'px';
        tc.className='tool-cursor '+(eraserActive?'eraser':'pen');
        // 펜에서 설정한 인라인 색이 지우개에 남지 않도록 매번 초기화
        if(eraserActive){ tc.style.background=''; tc.style.borderColor=''; }
        else { tc.style.background=hexA(drawColor,.35); tc.style.borderColor=drawColor; }
        tc.querySelector('.dot').style.display=(!eraserActive&&px<6)?'block':'none';
        tc.style.display='block';
    }
    function hexA(hex,a){
        const h=hex.replace('#',''); const f=h.length===3?h.split('').map(c=>c+c).join(''):h;
        const n=parseInt(f,16);
        return `rgba(${(n>>16)&255},${(n>>8)&255},${n&255},${a})`;
    }
    const _toolCursorMove=('PointerEvent' in window)?'pointermove':'mousemove';
    document.addEventListener(_toolCursorMove,e=>{
        if(!penActive) return;
        const points=typeof e.getCoalescedEvents==='function'?e.getCoalescedEvents():null;
        const p=points&&points.length?points[points.length-1]:e;
        const tc=document.getElementById('toolCursor');
        // left/top을 계속 바꾸면 레이아웃이 매번 다시 계산되어 고주사율 포인터가
        // 버벅였다. 최신 좌표만 GPU transform 변수로 넘긴다.
        tc.style.setProperty('--cursor-x',uiCss(p.clientX)+'px');
        tc.style.setProperty('--cursor-y',uiCss(p.clientY)+'px');
    },{passive:true});

    function surfacePos(e,pageIdx){
        const t=(e.touches&&e.touches[0])?e.touches[0]:e;
        return pageLocal(t,pageIdx);
    }

    let shapeStart=null;
    function effSize(){ return markerMode? drawSize*4 : drawSize; }
    function effOpacity(){ return markerMode? 0.4 : 1; }

    function drawStart(e,pageIdx){
        if(!penActive) return;
        e.preventDefault();
        curPageIdx=pageIdx; updatePageInfo();
        drawPageIdx=pageIdx;
        const p=surfacePos(e,pageIdx);
        if(eraserActive){ drawing=true; lastErase=null; eraseSweep(p,pageIdx); return; }
        pushHistory();
        drawing=true;
        shapeStart={x:round1(p.x),y:round1(p.y)};
        curPts=[[round1(p.x),round1(p.y)]];
        const svg=paperAt(pageIdx).querySelector('.layer-stroke');
        curPathNode=document.createElementNS('http://www.w3.org/2000/svg','path');
        curPathNode.setAttribute('fill','none');
        curPathNode.setAttribute('stroke',drawColor);
        curPathNode.setAttribute('stroke-width',effSize());
        curPathNode.setAttribute('stroke-opacity',effOpacity());
        curPathNode.setAttribute('stroke-linecap','round');
        curPathNode.setAttribute('stroke-linejoin','round');
        svg.appendChild(curPathNode);
    }
    function drawMove(e){
        if(!drawing||!penActive) return;
        e.preventDefault();
        const p=surfacePos(e,drawPageIdx);
        if(eraserActive){ eraseSweep(p,drawPageIdx); return; }
        if(shapeMode!=='free'){
            // 도형: 시작점~현재점으로 매번 다시 계산
            curPts=shapePoints(shapeStart,{x:round1(p.x),y:round1(p.y)},shapeMode,e.shiftKey);
            curPathNode.setAttribute('d',strokePath(curPts,shapeMode!=='ellipse'));
            return;
        }
        const last=curPts[curPts.length-1];
        if(Math.abs(p.x-last[0])<0.7&&Math.abs(p.y-last[1])<0.7) return;
        curPts.push([round1(p.x),round1(p.y)]);
        curPathNode.setAttribute('d',strokePath(curPts));
    }
    function drawEnd(){
        lastErase=null;
        if(!drawing) return;
        drawing=false;
        if(eraserActive){ saveDoc(); return; }
        if(!curPts||curPts.length<1){ if(curPathNode)curPathNode.remove(); return; }
        const el={type:'stroke',id:uid('s'),pts:curPts,color:drawColor,size:effSize(),dx:0,dy:0};
        if(markerMode) el.opacity=0.4;
        if(shapeMode!=='free') el.sharp=1;
        doc.pages[drawPageIdx].els.push(el);
        if(curPathNode) curPathNode.remove();
        const svg=paperAt(drawPageIdx).querySelector('.layer-stroke');
        svg.appendChild(buildStrokeEl(el,drawPageIdx));
        curPts=null; curPathNode=null;
        saveDoc();
    }
    function round1(v){ return Math.round(v*10)/10; }

    // 도형을 점 배열로 (스트로크 모델을 그대로 재사용 → 선택/이동/내보내기 전부 호환)
    function shapePoints(a,b,mode,shift){
        let x2=b.x, y2=b.y;
        if(shift){
            if(mode==='line'||mode==='arrow'){
                const dx=x2-a.x, dy=y2-a.y;
                if(Math.abs(dx)>Math.abs(dy)) y2=a.y; else x2=a.x;
            }else{
                const d=Math.max(Math.abs(x2-a.x),Math.abs(y2-a.y));
                x2=a.x+Math.sign(x2-a.x||1)*d;
                y2=a.y+Math.sign(y2-a.y||1)*d;
            }
        }
        const r=v=>Math.round(v*10)/10;
        if(mode==='line') return [[a.x,a.y],[r(x2),r(y2)]];
        if(mode==='arrow'){
            const ang=Math.atan2(y2-a.y,x2-a.x);
            const L=Math.max(9,Math.min(22,Math.hypot(x2-a.x,y2-a.y)*0.22));
            const p1=[r(x2-L*Math.cos(ang-0.42)), r(y2-L*Math.sin(ang-0.42))];
            const p2=[r(x2-L*Math.cos(ang+0.42)), r(y2-L*Math.sin(ang+0.42))];
            return [[a.x,a.y],[r(x2),r(y2)],p1,[r(x2),r(y2)],p2];
        }
        if(mode==='rect') return [[a.x,a.y],[r(x2),a.y],[r(x2),r(y2)],[a.x,r(y2)],[a.x,a.y]];
        if(mode==='ellipse'){
            const cx=(a.x+x2)/2, cy=(a.y+y2)/2, rx=Math.abs(x2-a.x)/2, ry=Math.abs(y2-a.y)/2;
            const pts=[];
            for(let i=0;i<=36;i++){
                const t=i/36*Math.PI*2;
                pts.push([r(cx+rx*Math.cos(t)), r(cy+ry*Math.sin(t))]);
            }
            return pts;
        }
        return [[a.x,a.y],[r(x2),r(y2)]];
    }

    // 지우개: 획 단위로 지움 (반경 안에 닿은 획 제거)
    // 점(px,py) 과 선분 (ax,ay)-(bx,by) 사이의 최단거리 제곱
    function distSqToSeg(px,py,ax,ay,bx,by){
        const vx=bx-ax, vy=by-ay;
        const wx=px-ax, wy=py-ay;
        const len2=vx*vx+vy*vy;
        let t = len2>0 ? (wx*vx+wy*vy)/len2 : 0;
        t = t<0?0 : t>1?1 : t;
        const dx=px-(ax+t*vx), dy=py-(ay+t*vy);
        return dx*dx+dy*dy;
    }
    // 지우개 원이 획과 실제로 겹치는가 (선분 단위로 검사)
    function eraserHitsStroke(el,p,r){
        const ox=el.dx||0, oy=el.dy||0;
        const pts=el.pts||[];
        if(!pts.length) return false;
        const reach=r+(el.size||1)/2;
        const reach2=reach*reach;
        if(pts.length===1){
            const dx=pts[0][0]+ox-p.x, dy=pts[0][1]+oy-p.y;
            return dx*dx+dy*dy<=reach2;
        }
        // 점 사이가 아무리 멀어도(직선 = 점 2개) 중간에서 지워지도록 선분으로 판정
        for(let i=0;i<pts.length-1;i++){
            const a=pts[i], b=pts[i+1];
            if(distSqToSeg(p.x,p.y, a[0]+ox,a[1]+oy, b[0]+ox,b[1]+oy)<=reach2) return true;
        }
        // 닫힌 도형(사각형/원)은 마지막→처음 변도 검사
        if(el.shape==='rect'||el.shape==='ellipse'||el.closed){
            const a=pts[pts.length-1], b=pts[0];
            if(distSqToSeg(p.x,p.y, a[0]+ox,a[1]+oy, b[0]+ox,b[1]+oy)<=reach2) return true;
        }
        return false;
    }
    // 마우스를 빨리 움직이면 이벤트 사이가 비어 '안 지워지는' 구간이 생긴다.
    // 이전 지점과 현재 지점 사이를 촘촘히 훑어서 지운다.
    let lastErase=null;
    function eraseSweep(p,pageIdx){
        const r=eraserRadius();
        const q=lastErase;
        if(q){
            const dx=p.x-q.x, dy=p.y-q.y;
            const dist=Math.hypot(dx,dy);
            const step=Math.max(2,r*0.7);
            const nSteps=Math.min(120,Math.ceil(dist/step));
            for(let i=1;i<nSteps;i++){
                eraseAt({x:q.x+dx*i/nSteps, y:q.y+dy*i/nSteps}, pageIdx);
            }
        }
        eraseAt(p,pageIdx);
        lastErase={x:p.x,y:p.y};
    }

    function eraseAt(p,pageIdx){
        const r=eraserRadius();
        const els=doc.pages[pageIdx].els||[];
        let removed=false;
        for(let i=els.length-1;i>=0;i--){
            const el=els[i];
            if(el.type!=='stroke') continue;
            if(eraserHitsStroke(el,p,r)){
                els.splice(i,1);
                const g=paperAt(pageIdx).querySelector(`.stroke-g[data-id="${el.id}"]`);
                if(g) g.remove();
                removed=true;
            }
        }
        if(removed&&!eraseAt._h){ pushHistory(); eraseAt._h=true; setTimeout(()=>eraseAt._h=false,400); }
    }

    // draw-surface 이벤트 위임
    document.addEventListener('mousedown',e=>{
        const s=e.target.closest('.draw-surface');
        if(s&&penActive) drawStart(e,+s.closest('.paper').dataset.pageIdx);
    },true);
    let _drawRaf=0, _drawEv=null;
    document.addEventListener('mousemove',e=>{
        if(!drawing) return;
        _drawEv=e;
        if(_drawRaf) return;
        _drawRaf=requestAnimationFrame(()=>{ _drawRaf=0; if(drawing&&_drawEv) drawMove(_drawEv); });
    },{passive:true});
    document.addEventListener('mouseup',()=>{ if(drawing) drawEnd(); });
    document.addEventListener('touchstart',e=>{
        if(e.touches&&e.touches.length>1) return;      // 두 손가락은 확대/축소용
        const s=e.target.closest&&e.target.closest('.draw-surface');
        if(s&&penActive) drawStart(e,+s.closest('.paper').dataset.pageIdx);
    },{passive:false});
    document.addEventListener('touchmove',e=>{
        if(e.touches&&e.touches.length>1){ if(drawing) drawEnd(); return; }
        if(drawing) drawMove(e);
    },{passive:false});
    document.addEventListener('touchend',()=>{ if(drawing) drawEnd(); });

    // ===== 두 손가락 확대/축소 (핀치 줌) =====
    // 예전엔 이 기능이 아예 없고 뷰포트도 user-scalable=no 라 모바일에서
    // 확대가 전혀 안 됐다. 손가락 사이 중점을 화면에 고정한 채 배율만 바꾼다.
    (function(){
        const body=document.getElementById('editorBody');
        const stage=document.getElementById('pagesStage');
        if(!body||!stage) return;
        let piv=null;
        const dist=t=>Math.hypot(t[0].clientX-t[1].clientX, t[0].clientY-t[1].clientY);
        const mid =t=>({x:(t[0].clientX+t[1].clientX)/2, y:(t[0].clientY+t[1].clientY)/2});

        body.addEventListener('touchstart',e=>{
            if(e.touches.length!==2) return;
            const m=mid(e.touches), r=body.getBoundingClientRect();
            piv={
                d0:dist(e.touches), z0:zoomPct,
                // 확대 기준점을 '문서 좌표'로 붙잡아 둔다
                cx:(body.scrollLeft+m.x-r.left)/pageScale,
                cy:(body.scrollTop +m.y-r.top )/pageScale,
                mx:m.x-r.left, my:m.y-r.top
            };
            try{ if(typeof deselectAll==='function') deselectAll(true); }catch(err){}
        },{passive:true});

        // 손가락을 움직이는 동안에는 '값싼' CSS 확대만 한다.
        // layoutPages() 는 쪽마다 DOM 을 만지므로 프레임마다 부르면
        // 손가락을 따라오지 못하고 굼떠 보인다 → 뗄 때 딱 한 번만 부른다.
        let raf=0, want=0;
        const apply=()=>{
            raf=0;
            const k=want/piv.z0;                       // 시작 배율 대비 비율
            stage.style.transformOrigin='0 0';
            stage.style.transform=`scale(${k})`;
            // 붙잡아 둔 지점이 손가락 중점에 계속 붙어 있도록 스크롤 보정
            const sc=pageScale*k;
            body.scrollLeft=piv.cx*sc-piv.mx;
            body.scrollTop =piv.cy*sc-piv.my;
        };
        body.addEventListener('touchmove',e=>{
            if(!piv||e.touches.length!==2) return;
            e.preventDefault();                       // 브라우저 기본 동작 차단
            const d=dist(e.touches);
            if(!d||!piv.d0) return;
            want=Math.max(25,Math.min(400, piv.z0*(d/piv.d0)));
            const m=mid(e.touches), r=body.getBoundingClientRect();
            piv.mx=m.x-r.left; piv.my=m.y-r.top;
            if(!raf) raf=requestAnimationFrame(apply);
        },{passive:false});

        const end=e=>{
            if(!piv) return;
            if(!e.touches||e.touches.length<2){
                if(raf){ cancelAnimationFrame(raf); raf=0; }
                const fin=want||piv.z0, mx=piv.mx, my=piv.my, cx=piv.cx, cy=piv.cy;
                piv=null; want=0;
                // 임시 CSS 확대를 걷어내고 진짜 배율로 한 번에 다시 그린다
                stage.style.transform='';
                zoomPct=fin;
                const was=body.style.scrollBehavior;
                body.style.scrollBehavior='auto';
                layoutPages();
                body.scrollLeft=cx*pageScale-mx;
                body.scrollTop =cy*pageScale-my;
                body.style.scrollBehavior=was;
                try{ sizeTextGhost(); }catch(err){}
                try{ onEditorScroll(); }catch(err){}
            }
        };
        body.addEventListener('touchend',end);
        body.addEventListener('touchcancel',end);

        // iOS Safari 는 페이지 전체를 확대하려 든다 → 에디터 안에서는 막는다
        ['gesturestart','gesturechange','gestureend'].forEach(g=>
            body.addEventListener(g,ev=>ev.preventDefault()));
    })();

    // 두 번 톡톡 → 100% ↔ 화면 폭 맞춤 (모바일에서 빠르게 오가기)
    (function(){
        const body=document.getElementById('editorBody');
        if(!body) return;
        let lastT=0,lastX=0,lastY=0;
        body.addEventListener('touchend',e=>{
            if(e.touches.length||!e.changedTouches.length) return;
            if(penActive||drawing) return;
            const t=e.changedTouches[0], now=Date.now();
            if(now-lastT<300 && Math.hypot(t.clientX-lastX,t.clientY-lastY)<28){
                if(e.target.closest('.tb,.paper-img,.stroke-g')) return;  // 요소 조작은 방해 않기
                lastT=0;
                if(Math.round(zoomPct)===100) zoomFit(); else resetZoom();
            }
            lastT=now; lastX=t.clientX; lastY=t.clientY;
        },{passive:true});
    })();

    // ============ 워드식 글자색 / 형광펜 ============
    const TEXT_COLORS=['#000000','#e74c3c','#e67e22','#f1c40f','#2ecc71','#1abc9c','#3498db','#9b59b6','#e84393','#7f8c8d'];
    const HL_COLORS=['#ffff00','#00ff00','#00ffff','#ff00ff','#ff9999','#99ccff','#ffcc99','#c0c0c0','#99ff99','#ffd700'];
    let currentTextColor='#000000', currentHlColor='#ffff00';

    function saveSel(){
        const s=window.getSelection();
        if(!s||!s.rangeCount||s.isCollapsed) return;
        const r=s.getRangeAt(0);
        const host=r.commonAncestorContainer.nodeType===1
            ? r.commonAncestorContainer.closest?.('.tb-content')
            : r.commonAncestorContainer.parentElement?.closest('.tb-content');
        if(!host) return;
        savedRange=r.cloneRange(); savedHost=host;
    }
    function restoreSel(){
        if(!savedRange||!savedHost) return null;
        if(!document.body.contains(savedHost)) return null;
        savedHost.contentEditable='true';
        savedHost.focus({preventScroll:true});
        const s=window.getSelection();
        s.removeAllRanges(); s.addRange(savedRange);
        return savedHost;
    }
    document.addEventListener('selectionchange',saveSel);
    // 14.13.4 · 글상자 옆에 떠 있던 서식 막대(fmtBar)를 없앴다 — 상단 바와 항목이
    //   중복됐기 때문. 글자 서식(글꼴·크기·굵기·색·형광펜)은 전부 상단 바에서 한다.

    // ===== 글꼴 선택 =====
    // 각 항목을 '해당 글꼴 자체'로 렌더링해 이름만 보고도 어떤 폰트인지 바로 알 수 있게 한다.
    //   좌측: 실제 글꼴로 그린 미리보기 문구 (abc 가나다)
    //   우측: 글꼴 이름 (항상 Noto Sans 로 표시해 항상 가독) + 현재 선택 시 체크
    function buildFontMenu(){
        const m=document.getElementById('fontMenu');
        if(m.dataset.ready==='1') return;
        FONTS.forEach(f=>{
            const it=document.createElement('div');
            it.className='font-item'; it.dataset.f=f.id;
            it.innerHTML=`<span class="fi-sample" style="font-family:${f.css}">abc 가나다</span>`+
                         `<span class="fi-name">${f.label}</span>`+
                         `<i class="ri-checkbox-fill fi-check"></i>`;
            it.onmousedown=e=>e.preventDefault();
            it.onclick=(e)=>{ e.stopPropagation(); applyFont(f.id); closeFontMenu(); };
            m.appendChild(it);
        });
        m.dataset.ready='1';
        // 미리보기가 실제 폰트로 그려지도록, 아직 안 불러온 글꼴은 여기에서 선제 로드
        if(document.fonts&&document.fonts.load){
            FONTS.forEach(f=>{
                const fam=f.css.split(',')[0];           // 주 패밀리 (따옴표 포함)
                try{ document.fonts.load('16px '+fam).catch(()=>{}); }catch(e){}
            });
        }
    }
    function toggleFontMenu(){
        buildFontMenu();
        const m=document.getElementById('fontMenu');
        const willShow=!m.classList.contains('show');
        closePops();
        m.classList.toggle('show',willShow);
        if(willShow){
            // 툴바의 블러(글래스)가 fixed 의 기준점을 바꾸어 위치가 어긋나므로
            // 색 팝오버와 같은 방식으로 body 로 옮긴 뒤 배치한다.
            if(m.parentElement!==document.body) document.body.appendChild(m);
            const r=document.getElementById('fontBtn').getBoundingClientRect();
            const cw=v=>window.sdyUiCss?window.sdyUiCss(v):(Number(v)||0);  // html zoom(.9) 보정
            m.style.left=Math.min(cw(r.left),cw(window.innerWidth)-240)+'px';
            m.style.top=(cw(r.bottom)+6)+'px';
            // 현재 선택된 글꼴 표시 (강조 + 체크)
            m.querySelectorAll('.font-item').forEach(n=>n.classList.toggle('sel',n.dataset.f===curFont));
        }
    }
    function closeFontMenu(){ document.getElementById('fontMenu').classList.remove('show'); }

    function applyFont(id){
        curFont=id;
        const f=FONTS.find(x=>x.id===id)||FONTS[0];
        document.getElementById('fontLabel').textContent=f.label;
        document.getElementById('fontBtn').style.fontFamily=f.css;

        // ① 글자 선택이 있으면 그 부분만
        const host=restoreSel();
        const sel=window.getSelection();
        if(host&&sel&&!sel.isCollapsed){
            document.execCommand('styleWithCSS',false,true);
            try{
                const r=sel.getRangeAt(0);
                const span=document.createElement('span');
                span.style.fontFamily=f.css;
                span.appendChild(r.extractContents());
                r.insertNode(span);
                const nr=document.createRange(); nr.selectNodeContents(span);
                sel.removeAllRanges(); sel.addRange(nr); savedRange=nr.cloneRange();
            }catch(e){}
            const w=host.closest('.tb'); if(w) syncTextEl(w);
            toast(`글꼴: ${f.label}`,1100);
            return;
        }
        // ② 선택한 표 셀 범위 전체
        if(selectedTblCellEls().length){
            tblCellApply(el=>{ el.font=id; },`선택한 칸 글꼴: ${f.label}`);
            return;
        }
        // ③ 선택된 텍스트 상자(들)
        let targets=[];
        if(multiSel.length) targets=multiSel.map(m=>m.node).filter(n=>n.classList.contains('tb'));
        if(!targets.length) targets=Array.from(document.querySelectorAll('#pagesStage .tb.edit,#pagesStage .tb.sel'));
        if(targets.length){
            pushHistory();
            targets.forEach(w=>{
                const el=findEl(+w.dataset.pageIdx,w.dataset.id);
                const c=w.querySelector('.tb-content');
                if(el&&c){ el.font=id; c.style.fontFamily=f.css; }
            });
            saveDoc();
            toast(`${targets.length}개 상자 글꼴 변경`,1200);
            return;
        }
        toast(`이후 입력 글꼴: ${f.label}`,1200);
    }

    function buildPop(id,colors,kind){
        const pop=document.getElementById(id);
        if(pop.dataset.ready==='1') return;
        const title=document.createElement('div');
        title.className='cp-title';
        title.textContent=kind==='text'?'글자 색':'형광펜 색';
        pop.appendChild(title);
        const grid=document.createElement('div'); grid.className='cp-grid';
        colors.forEach(c=>{
            const b=document.createElement('button');
            b.className='color-swatch'; b.style.background=c; b.dataset.c=c;
            b.onmousedown=e=>e.preventDefault();
            b.onclick=(e)=>{
                e.stopPropagation();
                if(kind==='text'){ currentTextColor=c; document.getElementById('tcBar').style.background=c; document.getElementById('tcGlyph').style.color=c; applyTextColor(c); }
                else { currentHlColor=c; document.getElementById('hlBar').style.background=c; applyHighlight(c); }
                pop.querySelectorAll('.color-swatch').forEach(s=>s.classList.toggle('sel',s.dataset.c===c));
                closePops();
            };
            grid.appendChild(b);
        });
        pop.appendChild(grid);
        const none=document.createElement('button');
        none.className='cp-none';
        none.innerHTML=kind==='text'?'<i class="ri-format-clear"></i> 자동(검정)':'<i class="ri-drop-line"></i> 색 없음';
        none.onmousedown=e=>e.preventDefault();
        none.onclick=(e)=>{ e.stopPropagation(); if(kind==='text') applyTextColor('#000000'); else applyHighlight(null); closePops(); };
        pop.appendChild(none);
        pop.dataset.ready='1';
    }
    function togglePop(id){
        const kind=id==='textColorPop'?'text':'hl';
        buildPop(id, kind==='text'?TEXT_COLORS:HL_COLORS, kind);
        const pop=document.getElementById(id);
        const other=document.getElementById(id==='textColorPop'?'hlPop':'textColorPop');
        other.classList.remove('show');
        const willShow=!pop.classList.contains('show');
        pop.classList.toggle('show',willShow);
        if(willShow){
            // 툴바의 overflow 에 잘리지 않도록 body 로 이동 + 버튼 아래에 고정 배치
            if(pop.parentElement!==document.body) document.body.appendChild(pop);
            const btn=document.getElementById(kind==='text'?'textColorWrap':'hlWrap');
            const r=btn.getBoundingClientRect();
            pop.style.left=Math.min(r.left, window.innerWidth-210)+'px';
            pop.style.top=(r.bottom+6)+'px';
        }
    }
    function closePops(){
        document.getElementById('textColorPop').classList.remove('show');
        document.getElementById('hlPop').classList.remove('show');
    }
    document.addEventListener('click',e=>{
        if(!e.target.closest('.split-btn')) closePops();
        if(!e.target.closest('.font-wrap')) closeFontMenu();
    });

    // 14.13.4 · execCommand(foreColor/hiliteColor) 가 선택지의 span 을 다시 짜면서
    //   기존 인라인 font-family 을 떨어뜨려 글꼴이 '기본으로 초기화'되는 환경을 대비한다.
    //   색/형광펜 적용 후 선택 영역 글꼴을 점검하고, 잃은 부분만 원본 글꼴로 다시 감싼다.
    function _keepFontOnSel(host){
        try{
            const s=window.getSelection();
            if(!s||s.isCollapsed||!s.rangeCount) return;
            const r=s.getRangeAt(0);
            const anc=r.commonAncestorContainer.nodeType===1
                ? r.commonAncestorContainer : r.commonAncestorContainer.parentElement;
            const c=anc&&anc.closest?anc.closest('.tb-content'):null;
            if(!c||!host||!host.contains(anc)) return;
            // 선택 시작 지점에 걸린 글꼴 (노드 → 상자까지 위로 탐색)
            let css='',n=anc;
            while(n&&n!==c){ if(n.style&&n.style.fontFamily){ css=n.style.fontFamily; break; } n=n.parentElement; }
            if(!css) return;                      // 상자에서 상속받은 글꼴이면 잃을 글꼴이 없음
            // 선택 영역의 모든 글자가 이미 그 글꼴이면 그대로 둔다 (span 중복 방지)
            const d=document.createElement('div');
            d.appendChild(r.cloneContents());
            const tw=document.createTreeWalker(d,NodeFilter.SHOW_TEXT);
            let need=false,tn;
            while(tn=tw.nextNode()){
                if(!tn.nodeValue.trim()) continue;
                let p=tn.parentElement,has=false;
                while(p&&p!==d){ if(p.style&&p.style.fontFamily===css){ has=true; break; } p=p.parentElement; }
                if(!has){ need=true; break; }
            }
            d.remove();
            if(!need) return;
            // 원본 글꼴로 다시 감싸기
            const span=document.createElement('span');
            span.style.fontFamily=css;
            span.appendChild(r.extractContents());
            r.insertNode(span);
            const nr=document.createRange(); nr.selectNodeContents(span);
            s.removeAllRanges(); s.addRange(nr);
        }catch(e){}
    }
    function withSelection(fn){
        const host=restoreSel();
        if(!host){ toast('텍스트를 드래그해 선택하세요',1300); return false; }
        document.execCommand('styleWithCSS',false,true);
        fn(host);
        _keepFontOnSel(host);                     // 글꼴 초기화 방지
        // 선택 유지 → 워드처럼 연속 적용 가능
        saveSel();
        const w=host.closest('.tb');
        if(w) syncTextEl(w);
        return true;
    }
    // 14.13.4 · 글자 선택 없이 '상자'만 고른 상태 → 상자 전체에 서식을 칠할 대상
    function _boxFmtTargets(){
        let t=multiSel.length
            ? multiSel.map(m=>m.node).filter(n=>n&&n.classList&&n.classList.contains('tb')&&!n.classList.contains('latex-box'))
            : [];
        if(!t.length) t=Array.from(document.querySelectorAll('#pagesStage .tb.sel,#pagesStage .tb.msel,#pagesStage .tb.edit'))
            .filter(n=>!n.classList.contains('latex-box'));
        return t;
    }
    // 상자 안 내용 전체를 골라 서식 함수를 적용 (편집 중이 아닌 상자는 편집 모드를 원상복구)
    function _paintBoxAll(w,fn){
        const c=w.querySelector('.tb-content'); if(!c) return;
        const wasEdit=w.classList.contains('edit');
        c.contentEditable='true';
        try{ c.focus({preventScroll:true}); }catch(e){}
        const r=document.createRange(); r.selectNodeContents(c);
        const s=window.getSelection(); s.removeAllRanges(); s.addRange(r);
        document.execCommand('styleWithCSS',false,true);
        fn();
        _keepFontOnSel(c);
        c.contentEditable=wasEdit?'true':'false';
        if(!wasEdit){ try{ s.removeAllRanges(); }catch(e){} }
        syncTextEl(w);
    }
    // 14.13.4 · 순서: ① 표 셀 → ② 글자 선택 범위 → ③ 상자만 고른 상태(상자 전체)
    function applyTextColor(c){
        currentTextColor=c;
        document.getElementById('tcBar').style.background=c;
        document.getElementById('tcGlyph').style.color=c;
        if(selectedTblCellEls().length){ tblCellApply(el=>{ el.textColor=c; },'선택한 칸 글자색 적용'); return; }
        const sel=window.getSelection();
        if(sel&&sel.rangeCount&&!sel.isCollapsed
           &&sel.anchorNode&&sel.anchorNode.closest&&sel.anchorNode.closest('.tb-content')){
            withSelection(()=>document.execCommand('foreColor',false,c)); return;
        }
        const targets=_boxFmtTargets();
        if(targets.length){
            pushHistory();
            targets.forEach(w=>_paintBoxAll(w,()=>document.execCommand('foreColor',false,c)));
            saveDoc();
            toast(targets.length>1?targets.length+'개 상자 글자색 적용':'상자 전체 글자색 적용',1000);
            return;
        }
        toast('텍스트를 드래그하거나 상자를 고르세요',1300);
    }
    function applyHighlight(c){
        if(c){ currentHlColor=c; document.getElementById('hlBar').style.background=c; }
        if(selectedTblCellEls().length){ tblCellFill(c||''); return; }
        const doHl=()=>{
            if(c){ if(!document.execCommand('hiliteColor',false,c)) document.execCommand('backColor',false,c); }
            else { if(!document.execCommand('hiliteColor',false,'transparent')) document.execCommand('backColor',false,'transparent'); }
        };
        const sel=window.getSelection();
        if(sel&&sel.rangeCount&&!sel.isCollapsed
           &&sel.anchorNode&&sel.anchorNode.closest&&sel.anchorNode.closest('.tb-content')){
            withSelection(doHl); return;
        }
        const targets=_boxFmtTargets();
        if(targets.length){
            pushHistory();
            targets.forEach(w=>_paintBoxAll(w,doHl));
            saveDoc();
            toast(targets.length>1?targets.length+'개 상자 형광펜 적용':'상자 전체 형광펜 적용',1000);
            return;
        }
        toast('텍스트를 드래그하거나 상자를 고르세요',1300);
    }
    function execFmt(cmd){
        const cells=selectedTblCellEls();
        if(cells.length){
            const spec={bold:['fontWeight','700'],italic:['fontStyle','italic'],underline:['textDecoration','underline']}[cmd];
            if(spec){
                const [key,val]=spec,remove=cells.every(el=>el[key]===val);
                tblCellApply(el=>{ if(remove) delete el[key]; else el[key]=val; },'선택한 칸 글자 서식 적용');
                return;
            }
        }
        withSelection(()=>document.execCommand(cmd,false,null));
    }

    // 문단 정렬 — 선택 영역이 있으면 그 문단만, 없으면 선택한 상자 전체
    function setAlign(dir){
        const cmd={left:'justifyLeft',center:'justifyCenter',right:'justifyRight'}[dir];
        const sel=window.getSelection();
        const live=sel&&!sel.isCollapsed&&document.querySelector('.tb.edit');
        if(live){ withSelection(()=>document.execCommand(cmd,false,null)); return; }
        if(selectedTblCellEls().length){ tblCellAlign(dir); return; }
        let targets=multiSel.length
            ? multiSel.map(m=>m.node).filter(nd=>nd.classList.contains('tb'))
            : [];
        if(!targets.length) targets=Array.from(document.querySelectorAll('#pagesStage .tb.edit,#pagesStage .tb.sel'));
        if(!targets.length){ toast('텍스트 상자를 먼저 선택하세요',1300); return; }
        pushHistory();
        targets.forEach(w=>{
            const c=w.querySelector('.tb-content'); if(!c) return;
            c.style.textAlign=dir;
            const el=findEl(+w.dataset.pageIdx,w.dataset.id);
            if(el) el.align=dir;
        });
        saveDoc();
        toast(({left:'왼쪽',center:'가운데',right:'오른쪽'})[dir]+' 정렬',1000);
    }
    // 서식 지우기 (고도화)
    //  - 텍스트를 드래그해 선택했으면 그 부분만
    //  - 선택이 없으면 텍스트 상자 전체 (여러 개 선택 시 전부)
    function clearFmt(){
        const host=restoreSel();
        const sel=window.getSelection();
        if(host && sel && !sel.isCollapsed){
            document.execCommand('styleWithCSS',false,true);
            document.execCommand('removeFormat',false,null);
            document.execCommand('unlink',false,null);
            const w=host.closest('.tb'); if(w) syncTextEl(w);
            toast('선택 영역 서식 지움',1200);
            return;
        }
        if(selectedTblCellEls().length){
            tblCellApply(el=>{
                el.html=stripFormatting(el.html||''); el.fontSize=curFontSize;
                delete el.textColor; delete el.font; delete el.fontWeight;
                delete el.fontStyle; delete el.textDecoration;
            },'선택한 칸 글자 서식 지움');
            return;
        }
        // 상자 단위
        let targets=[];
        if(multiSel.length) targets=multiSel.map(m=>m.node).filter(n=>n.classList.contains('tb'));
        if(!targets.length){
            targets=Array.from(document.querySelectorAll('#pagesStage .tb.edit,#pagesStage .tb.sel,#pagesStage .tb.msel'));
        }
        if(!targets.length){ toast('텍스트 상자를 선택하거나 글자를 드래그하세요',1800); return; }
        pushHistory();
        targets.forEach(w=>{
            const c=w.querySelector('.tb-content');
            const el=findEl(+w.dataset.pageIdx,w.dataset.id);
            if(!c||!el) return;
            c.innerHTML=stripFormatting(c.innerHTML);
            c.style.fontSize=(curFontSize)+'px';
            el.fontSize=curFontSize;
            el.html=c.innerHTML;
        });
        saveDoc();
        toast(`${targets.length}개 상자 서식 지움`,1400);
    }

    // 줄바꿈만 남기고 모든 서식 제거
    function stripFormatting(html){
        const box=document.createElement('div');
        box.innerHTML=html||'';
        box.querySelectorAll('br').forEach(b=>b.replaceWith('\n'));
        box.querySelectorAll('div,p,li').forEach(n=>{ n.after('\n'); });
        const text=(box.textContent||'').replace(/\n{3,}/g,'\n\n').replace(/[ \t]+\n/g,'\n').trim();
        return esc(text).replace(/\n/g,'<br>');
    }
    // 14.16 · 툴바의 글자 크기칸과 '지금 보고 있는 글자'를 맞추는 장치
    //  상자를 Alt+휠로 키우거나 다른 상자를 집었을 때 툴바 값이 낡은 채로 남아
    //  '+' 를 누르면 도로 작아지던 것을 막는다.
    function setToolbarFS(v){
        v=Math.max(2,Math.min(200,Math.round(Number(v)||0)));
        if(!v||v===curFontSize) return;
        curFontSize=v;
        const inp=document.getElementById('fsInput');
        if(inp&&document.activeElement!==inp) inp.value=v;
    }
    // 지금 글자 크기를 물어볼 대상: 표 칸 → 편집 중인 상자 → 선택한 상자
    function activeTextFS(){
        try{
            const cells=selectedTblCellEls();
            if(cells.length&&cells[0]&&cells[0].fontSize) return cells[0].fontSize;
        }catch(e){}
        let node=null;
        if(selected&&selected.type==='text'&&selected.el) node=selected.el;   // 편집 중/방금 집은 상자
        if(!node&&multiSel.length===1) node=multiSel[0].node;
        if(!node) node=document.querySelector('#pagesStage .tb.edit');
        if(!node) node=document.querySelector('#pagesStage .tb.sel');
        if(!node||!node.isConnected) return 0;
        const c=node.querySelector('.tb-content'); if(!c) return 0;
        // 화면에 실제로 그려진 크기를 우선한다 (자동 맞춤 상자도 헷갈리지 않게)
        let v=parseFloat(c.style.fontSize);
        if(!v){ try{ const el=findEl(+node.dataset.pageIdx,node.dataset.id); v=el&&el.fontSize; }catch(e){} }
        return Math.round(Number(v)||0);
    }
    function syncFSFromTarget(){ setToolbarFS(activeTextFS()); }
    // 상자 안의 '일부 글자'를 드래그해 골라 둔 상태면 그쪽 크기를 기준으로 삼는다
    function hasInlineTextSel(){
        try{
            const s=window.getSelection();
            if(s&&s.rangeCount&&!s.isCollapsed){
                const r=s.getRangeAt(0);
                const n=r.commonAncestorContainer;
                const host=n.nodeType===1?n:n.parentElement;
                if(host&&host.closest&&host.closest('.tb-content')) return true;
            }
            if(savedRange&&!savedRange.collapsed&&savedHost&&document.body.contains(savedHost)) return true;
        }catch(e){}
        return false;
    }
    function chFS(d){
        if(!hasInlineTextSel()) syncFSFromTarget();   // 지금 보이는 크기에서 증감
        setFS(curFontSize + (curFontSize<=10 ? (d>0?1:-1) : d));
    }
    function setFS(v){
        curFontSize=Math.max(2,Math.min(200,Math.round(v)));
        document.getElementById('fsInput').value=curFontSize;
        if(selectedTblCellEls().length){
            tblCellApply(el=>{ el.fontSize=curFontSize; },`선택한 칸 글자 ${curFontSize}px`);
            return;
        }
        const host=restoreSel();
        if(host){
            document.execCommand('styleWithCSS',false,true);
            try{
                const s=window.getSelection(), r=s.getRangeAt(0);
                const span=document.createElement('span');
                span.style.fontSize=curFontSize+'px';
                span.appendChild(r.extractContents());
                r.insertNode(span);
                const nr=document.createRange(); nr.selectNodeContents(span);
                s.removeAllRanges(); s.addRange(nr); savedRange=nr.cloneRange();
            }catch(e){}
            const w=host.closest('.tb'); if(w) syncTextEl(w);
            return;
        }
        const sel=document.querySelector('.tb.sel,.tb.edit');
        if(sel){ sel.querySelector('.tb-content').style.fontSize=curFontSize+'px'; syncTextEl(sel); }
    }

    // ============ 종이 / 크기 ============
    function setPaper(type){
        if(!doc) return;
        doc.paper=type;
        document.querySelectorAll('.ptool').forEach(b=>b.classList.toggle('active',b.dataset.p===type));
        editorPapers().forEach(p=>{
            p.classList.remove('paper-blank','paper-lined','paper-grid','paper-dotted');
            p.classList.add('paper-'+type);
        });
        saveDoc();
    }
    function changeSizePreset(key){
        if(!doc) return;
        doc.sizePreset=key;
        renderPages(); saveDoc();
    }

    // ============ 이미지 ============
    let _imgPickAnchor=null;   // 우클릭 '사진 넣기'로 연 경우: 그 지점(문서 좌표)
    function triggerImgUpload(anchor){
        if(penActive) finishDrawing();
        setTextTool(false); deselectAll();
        cancelPlaceMode(); if(tablePlace) cancelTablePlacement();
        _imgPickAnchor=(anchor&&Number.isFinite(anchor.x)&&Number.isFinite(anchor.y))?anchor:null;
        document.getElementById('imgInput').click();
    }
    // 파일 선택 결과: 우클릭 지점이 잡혀 있으면 그 자리에 바로, 아니면 배치 모드로.
    // 예전에는 도구막대에서 고륜 파일이 항상 쪽 한가욤데에 들어가 커서와 동떨어져 보였다.
    async function onImgPicked(input){
        const anchor=_imgPickAnchor; _imgPickAnchor=null;
        try{
            const items=await filesToImgItems(input?input.files:null);
            if(!items.length||!doc) return;
            if(anchor&&doc.pages[anchor.pageIdx]){
                for(let i=0;i<items.length;i++)
                    placeImgItem(items[i],anchor.pageIdx,anchor.x+i*16,anchor.y+i*16);
                saveDoc(); runUploadQueue();
                toast(items.length>1?`${items.length}장을 넣었습니다`:'그림을 넣었습니다',1300);
            }else{
                beginImgPlacement(items);
            }
        }finally{ if(input) input.value=''; }
    }

    // 원본 비율 그대로 배치 (정사각 고정 제거)
    function fitBox(nw,nh){
        const s=paperSize();
        const maxW=s.w*0.5, maxH=s.h*0.4;
        let w=nw||200, h=nh||150;
        const r=Math.min(maxW/w, maxH/h, 1);
        return {w:Math.max(24,Math.round(w*r)), h:Math.max(24,Math.round(h*r))};
    }
    function imageNaturalSize(src){
        return new Promise(res=>{
            const i=new Image();
            i.onload=()=>res({w:i.naturalWidth||200,h:i.naturalHeight||150});
            i.onerror=()=>res({w:200,h:150});
            i.src=src;
        });
    }

    // 업로드 큐: 화면에는 즉시 붙이고, 전송은 백그라운드에서 순차 처리
    const uploadQueue=[];
    let uploadRunning=false, uploadDone=0, uploadTotal=0;

    function updateUploadBadge(){
        const el=document.getElementById('uploadBadge');
        if(!el) return;
        const left=uploadTotal-uploadDone;
        if(left>0){
            el.style.display='flex';
            el.querySelector('span').textContent=`이미지 업로드 ${uploadDone}/${uploadTotal}`;
        }else{
            el.style.display='none';
            uploadDone=uploadTotal=0;
        }
    }

    // 파일 목록 → 배치 준비물 (로컬 미리보기 URL·자연 크기·맞춤 상자)을 만든다.
    async function filesToImgItems(files){
        const list=Array.from(files||[]).filter(f=>f&&f.type&&f.type.startsWith('image/'));
        const items=[];
        for(const f of list){
            const url=URL.createObjectURL(f);
            const nat=await imageNaturalSize(url);   // 로컬이라 즉시 완료
            items.push({file:f,url,box:fitBox(nat.w,nat.h)});
        }
        return items;
    }
    // 그림 한 장을 문서 좌표 (cx,cy) 중심에 둔다. 업로드는 큐가 백그라운드로 이어서 처리.
    function placeImgItem(item,pageIdx,cx,cy){
        pushHistory();
        const c=clampEl(cx-item.box.w/2,cy-item.box.h/2,item.box.w,item.box.h);
        const el={type:'image',id:uid('i'),url:item.url,localURL:item.url,pending:true,
            x:Math.round(c.x),y:Math.round(c.y),w:item.box.w,h:item.box.h};
        doc.pages[pageIdx].els.push(el);
        renderPageEls(pageIdx);
        uploadQueue.push({file:item.file,id:el.id,pageIdx,nbId:curNB.id});
        uploadTotal++; updateUploadBadge();
        return el;
    }

    async function uploadImgs(files,atPoint){
        if(!doc) return;
        const items=await filesToImgItems(files);
        if(!items.length) return;
        const s=paperSize();
        // ① 즉시 로컬 미리보기로 배치 (네트워크 대기 없음)
        for(let i=0;i<items.length;i++){
            const it=items[i];
            if(atPoint){
                // 붙여넣기면 마우스 위치에 연달아 살짝씩 어긋나게
                const pt=pastePoint(it.box.w,it.box.h);
                placeImgItem(it,pt.pageIdx,pt.x+it.box.w/2+i*16,pt.y+it.box.h/2+i*16);
            }else{
                // 지정 지점이 없으면 현재 페이지 위쪽에 차례로
                placeImgItem(it,curPageIdx,s.w/2,60+i*24+it.box.h/2);
            }
        }
        saveDoc();
        document.getElementById('imgInput').value='';
        runUploadQueue();
    }

    async function runUploadQueue(){
        if(uploadRunning) return;
        uploadRunning=true;
        while(uploadQueue.length){
            const job=uploadQueue.shift();
            try{
                const res=await uploadOne(job.file);
                if(res&&res.url) applyUploadedURL(job,res.url,res.public_id);
                else markUploadFailed(job);
            }catch(e){ console.warn('업로드 실패:',e); markUploadFailed(job); }
            uploadDone++; updateUploadBadge();
        }
        uploadRunning=false;
        saveDoc();
    }

    async function uploadOne(file){
        // 14.12 · 이미지는 항상 이 서버(/api/upload → 오라클 디스크)에 올린다.
        // 예전의 Cloudinary 직접 업로드 폴백은 삭제됐다 (쿼터 초과 방지).
        try{
            const fd=new FormData();
            fd.append('file',file); fd.append('quality','78'); fd.append('max_width','1920');
            const r=await fetch('/api/upload',{method:'POST',body:fd});
            if(r.ok){ const j=await r.json(); if(j.url) return {url:j.url,public_id:j.public_id}; }
        }catch(e){}
        try{
            const c=await compressImg(file);
            const fd=new FormData();
            fd.append('file',c); fd.append('quality','78'); fd.append('max_width','1920');
            const r=await fetch('/api/upload',{method:'POST',body:fd});
            if(r.ok){ const j=await r.json(); if(j.url) return {url:j.url,public_id:j.public_id}; }
        }catch(e){}
        return null;
    }

    // 업로드 완료 → blob URL 을 실제 URL 로 교체 (열려있지 않은 노트도 반영)
    function applyUploadedURL(job,url,publicId){
        const patch=(d)=>{
            let hit=false;
            (d.pages||[]).forEach(pg=>(pg.els||[]).forEach(el=>{
                if(el.id===job.id){
                    el.url=url;
                    if(publicId) el.public_id=publicId;
                    delete el.pending; delete el.failed; delete el.localURL; hit=true;
                }
            }));
            return hit;
        };
        if(curNB&&curNB.id===job.nbId&&doc){
            if(patch(doc)){
                const node=document.querySelector(`#pagesStage .paper-img[data-id="${job.id}"]`);
                if(node){
                    node.classList.remove('pending','failed');
                    const im=node.querySelector('img');
                    if(im) im.src=url;
                }
                saveDoc();
            }
        }else{
            const d=loadDoc(job.nbId);
            if(patch(d)){ persistDoc(job.nbId,d); queueSync(job.nbId); }
        }
    }
    function markUploadFailed(job){
        const node=document.querySelector(`#pagesStage .paper-img[data-id="${job.id}"]`);
        if(node) node.classList.add('failed');
        if(curNB&&curNB.id===job.nbId&&doc){
            (doc.pages||[]).forEach(pg=>(pg.els||[]).forEach(el=>{ if(el.id===job.id){ el.failed=true; } }));
        }
        toast('일부 이미지 업로드 실패 (로컬에만 표시됨)',2600);
    }

    function compressImg(file){
        return new Promise(resolve=>{
            if(file.size<500000&&/jpe?g/.test(file.type)){ resolve(file); return; }
            const r=new FileReader();
            r.onload=e=>{
                const img=new Image();
                img.onload=()=>{
                    const c=document.createElement('canvas');
                    let w=img.width,h=img.height;
                    if(w>1920){h=Math.round(h*1920/w);w=1920;}
                    if(h>1920){w=Math.round(w*1920/h);h=1920;}
                    c.width=w;c.height=h;
                    c.getContext('2d').drawImage(img,0,0,w,h);
                    if(file.type==='image/png') c.toBlob(b=>resolve(new File([b],file.name||'image.png',{type:'image/png'})),'image/png');
                    else c.toBlob(b=>resolve(new File([b],(file.name||'image').replace(/\.\w+$/,'')+'.jpg',{type:'image/jpeg'})),'image/jpeg',0.85);
                };
                img.onerror=()=>resolve(file);
                img.src=e.target.result;
            };
            r.onerror=()=>resolve(file);
            r.readAsDataURL(file);
        });
    }

    // 붙여넣기
    document.addEventListener('paste',async e=>{
        if(!doc||!document.getElementById('editorView').classList.contains('open')) return;
        if(document.querySelector('.tb.edit')) return;   // 텍스트 편집 중엔 기본 동작

        const files=[];
        const items=e.clipboardData?.items||[];
        for(const it of items){
            if(it.type&&it.type.startsWith('image/')){
                const f=it.getAsFile();
                if(f) files.push(new File([f],`paste-${Date.now()}.${(it.type.split('/')[1]||'png')}`,{type:it.type}));
            }
        }
        if(files.length){
            e.preventDefault();
            await uploadImgs(files,true);      // 마우스 위치에 배치
            return;
        }

        // 텍스트 붙여넣기 → 자동으로 텍스트 상자 생성
        const html=e.clipboardData?.getData('text/html');
        const plain=e.clipboardData?.getData('text/plain');
        if(plain&&plain.trim()){
            e.preventDefault();
            let content;
            if(html&&html.trim()){
                const box=document.createElement('div');
                box.innerHTML=html;
                box.querySelectorAll('script,style,meta,link').forEach(n=>n.remove());
                box.querySelectorAll('*').forEach(n=>{
                    // 서식은 색/굵기/기울임/밑줄/배경만 유지
                    const c=n.style.color,bg=n.style.backgroundColor,
                          fw=n.style.fontWeight,fs=n.style.fontStyle,td=n.style.textDecoration;
                    n.removeAttribute('style'); n.removeAttribute('class'); n.removeAttribute('id');
                    if(c) n.style.color=c;
                    if(bg&&bg!=='transparent'&&!/rgba\(0, 0, 0, 0\)/.test(bg)) n.style.backgroundColor=bg;
                    if(fw&&(fw==='bold'||+fw>=600)) n.style.fontWeight='bold';
                    if(fs==='italic') n.style.fontStyle='italic';
                    if(td&&td.includes('underline')) n.style.textDecoration='underline';
                });
                content=box.innerHTML;
            }else{
                content=esc(plain).replace(/\n/g,'<br>');
            }
            // 글자 수에 따라 상자 크기 어림
            const s=paperSize();
            const lines=plain.split(/\n/).length;
            const w=Math.min(s.w-96, Math.max(220, Math.min(560, plain.length*11)));
            const h=Math.min(s.h-96, Math.max(52, lines*(curFontSize*1.5)+26));
            const pt=pastePoint(w,h);
            pushHistory();
            const el={type:'text',id:uid('t'),x:pt.x,y:pt.y,w:Math.round(w),h:Math.round(h),
                      html:content,fontSize:curFontSize,font:curFont};
            doc.pages[pt.pageIdx].els.push(el);
            renderPageEls(pt.pageIdx);
            saveDoc();
            const node=paperAt(pt.pageIdx).querySelector(`.tb[data-id="${el.id}"]`);
            if(node){ deselectAll(); node.classList.add('sel'); selected={type:'text',el:node}; }
            toast('텍스트 붙여넣음',1200);
            return;
        }
        // OS 클립보드가 비어 있으면 앱 내부에서 복사한 요소를 붙여넣기
        if(clipboardEls.length){ e.preventDefault(); pasteElements(); }
    });

    // ============ 내보내기 ============
    const dataUrlCache=new Map();
    async function toDataURL(url){
        if(!url||url.startsWith('data:')) return url||'';
        if(dataUrlCache.has(url)) return dataUrlCache.get(url);
        const p=(async()=>{
            try{
                const r=await fetch(url,{mode:'cors',cache:'force-cache'});
                if(r.ok){
                    const b=await r.blob();
                    return await new Promise((res,rej)=>{const fr=new FileReader();fr.onload=()=>res(fr.result);fr.onerror=rej;fr.readAsDataURL(b);});
                }
            }catch(e){}
            try{
                const im=new Image(); im.crossOrigin='anonymous';
                await new Promise((res,rej)=>{im.onload=res;im.onerror=rej;im.src=url;});
                const c=document.createElement('canvas');
                c.width=im.naturalWidth;c.height=im.naturalHeight;
                c.getContext('2d').drawImage(im,0,0);
                return c.toDataURL('image/png');
            }catch(e){ return ''; }
        })();
        dataUrlCache.set(url,p); return p;
    }

    function paperCSSForExport(type){
        if(type==='lined') return 'background-color:#fff;background-image:repeating-linear-gradient(transparent,transparent 31px,#e8e8e8 31px,#e8e8e8 32px);background-position:0 16px;';
        if(type==='grid') return 'background-color:#fff;background-image:linear-gradient(#e8e8e8 1px,transparent 1px),linear-gradient(90deg,#e8e8e8 1px,transparent 1px);background-size:32px 32px;';
        if(type==='dotted') return 'background-color:#fff;background-image:radial-gradient(circle,#cfcfcf 1px,transparent 1px);background-size:24px 24px;';
        return 'background-color:#fff;';
    }

    // 페이지 1장을 캔버스로 (화면 배율과 무관하게 항상 원본 크기)
    // HTML → XHTML 로 정규화.
    // foreignObject 는 '엄격한 XML' 만 받는다. contentEditable 이 만드는
    // <br>, &nbsp;, 안 닫힌 태그 때문에 내보내기가 통째로 실패하던 문제를 여기서 차단한다.
    function htmlToXhtml(html){
        const box=document.createElement('div');
        box.innerHTML=html||'';
        // XMLSerializer 는 항상 well-formed XML 을 만들어 준다
        let xml=new XMLSerializer().serializeToString(box);
        xml=xml.replace(/^<div[^>]*>/,'').replace(/<\/div>$/,'');
        // 숫자 참조만 남기고 명명 엔티티(&nbsp; 등)는 XML 에서 미정의라 치환
        xml=xml.replace(/&nbsp;/g,'\u00a0');
        return xml;
    }
    function escXml(t){
        return String(t==null?'':t)
            .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
            .replace(/"/g,'&quot;');
    }

    async function svgToImage(svg){
        const url='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);
        const img=new Image();
        await new Promise((res,rej)=>{
            img.onload=res;
            img.onerror=()=>rej(new Error('svg render fail'));
            img.src=url;
        });
        if(img.decode){ try{ await img.decode(); }catch(e){} }
        return img;
    }

    // 다크모드에서 저장된 밝은 글자색을 인쇄용으로 어둡게 보정
    function fixDarkColors(html){
        if(!html) return html;
        const box=document.createElement('div');
        box.innerHTML=html;
        box.querySelectorAll('[style]').forEach(n=>{
            const c=n.style.color;
            if(!c) return;
            const m=c.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
            if(m){
                const lum=(+m[1]*0.299 + +m[2]*0.587 + +m[3]*0.114);
                if(lum>210) n.style.color='#111111';   // 흰색 계열 → 검정
            }else if(/^#(fff|ffffff|eee|eeeeee)$/i.test(c.trim())){
                n.style.color='#111111';
            }
        });
        return box.innerHTML;
    }

    // ===== 선택한 것들을 스티커(이미지)로 만들기 =====
    // 글자·그림·펜 그림을 통째로 하나의 그림으로 구워서 새 요소로 넣는다.
    async function makeSticker(replace){
        const items=selEntries();
        if(!items.length){ toast('먼저 요소를 선택해 주세요',1800); return; }
        const pi=items[0].pageIdx;
        const bb=unionBBox(items,pi);
        if(!bb||bb.w<2||bb.h<2){ toast('선택 영역이 너무 작습니다',1800); return; }

        const pad=8;
        const rx=Math.max(0,bb.x-pad), ry=Math.max(0,bb.y-pad);
        const rw=bb.w+pad*2, rh=bb.h+pad*2;
        toast('스티커를 만드는 중…',1200);
        try{
            // 페이지 전체를 한 번 굽고 필요한 부분만 잘라낸다
            const ids=new Set(items.map(i=>i.id));
            const full=await renderPageCanvas(pi,{onlyIds:ids,transparent:true});
            const sc=full.width/paperSize().w;
            const out=document.createElement('canvas');
            out.width=Math.max(1,Math.round(rw*sc));
            out.height=Math.max(1,Math.round(rh*sc));
            const octx=out.getContext('2d');
            octx.drawImage(full, Math.round(rx*sc), Math.round(ry*sc),
                                 out.width, out.height,
                                 0,0, out.width, out.height);
            const url=out.toDataURL('image/png');

            pushHistory();
            if(replace){
                const rm=(doc.pages[pi].els||[]).filter(e=>ids.has(e.id));
                doc.pages[pi].els=(doc.pages[pi].els||[]).filter(e=>!ids.has(e.id));
                purgeElements(rm);
            }
            const el={type:'image',id:uid('i'),url,
                      x:Math.round(rx),y:Math.round(ry),
                      w:Math.round(rw),h:Math.round(rh),sticker:true};
            doc.pages[pi].els.push(el);
            clearMulti(); deselectAll(true);
            renderPageEls(pi);
            saveDoc();
            // 보관함에도 넣어 다른 노트에서 재사용
            fetch('/api/stickers/save',{method:'POST',
                headers:{'Content-Type':'application/json'},
                body:JSON.stringify({data:url,name:'스티커'})}).catch(()=>{});
            toast(replace?'스티커로 바꿨습니다 🏷️':'스티커 저장됨 · 보관함에서 다시 쓸 수 있어요',2600);
        }catch(e){
            console.error(e); toast('스티커 만들기 실패',2200);
        }
    }

    // 노트 정보 (용량·페이지·시간)
    function showNoteInfo(nb){
        const cfg=getCfg(nb.id);
        const d=loadDoc(nb.id);
        let bytes=0;
        try{ bytes=new Blob([localStorage.getItem('nb_'+nb.id)||'']).size; }catch(e){}
        const els=(d.pages||[]).reduce((t,p)=>t+((p.els||[]).length),0);
        const imgs=(d.pages||[]).reduce((t,p)=>t+((p.els||[]).filter(e=>e.type==='image').length),0);
        const txts=(d.pages||[]).reduce((t,p)=>t+((p.els||[]).filter(e=>e.type==='text').length),0);
        const strs=(d.pages||[]).reduce((t,p)=>t+((p.els||[]).filter(e=>e.type==='stroke').length),0);
        const fmtT=(v)=>v?new Date(v).toLocaleString('ko-KR',
            {year:'numeric',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'}):'-';
        const peers=livePeerCount[nb.id]||0;
        const row=(k,v)=>`<div style="display:flex;justify-content:space-between;gap:16px;
            padding:7px 0;border-bottom:1px solid var(--border);">
            <span style="color:var(--text3);font-size:12.5px;">${k}</span>
            <span style="font-size:12.5px;font-weight:600;text-align:right;">${v}</span></div>`;
        const m=document.getElementById('infoModal');
        document.getElementById('infoBody').innerHTML=
            row('제목',esc(nb.title||'제목 없음'))+
            row('용량',fmtBytes(bytes))+
            row('페이지',(d.pages||[]).length+'쪽')+
            row('요소',`${els}개 (글 ${txts} · 그림 ${imgs} · 펜 ${strs})`)+
            row('종이',({blank:'빈 종이',lined:'줄 노트',grid:'격자',dotted:'도트'})[d.paper]||d.paper)+
            row('만든 날짜',fmtT(nb.created_at))+
            row('마지막 수정',fmtT(nb.updated_at||nb.created_at))+
            row('잠금',(cfg.lock&&cfg.lock.enc)?'🔒 설정됨':'없음')+
            (peers>1?row('현재 접속',peers+'명이 함께 보는 중'):'');
        m.style.display='flex';
        openNav(closeNoteInfo);
    }
    function closeNoteInfo(){ document.getElementById('infoModal').style.display='none'; navDrop(closeNoteInfo); }

    // ============ 스티커 보관함 ============
    let stickerList=[];
    async function openStickers(){
        document.getElementById('stickerModal').style.display='flex';
        openNav(closeStickers);
        const box=document.querySelector('#stkList .vault-grid');
        box.innerHTML='<div class="vault-empty">불러오는 중…</div>';
        try{
            const r=await fetch('/api/stickers/list',{cache:'no-store'});
            const d=await r.json();
            stickerList=(d&&d.stickers)||[];
            renderStickers();
        }catch(e){ box.innerHTML='<div class="vault-empty">서버에 연결할 수 없습니다</div>'; }
    }
    function closeStickers(){ document.getElementById('stickerModal').style.display='none'; navDrop(closeStickers); }
    function renderStickers(){
        const box=document.querySelector('#stkList .vault-grid');
        document.getElementById('stkCount').textContent=
            stickerList.length?stickerList.length+'개':'';
        if(!stickerList.length){
            box.innerHTML='<div class="vault-empty"><i class="ri-sticky-note-line"></i>'+
                '스티커가 없습니다<br><span style="font-size:11.5px">'+
                '여러 개를 선택하고 우클릭 → 스티커로 만들기</span></div>';
            return;
        }
        box.innerHTML=stickerList.map(s=>
            `<div class="v-file" title="${esc(s.name||'')}" onclick="useSticker('${s.id}')"
                  oncontextmenu="event.preventDefault();delSticker('${s.id}')">
                <img class="v-thumb" src="${esc(s.url)}" alt="" loading="lazy">
                <div class="v-name">${esc(s.name||'스티커')}</div>
                <div class="v-size">${fmtBytes(s.bytes||0)}</div>
            </div>`).join('');
    }
    function useSticker(id){
        const s=stickerList.find(x=>x.id===id); if(!s) return;
        if(!doc){ toast('노트를 먼저 열어주세요',1800); return; }
        const im=new Image();
        im.onload=()=>{
            pushHistory();
            const sc=Math.min(1,300/Math.max(im.width,im.height));
            doc.pages[curPageIdx].els.push({type:'image',id:uid('i'),url:s.url,
                x:80,y:100,w:Math.round(im.width*sc),h:Math.round(im.height*sc),sticker:true});
            renderPageEls(curPageIdx); saveDoc();
            closeStickers(); toast('스티커를 붙였습니다',1600);
        };
        im.onerror=()=>toast('스티커를 불러오지 못했습니다',2000);
        im.src=s.url;
    }
    async function delSticker(id){
        const s=stickerList.find(x=>x.id===id); if(!s) return;
        if(!confirm('이 스티커를 보관함에서 지울까요?')) return;
        try{
            await fetch('/api/stickers/delete',{method:'POST',
                headers:{'Content-Type':'application/json'},
                body:JSON.stringify({id})});
            stickerList=stickerList.filter(x=>x.id!==id);
            renderStickers(); toast('삭제됨',1400);
        }catch(e){ toast('삭제 실패',1800); }
    }

    // ============ 자동 번역 (영어 <-> 한국어) ============
    // ---- 번역 작업 중단(취소) ----
    // 진행 중인 번역은 진행바의 [중단] 버튼이나 Esc 로 언제든 멈출 수 있다.
    // 취소는 '실패'가 아니므로 별도 신호(TR_CANCEL)를 던져 '번역 실패' 토스트나
    // 긴 재시도 로직과 섞이지 않게 한다. 이 신호 덕분에 "무한 로딩" 도 없다.
    const TR_CANCEL='번역 중단됨';   // 낮은 수준 신호 — 실패 문구/재시도 정규식과 절대 겹치지 않게
    let trCtl=null;                  // 실행 중인 번역 작업의 AbortController (한 번에 하나)
    let trCancel=false;              // 사용자가 중단을 눌렀는가
    function cancelTranslation(){
        if(!trCtl||trCancel) return;
        trCancel=true;
        try{ trCtl.abort(); }catch(e){}
        const p=document.getElementById('trProg');
        const l=p&&p.querySelector('.tr-label');
        if(p&&p.style.display!=='none'&&l) l.textContent='번역을 중단하는 중…';
    }
    function beginTrTask(){
        if(trCtl) endTrTask();       // 방어: 이전 작업 꼬리 정리
        trCtl=new AbortController(); trCancel=false;
        document.addEventListener('keydown',trEscKey,true);
    }
    function endTrTask(){
        if(trCtl) document.removeEventListener('keydown',trEscKey,true);
        trCtl=null;
        hideTrProg();
    }
    function trEscKey(e){
        if(e.key==='Escape'&&trCtl){
            e.preventDefault(); e.stopPropagation();
            cancelTranslation();
        }
    }
    // 중단하면 재시도 대기·간격 유지 잠도 바로 깬다 (취소가 대기 시간만큼 늦어지지 않게)
    function trSleep(ms){
        return new Promise(res=>{
            const ctl=trCtl;
            const t=setTimeout(fin,ms);
            function fin(){ clearTimeout(t); if(ctl) ctl.signal.removeEventListener('abort',fin); res(); }
            if(ctl){
                if(ctl.signal.aborted||trCancel) fin();
                else ctl.signal.addEventListener('abort',fin);
            }
        });
    }
    async function apiTranslate(text,target,gloss){
        // 프록시/서버가 잠깐 끊긴 경우 한 번만 재시도한다. 무한 재시도는
        // 사용자가 취소할 수 없고 무료 번역 엔진의 429를 더 악화시킨다.
        let last;
        for(let attempt=0;attempt<2;attempt++){
            if(trCancel) throw new Error(TR_CANCEL);
            const ctl=new AbortController();
            const task=trCtl;                       // 이 요청을 거는 작업 핸들
            const timer=setTimeout(()=>ctl.abort(),30000);
            // 사용자 중단 → 이 요청도 즉시 끊는다 (30초 타임아웃을 기다리지 않는다)
            const kick=()=>{ try{ctl.abort();}catch(e){} };
            if(task){
                if(task.signal.aborted){ clearTimeout(timer); throw new Error(TR_CANCEL); }
                task.signal.addEventListener('abort',kick);
            }
            try{
                const r=await fetch('/api/translate',{method:'POST',signal:ctl.signal,
                    headers:{'Content-Type':'application/json','Accept':'application/json'},
                    body:JSON.stringify({text,target,gloss:gloss||undefined})});
                const d=await r.json().catch(()=>({}));
                if(r.ok&&d.ok&&typeof d.text==='string') return d.text;
                // 4xx와 제한 응답은 재시도해도 성공하지 않는다.
                const msg=d.error||('번역 요청 실패 ('+r.status+')');
                if(r.status<500||/제한|429/.test(msg)) throw new Error(msg);
                last=new Error(msg);
            }catch(e){
                if(trCancel) throw new Error(TR_CANCEL);
                last=e&&e.name==='AbortError'?new Error('번역 서버 응답 시간이 초과됐어요. 잠시 후 다시 시도해 주세요.'):e;
                if(/제한|429|문자열이어야|내용이 없습니다|5000자/.test(String(last&&last.message||''))) throw last;
            }finally{
                clearTimeout(timer);
                if(task) task.signal.removeEventListener('abort',kick);
            }
            if(attempt===0) await trSleep(700);
            if(trCancel) throw new Error(TR_CANCEL);
        }
        throw last||new Error('번역 서버에 연결할 수 없습니다. 잠시 후 다시 시도해 주세요.');
    }

    async function persistTranslatedChange(){
        // 로컬 저장은 즉시 예약하고, 가져온 문서는 원격 슬라이스 저장까지 완료한 뒤
        // 성공 안내를 낸다. 따라서 다시 열었을 때 원문으로 돌아가지 않는다.
        saveDoc(); queueOps();
        try{ flushSaveDoc(); await flushImportedSave(); }
        catch(e){ throw new Error('번역 결과를 저장하지 못했어요. 네트워크를 확인해 주세요.'); }
    }

    // 텍스트 상자 전체 번역 (서식은 유지하기 어려우므로 글자만 바꾼다)
    // 가져온(tight) 상자는 innerText 가 절대스팬 사이를 줄바꿈으로 잇기 때문에
    // 줄/단어 구조를 살린 클린 텍스트를 만들고, 결과도 가지런한 일반 상자로 변환.
    // tight 상자의 단어 스팬을 '시각적 읽기 순서'로 정렬한다.
    // PDF 가져오기에서 스팬은 절대좌표로 배치되므로 DOM 순서 ≠ 눈에 보이는 순서.
    // → 위(top)에서 아래로, 같은 줄은 왼쪽(left)에서 오른쪽으로 정렬해야
    //   복사·번역·검색 때 글자 순서와 띄어쓰기가 정확해진다.
    function tightSpansSorted(host){
        const sps=Array.from(host.querySelectorAll(':scope>span'));
        const num=(v)=>{ const n=parseFloat(v); return isNaN(n)?0:n; };
        const pos=(s)=>[num(s.style.top), num(s.style.left)];
        // inline top/left 가 없으면 offsetTop/offsetLeft 로 대체 (옛 노트 호환)
        const noInline=sps.some(s=>s.style.left===''&&s.style.top==='');
        sps.sort((a,b)=>{
            const [at,al]=pos(a), [bt,bl]=pos(b);
            if(noInline){
                const aot=a.offsetTop||0, bot=b.offsetTop||0;
                if(Math.abs(aot-bot)>2) return aot-bot;
                return (a.offsetLeft||0)-(b.offsetLeft||0);
            }
            if(Math.abs(at-bt)>2) return at-bt;
            return al-bl;
        });
        return sps;
    }
    function tightCleanText(c){
        const sps=tightSpansSorted(c);
        const num=(v)=>{ const n=parseFloat(v); return isNaN(n)?0:n; };
        const topOf=(s)=>num(s.style.top)||s.offsetTop||0;
        const lines=[]; let cur=[]; let lastTop=null;
        sps.forEach(s=>{
            const t=(s.textContent||'').replace(/[\s\u00a0\u200b\ufeff]+$/,'');
            if(!t) return;
            const top=topOf(s);
            if(lastTop!=null&&Math.abs(top-lastTop)>2){
                lines.push(cur.join(' ')); cur=[];
            }
            cur.push(t); lastTop=top;
        });
        if(cur.length) lines.push(cur.join(' '));
        return lines.join('\n');
    }
    // 선택 범위에서 공백을 '재조립' (zsp 유무·옛 노트 무관):
    // 선택과 교차하는 단어 스팬을 시각 순서로 정렬한 뒤 줄 단위로 묶어 공백으로 잇는다.
    function tightSelectionText(sel){
        try{
            if(!sel||!sel.rangeCount) return String(sel||'');
            const rng=sel.getRangeAt(0);
            const rootEl=(sel.anchorNode&&sel.anchorNode.nodeType===1)
                ? sel.anchorNode : (sel.anchorNode&&sel.anchorNode.parentElement);
            const host=rootEl&&rootEl.closest('.tb-content');
            if(!host||!host.closest('.tight')) return String(sel);
            const spans=tightSpansSorted(host).filter(s=>{
                try{ return rng.intersectsNode(s); }catch(e){ return false; }
            });
            if(!spans.length) return String(sel);
            const num=(v)=>{ const n=parseFloat(v); return isNaN(n)?0:n; };
            const topOf=(s)=>num(s.style.top)||s.offsetTop||0;
            const lines=[]; let cur=[]; let lastTop=null;
            spans.forEach(s=>{
                const t=(s.textContent||'').replace(/[\s\u00a0\u200b\ufeff]+$/,'');
                if(!t) return;
                const top=topOf(s);
                if(lastTop!=null&&Math.abs(top-lastTop)>2){
                    lines.push(cur.join(' ')); cur=[];
                }
                cur.push(t); lastTop=top;
            });
            if(cur.length) lines.push(cur.join(' '));
            return lines.join('\n');
        }catch(e){ return String(sel||''); }
    }
    async function translateElement(node,target){
        closeCtxMenu();
        const pi=+node.dataset.pageIdx;
        const el=findEl(pi,node.dataset.id);
        if(!el||el.type!=='text'){ toast('텍스트 상자를 선택해 주세요',1800); return; }
        const c=node.querySelector('.tb-content');
        const isTight=node.classList.contains('tight');
        // 번역기는 뉴라인을 줄바꿈/문장 끝으로 취급하므로 공백으로 이어
        // 마침표 기준의 자연스러운 문장으로 보낸다.
        const src=isTight? tightCleanText(c).replace(/\n+/g,' ')
                         : (c?c.innerText:'').trim();
        if(!src){ toast('번역할 내용이 없습니다',1600); return; }
        if(trCtl||trBusy){ toast('번역이 이미 진행 중입니다 — 진행바의 [중단] 을 누르거나 잠시 기다려 주세요',2400); return; }
        beginTrTask();
        showTrProg(null,(TR_NAME[target]||target)+'로 번역 중… · 중단하려면 [중단] 또는 Esc');
        try{
            // 본문을 먼저 바꾼다. 용어 학습을 앞에 두면 무료 엔진 한도를
            // 먼저 깎아 정작 상자 번역이 '실패'로 떨어졌다.
            if(trCancel) throw new Error(TR_CANCEL);
            const out=await apiTranslate(src,target,doc.glossary);
            learnGlossary([src],target).then(n=>{ if(n){ try{ saveDoc(); queueOps(); }catch(e){} } }).catch(()=>{});
            pushHistory();
            if(isTight){
                // 가지런한 일반 텍스트 상자로 전환 (찌부됨 방지)
                el.tight=0; el.align='left'; delete el.fitDown;
                node.classList.remove('tight');
            }
            el.fit=0;
            el.html=esc(out).replace(/\n/g,'<br>');
            if(c) c.innerHTML=el.html;
            fitTranslated(node,c,el);                     // 6.1: 상자 안으로 자동 맞춤
            try{
                syncState();
                const rev=Date.now();
                doc.__localRev.set(el.id,rev);
                doc.__lastHash.set(el.id,JSON.stringify(el));
            }catch(e){}
            syncTextEl(node);
            await persistTranslatedChange();
            toast((TR_NAME[target]||target)+'로 번역하고 저장했습니다',2000);
        }catch(e){
            if(e&&e.message===TR_CANCEL) toast('번역을 중단했습니다 — 원문은 그대로입니다',2200);
            else toast('번역 실패: '+e.message,2600);
        }finally{ endTrTask(); }
}

    // 긁어놓은 글자만 번역해서 그 자리에 넣는다
    // 고른 글자를 그 자리에서 번역문으로 바꿔 넣는다 (서식·위치 유지)
    const TR_NAME={ko:'한국어',en:'영어',ja:'일본어','zh-CN':'중국어'};
    async function translateSelectedText(target){
        closeCtxMenu();
        // 우클릭 도중 선택이 풀릴 수 있으니 저장해 둔 선택을 되살린다
        let host=restoreSel();
        let sel=window.getSelection();
        if((!sel||sel.isCollapsed) && host){ /* 복원 실패 */ }
        if(!host){
            const n=sel&&sel.anchorNode
                ? (sel.anchorNode.nodeType===1?sel.anchorNode:sel.anchorNode.parentElement) : null;
            host=n?n.closest('.tb-content'):null;
        }
        sel=window.getSelection();
        // tight 상자는 단어 스팬 구조에서 공백을 재조립하고,
        // 번역 품질을 위해 뉴라인은 공백으로 보낸다.
        let txt=(host&&host.closest('.tight'))? tightSelectionText(sel) : (sel?String(sel):'');
        if(host&&host.closest('.tight'))
            txt=txt.replace(/\n+/g,' ').replace(/\s{2,}/g,' ').trim();
        if(!host||!txt.trim()){ toast('번역할 글자를 선택해 주세요',1800); return; }
        if(trCtl||trBusy){ toast('번역이 이미 진행 중입니다 — 진행바의 [중단] 을 누르거나 잠시 기다려 주세요',2400); return; }
        const w=host.closest('.tb');
        const rng=sel.getRangeAt(0).cloneRange();
        beginTrTask();
        showTrProg(null,`${TR_NAME[target]||target}로 번역 중… · 중단하려면 [중단] 또는 Esc`);
        try{
            const out=await apiTranslate(txt,target);
            if(!out||!String(out).trim()){ toast('번역 결과가 비어 있습니다',2000); return; }
            pushHistory();
            // 편집 상태여야 execCommand 가 먹는다
            if(w&&!w.classList.contains('edit')){
                enterEdit(w,true); enableTextSelect(host);
            }
            const s2=window.getSelection();
            s2.removeAllRanges(); s2.addRange(rng);
            host.focus({preventScroll:true});
            // 브라우저 execCommand 는 자체 실행취소 스택을 써서 Ctrl+Z 가 어긋난다.
            // → 직접 바꿔 넣어 우리 되돌리기 한 번으로 정확히 복구되게 한다.
            rng.deleteContents();
            const tn=document.createTextNode(out);
            rng.insertNode(tn);
            const r2=document.createRange();
            r2.setStartAfter(tn); r2.collapse(true);
            s2.removeAllRanges(); s2.addRange(r2);
            if(w){
                syncTextEl(w);
                await persistTranslatedChange();
            }
            saveSel();
            toast(`${TR_NAME[target]||target}로 바꾸고 저장했습니다 (Ctrl+Z 로 되돌리기)`,2400);
        }catch(e){
            if(e&&e.message===TR_CANCEL) toast('번역을 중단했습니다 — 원문은 그대로입니다',2200);
            else toast('번역 실패: '+e.message,2600);
        }finally{ endTrTask(); }
}

    // ============ 6.1: 페이지/문서 전체 번역 + 용어 기억 + 자동 맞춤 ============
    // tight 상자의 단어 스팬은 인라인 top 을 갖고 있으므로 레이아웃 없이 파싱 가능
    function tightTextFromHtml(html){
        const d=document.createElement('div'); d.innerHTML=html||'';
        const sps=Array.from(d.querySelectorAll('span')).filter(s=>s.style.left!==''||s.style.top!=='');
        sps.sort((a,b)=>(parseFloat(a.style.top)||0)-(parseFloat(b.style.top)||0)
                       ||(parseFloat(a.style.left)||0)-(parseFloat(b.style.left)||0));
        const lines=[]; let cur=[]; let last=null;
        sps.forEach(s=>{
            const t=(s.textContent||'').replace(/[​‌‍﻿]/g,'').trim();
            if(!t) return;
            const top=parseFloat(s.style.top)||0;
            if(last!=null&&Math.abs(top-last)>2){ lines.push(cur.join(' ')); cur=[]; }
            cur.push(t); last=top;
        });
        if(cur.length) lines.push(cur.join(' '));
        return lines.join(' ');
    }
    function plainTextFromHtml(html){
        const d=document.createElement('div');
        d.innerHTML=(html||'').replace(/<br\s*\/?>/gi,'\n');
        return (d.textContent||'').replace(/[​‌‍﻿]/g,'');
    }
    // 전문용어 후보 추출: 대문자 줄임말·하이픈 결합 용어·CamelCase
    const TR_STOP=new Set(['FIG','FIGS','FIGURE','FIGURES','TABLE','TABLES','SECTION','SECTIONS',
        'EQ','EQS','VOL','NO','PP','ET','AL','THE','AND','OR','OF','IN','ON','FOR','WITH','TO','BY',
        'IS','ARE','WAS','WERE','WE','OUR','US','AS','AT','AN','NOT','YES','OK','PDF','HTML','HTTP',
        'HTTPS','URL','DOI','ISBN','ISSN','ARXIV','CC','USA','UK','EU','UN','ABSTRACT','INTRODUCTION',
        'CONCLUSION','CONCLUSIONS','REFERENCES','ACKNOWLEDGMENTS','ACKNOWLEDGEMENTS','APPENDIX',
        'SUPPLEMENTARY','METHODS','RESULTS','DISCUSSION','PAGE','PAGES','COPYRIGHT','IEEE','ACM',
        'LNCS','SPRINGER','ELSEVIER','PREPRINT','ARTICLE','LETTER','LETTERS','NOTE','NOTES']);
    function extractTerms(text){
        const set=new Set();
        const re=/\b([A-Z][A-Z0-9]{1,9}(?:-[A-Z0-9]+)?)\b|\b([A-Z][a-z]+(?:-[A-Z][a-z]+)+)\b|\b([A-Z][a-z]+[A-Z][A-Za-z]+)\b/g;
        let m;
        while((m=re.exec(text))){
            const t=m[1]||m[2]||m[3];
            if(!t) continue;
            if(TR_STOP.has(t.toUpperCase())) continue;
            set.add(t);
            if(set.size>=300) break;
        }
        return Array.from(set);
    }
    // 문서 사전(doc.glossary)에 새 용어 번역을 학습해 저장 → 이후 번역이 일관됨
    async function learnGlossary(texts,target){
        if(!doc) return 0;
        const g=doc.glossary||(doc.glossary={});
        const seen=new Set(Object.keys(g));
        const terms=[];
        (texts||[]).forEach(t=>extractTerms(t).forEach(x=>{
            if(!seen.has(x)){ seen.add(x); terms.push(x); }
        }));
        if(!terms.length) return 0;
        for(let i=0;i<terms.length;i+=60){
            if(trCancel) return 0;                    // 사용자 중단 → 학습도 멈춤
            const chunk=terms.slice(i,i+60);
            try{
                const r=await fetch('/api/translate/gloss',{method:'POST',
                    signal:trCtl?trCtl.signal:undefined,
                    headers:{'Content-Type':'application/json'},
                    body:JSON.stringify({terms:chunk,target})});
                const d=await r.json().catch(()=>({}));
                if(d&&d.ok&&d.gloss) Object.assign(g,d.gloss);
            }catch(e){ if(trCancel) return 0; }
        }
        return terms.length;
    }
    // 번역문이 상자를 넘치면: ① 글자간격 → ② 기 → ③ 글자 크기 순으로 맞춤
    function fitTranslated(w,c,el){
        if(!c||!el) return;
        const base=el.fontSize||parseFloat(getComputedStyle(c).fontSize)||14;
        c.style.fontSize=base+'px'; c.style.letterSpacing='';
        c.style.fontWeight=el.fontWeight?String(el.fontWeight):'';
        const over=()=>c.scrollHeight>c.clientHeight+1||c.scrollWidth>c.clientWidth+1;
        el.trFit=1; el.trLS=''; el.trFW=''; el.trFS=base;
        if(!over()) return;
        for(const ls of [-0.012,-0.024,-0.036,-0.048]){   // ① 글자간격
            if(!over()) break;
            c.style.letterSpacing=ls+'em'; el.trLS=ls+'em';
        }
        let fw=parseInt(getComputedStyle(c).fontWeight)||400;   // ② 굵기
        for(const step of [600,500,400]){
            if(!over()||fw<=step) continue;
            c.style.fontWeight=step; el.trFW=step; fw=step;
        }
        let px=base, guard=0;                              // ③ 크기
        const min=Math.max(7,Math.round(base*0.62*10)/10);
        while(over()&&guard++<22&&px>min){
            px=Math.round(px*0.94*10)/10;
            c.style.fontSize=px+'px';
        }
        el.trFS=px;
        // ④ 최소 크기에서도 넘치면 상자 높이를 늘린다 (표 칸은 제외)
        if(el.h&&over()&&!el.tbl){
            let h=el.h, g2=0;
            while(over()&&g2++<60){ h+=16; el.h=h; w.style.height=h+'px'; }
        }
    }
    // 진행률 바
    function showTrProg(f,label){
        let p=document.getElementById('trProg');
        if(!p){
            p=document.createElement('div'); p.id='trProg';
            p.innerHTML='<span class="tr-label"></span><span class="tr-track"><i class="tr-fill"></i></span>'+
                '<button type="button" class="tr-cancel" title="번역 중단 (Esc)">중단</button>';
            p.querySelector('.tr-cancel').addEventListener('click',cancelTranslation);
            document.body.appendChild(p);
        }
        p.style.display='flex';
        const fill=p.querySelector('.tr-fill');
        if(f==null){ fill.classList.add('indet'); fill.style.width=''; }
        else{ fill.classList.remove('indet'); fill.style.width=Math.round(Math.min(1,Math.max(0,f))*100)+'%'; }
        p.querySelector('.tr-label').textContent=label||'';
    }
    function hideTrProg(){
        const p=document.getElementById('trProg');
        if(p) p.style.display='none';
    }
    // 피규어/표 캡션·축 라벨 등 "본문이 아닌" 글자인지 판별 (논문 전체 번역 시 제외)
    function isFigureText(el,src){
        if(el.isFig) return true;                        // 명시적으로 그림 글자로 표시된 경우
        const s=(src||'').replace(/\s+/g,' ').trim();
        if(!s) return true;
        // 캡션 패턴: Fig. 1 / Figure 2 / Table 3 / 그림 1 / 표 2 ...
        if(/^(fig(?:ure)?s?\.?|table|그림|표)\s*[0-9]+/i.test(s)) return true;
        // 축 눈금처럼 짧고 숫자·기호 위주인 글자는 그림 위 글자로 간주
        const letters=(s.match(/[A-Za-z가-힣]/g)||[]).length;
        if(letters<=3 && /[0-9]/.test(s) && s.length<=24) return true;
        return false;
    }
    // 논문 잡음: 참고문헌 번호·DOI·연도만 있는 조각은 번역하지 않는다.
    function isPaperNoise(src){
        const s=String(src||'').replace(/\s+/g,' ').trim();
        if(!s) return true;
        if(/^\[[0-9,\s–\-]+\]$/.test(s)) return true;
        if(/^\(\s*\d{4}[a-z]?\s*\)$/.test(s)) return true;
        if(/^(doi:|https?:\/\/|arxiv:)/i.test(s)) return true;
        if(/^[A-Za-z][A-Za-z\-']+ et al\.?$/i.test(s)) return true;
        if(/^(vol\.?|pp?\.?|no\.?)\s*[\d\-]+$/i.test(s)) return true;
        if(/^[\d.,+\-±%=\s]+$/.test(s) && s.length<=20) return true;
        return false;
    }
    function trLooksTarget(s,target){
        const t=String(s||'');
        if(target==='ko'){
            let ko=0; for(const ch of t) if(ch>='\uAC00'&&ch<='\uD7A3') ko++;
            return ko>=Math.max(2,Math.floor(t.trim().length*0.2));
        }
        if(target==='ja') return /[\u3040-\u30ff]/.test(t);
        if(target==='zh-CN'||target==='zh') return /[\u4e00-\u9fff]/.test(t)&&!/[\u3040-\u30ff]/.test(t);
        if(target==='en'){
            const letters=(t.match(/[A-Za-z]/g)||[]).length;
            const ko=(t.match(/[\uAC00-\uD7A3]/g)||[]).length;
            return letters>=8 && ko===0;
        }
        return false;
    }
    function applyTrResult(o,out){
        if(!out||!String(out).trim()) return false;
        o.el.tight=0; o.el.fit=0; delete o.el.fitDown;
        o.el.html=esc(out).replace(/\n/g,'<br>');
        if(doc.pages[o.pi]) doc.pages[o.pi].__dirty=true;
        try{
            syncState();
            const rev=Date.now()+Math.random();
            doc.__localRev.set(o.el.id,rev);
            doc.__lastHash.set(o.el.id,JSON.stringify(o.el));
        }catch(e){}
        const node=document.querySelector('.tb[data-id="'+o.el.id+'"]');
        const c=node&&node.querySelector('.tb-content');
        if(node&&c){
            node.classList.remove('tight');
            c.innerHTML=o.el.html;
            fitTranslated(node,c,o.el);
        }else o.el.trPending=1;
        return true;
    }
    // 논문 PDF 는 한 줄=한 상자인 경우가 많다. 짧은 상자를 한 요청으로 묶어
    // 문맥도 살리고 무료 엔진 한도도 덜 깎는다.
    function packTrJobs(list){
        const shorts=list.filter(o=>o.src.length<=240).length;
        const pack=list.length>=5 || shorts>=4;
        if(!pack) return list.map(o=>({items:[o]}));
        const packs=[]; let cur=null;
        const flush=()=>{ if(cur) packs.push(cur); cur=null; };
        list.forEach(o=>{
            const short=o.src.length<=240;
            if(!short){ flush(); packs.push({items:[o]}); return; }
            if(!cur){ cur={items:[o]}; return; }
            const next=cur.items.reduce((n,x)=>n+x.src.length,0)+o.src.length+10*cur.items.length;
            if(cur.items.length>=12 || next>1800){ flush(); cur={items:[o]}; }
            else cur.items.push(o);
        });
        flush();
        return packs;
    }
    function joinTrPack(items){
        if(items.length===1) return items[0].src;
        return items.map((o,i)=>i===0?o.src:('§#'+(i+1)+'§\n'+o.src)).join('\n');
    }
    function splitTrPack(out,n){
        if(n<=1) return [String(out||'')];
        const parts=[]; let rest=String(out||'');
        for(let i=2;i<=n;i++){
            const mark='§#'+i+'§';
            const idx=rest.indexOf(mark);
            if(idx<0) return null;
            parts.push(rest.slice(0,idx).replace(/^\s+|\s+$/g,''));
            rest=rest.slice(idx+mark.length);
        }
        parts.push(rest.replace(/^\s+|\s+$/g,''));
        if(parts.length!==n || parts.some(p=>!p)) return null;
        return parts;
    }
    function collectPageEls(pi){
        const pg=(doc.pages||[])[pi]; const out=[];
        if(!pg) return out;
        // 그림(이미지) 영역 위에 놓인 글자는 번역에서 제외
        const imgs=(pg.els||[]).filter(e=>e.type==='image'&&!e.isBg);
        const overImg=(el)=>{
            if(!imgs.length) return false;
            return imgs.some(im=>{
                const iw=im.w||0, ih=im.h||0, ew=el.w||0, eh=el.h||0;
                if(!iw||!ih||im.x==null||im.y==null||el.x==null||el.y==null) return false;
                return el.x>=im.x-2 && el.y>=im.y-2 &&
                       el.x+ew<=im.x+iw+2 && el.y+eh<=im.y+ih+2;
            });
        };
        (pg.els||[]).forEach(el=>{
            if(el.type!=='text'||el.locked) return;
            let src=el.tight? tightTextFromHtml(el.html) : plainTextFromHtml(el.html);
            src=(src||'').replace(/\s+/g,' ').trim();
            if(!src) return;
            if(isFigureText(el,src)||overImg(el)) return;   // 6.6: 피규어/캡션은 제외
            out.push({el,src,pi});
        });
        return out;
    }
    let trBusy=false;
    // 15.0 · 무료 번역 엔진은 요청이 몰리면 잠깐 제한(429)된다. 그럴 땐
    //   기다렸다가 다시 시도한다 — 문서 전체 번역이 중간에 통째로 실패하지 않게.
    async function apiTranslateRetry(src,target,gloss){
        for(let a=0;a<3;a++){
            if(trCancel) throw new Error(TR_CANCEL);
            try{ return await apiTranslate(src,target,gloss); }
            catch(e){
                const msg=String(e&&e.message||'');
                if(msg===TR_CANCEL) throw e;                 // 사용자 중단은 재시도하지 않는다
                if(a>=2||!/제한|429|닿지 않/.test(msg)) throw e;
                await trSleep(9000*(a+1));                   // 대기 중에도 중단 즉시 반영
            }
        }
    }
    async function translateEls(list,target,label){
        if(trBusy||trCtl){ toast('번역이 이미 진행 중입니다 — 진행바의 [중단] 을 누르거나 잠시 기다려 주세요',2400); return; }
        if(!list.length){ toast('번역할 텍스트 상자가 없습니다',1800); return; }
        trBusy=true;
        beginTrTask();
        let failCnt=0, lastErr='', okCnt=0;
        const remaining=()=>q.reduce((n,p)=>n+((p&&p.items)||[p]).length,0);
        let q=[];
        try{
            showTrProg(0,label+' · 번역 준비… · 중단하려면 [중단]/Esc');
            pushHistory();                                 // 되돌리기 한 번으로 전체 복구
            const jobs=list.filter(o=>{
                if(trLooksTarget(o.src,target)){ okCnt++; return false; }
                return true;
            });
            const packs=packTrJobs(jobs);
            q=packs.slice();
            const totalPacks=Math.max(1,packs.length);
            const worker=async()=>{
                while(q.length&&!trCancel){
                    const pack=q.shift();
                    const items=pack.items||[pack];
                    const done=okCnt+failCnt;
                    showTrProg(done/Math.max(1,list.length),
                        label+' · 번역 '+Math.min(done+items.length,list.length)+'/'+list.length
                        +(failCnt?' · 실패 '+failCnt:'')+' · 중단: [중단]/Esc');
                    try{
                        if(items.length===1){
                            const out=await apiTranslateRetry(items[0].src,target,doc.glossary);
                            if(applyTrResult(items[0],out)) okCnt++;
                        }else{
                            const joined=joinTrPack(items);
                            const out=await apiTranslateRetry(joined,target,doc.glossary);
                            const parts=splitTrPack(out,items.length);
                            if(parts){
                                items.forEach((o,i)=>{ if(applyTrResult(o,parts[i])) okCnt++; else failCnt++; });
                            }else if(/제한|429/.test(String(out||''))){
                                failCnt+=items.length;
                                lastErr='지금 번역 요청이 몰려 잠시 제한됐어요';
                            }else{
                                // 구분자가 깨지면 그 묶음만 상자별로 한 번 더 (429는 안 함)
                                for(const o of items){
                                    if(trCancel){ q.unshift({items:items.slice(items.indexOf(o))}); break; }
                                    try{
                                        const one=await apiTranslateRetry(o.src,target,doc.glossary);
                                        if(applyTrResult(o,one)) okCnt++; else failCnt++;
                                    }catch(e){
                                        if(e&&e.message===TR_CANCEL){ q.unshift({items:[o]}); break; }
                                        failCnt++; lastErr=String(e&&e.message||'');
                                        if(/제한|429/.test(lastErr)){
                                            const rest=items.slice(items.indexOf(o)+1);
                                            failCnt+=rest.length;
                                            break;
                                        }
                                    }
                                }
                            }
                        }
                    }catch(e){
                        if(e&&e.message===TR_CANCEL){ q.unshift(pack); }
                        else {
                            failCnt+=items.length;
                            lastErr=String(e&&e.message||'');
                        }
                    }
                    await trSleep(packs.length>8?80:160);
                }
            };
            // 논문은 묶음이 이미 커서 일꾼 2개면 한도만 더 깎인다. 묶음이 많을 때만 2개.
            await Promise.all(totalPacks>=6?[worker(),worker()]:[worker()]);
            // 중단했어도 이미 완료된 상자는 유실하지 않고 저장한다
            await persistTranslatedChange();
            learnGlossary(list.map(o=>o.src),target)
                .then(n=>{ if(n){ try{ saveDoc(); queueOps(); }catch(e){} } })
                .catch(()=>{});
            const left=remaining();
            if(trCancel){
                toast(label+' 번역을 중단했어요 · 완료한 '+okCnt+'개 상자는 저장했습니다'
                    +(left?' · 남은 '+left+'개 상자는 원문 유지':''),3200);
            }
            // 15.0 · 실패한 상자가 있으면 '완료'라고만 알리지 않는다 —
            //   다 번역 안 됐는데 완료로 보이던 문제.
            else if(failCnt>=list.length){
                toast('번역에 실패했어요 · '+(lastErr||'잠시 뒤 다시 시도해 주세요'),3600);
            }else if(failCnt){
                toast(label+' 번역 부분 완료 · '+failCnt+'개 상자는 실패 (잠시 뒤 다시 눌러 주세요)',3200);
            }else{
                toast(label+' 번역 완료 · 저장됨 ('+list.length+'개 상자)',2400);
            }
        }catch(e){
            toast('번역 결과 저장 실패: '+String(e&&e.message||'다시 시도해 주세요'),3600);
        }finally{ trBusy=false; endTrTask(); }
    }
    async function translatePageAction(pi,target){
        if(trBusy||trCtl){ toast('번역이 이미 진행 중입니다 — 진행바의 [중단] 을 누르거나 잠시 기다려 주세요',2400); return; }
        closeCtxMenu();
        try{ await ensureLazyPage(pi); }catch(e){}
        const list=collectPageEls(pi);
        await translateEls(list,target,(pi+1)+'페이지');
    }
    async function translateDocAction(target){
        if(trBusy||trCtl){ toast('번역이 이미 진행 중입니다 — 진행바의 [중단] 을 누르거나 잠시 기다려 주세요',2400); return; }
        closeCtxMenu();
        const total=(doc.pages||[]).length;
        // 대용량(서버 보관) 문서는 먼저 전부 불러온다 → 번역이 중간에 끊기지 않게
        if(doc.__ref&&(doc.pages||[]).some(p=>p.__lazy!=null)){
            showTrProg(0,'문서 전체 불러오는 중…');
            try{ await loadAllLazyNoEvict(); }catch(e){}
        }
        const list=[];
        for(let i=0;i<total;i++){
            showTrProg(i/Math.max(1,total),'문서 로딩 '+(i+1)+'/'+total);
            const got=collectPageEls(i);
            got.forEach(o=>list.push(o));
        }
        hideTrProg();
        await translateEls(list,target,'문서 전체');
    }
    try{
        window.__sdyTranslate={
            page:translatePageAction,
            doc:translateDocAction,
            getDoc:()=>doc,
            pack:packTrJobs,
        };
    }catch(e){}
    /* ============ /6.1 번역 ============ */

    // 가져온(tight) 상자에서 복사 시: 절대스팬 사이 줄바꿈을 공백으로 정돈해
    // 외부에 붙여넣어도 깔끔한 문장으로 나가게 한다.
    document.addEventListener('copy',e=>{
        try{
            const sel=window.getSelection();
            if(!sel||sel.isCollapsed) return;
            const n=sel.anchorNode
                ? (sel.anchorNode.nodeType===1?sel.anchorNode:sel.anchorNode.parentElement)
                : null;
            const host=n&&n.closest('.tb-content');
            if(!host||!host.closest('.tight')) return;
            // 외부(구글 등) 붙여넣기용: 공백 재조립 + 줄바꿈→공백
            const clean=tightSelectionText(sel).replace(/\n+/g,' ').replace(/\s{2,}/g,' ').trim();
            if(!clean) return;
            e.clipboardData.setData('text/plain',clean);
            e.preventDefault();
        }catch(err){}
    });

    // ============ 여러 기기 실시간 반영 (적응형 폴링) ============
    // 예전엔 20초 고정이라 다른 기기의 변경이 한참 뒤에 보였다.
    // 지금은 '방금 뭔가 오갔으면 빠르게(1.2초), 조용하면 천천히(15초)'.
    // 화면이 가려져 있으면 아예 쉰다 → 배터리·버벅임 없음.
    let liveSyncTimer=null, _syncGap=1200, _syncBusy=false, _syncQuiet=0;
    const SYNC_FAST=1200, SYNC_SLOW=15000;
    function stopLiveDocSync(){
        if(liveSyncTimer){ clearTimeout(liveSyncTimer); liveSyncTimer=null; }
    }
    function _armSync(gap){
        stopLiveDocSync();
        liveSyncTimer=setTimeout(liveDocTick, gap==null?_syncGap:gap);
    }
    // 내가 편집했을 때: 잠시 빠른 주기로 (상대 변경도 곧바로 받도록)
    function syncBoost(){
        _syncQuiet=0;
        if(_syncGap!==SYNC_FAST){ _syncGap=SYNC_FAST; _armSync(SYNC_FAST); }
    }
    async function startLiveDocSync(){
        // 14.15 · 요청을 보내는 사이에 다른 노트를 열었으면 이 결과를
        //   새 노트 doc 에 넣지 않는다.
        const d=doc, nid=(curNB&&curNB.id)||null;
        stopLiveDocSync();
        try{
            if(d&&d.__ref){
                const r=await fetch('/api/import/docfile/'
                    +encodeURIComponent(d.__ref)+'?meta=1',{cache:'no-store'});
                const m=await r.json().catch(()=>({}));
                if(doc!==d||!curNB||curNB.id!==nid) return;
                if(m&&m.ok) d.__ver=m.version;
            }else if(SB&&curMemo&&curMemo.updated_at&&doc===d){
                d.__sbVer=curMemo.updated_at;
            }
        }catch(e){}
        if(doc!==d||!curNB||curNB.id!==nid) return;
        _syncGap=SYNC_FAST; _syncQuiet=0;
        _armSync(SYNC_FAST);
    }
    let _impReloading=false;
    async function reloadImportedIfNewer(){
        // 가져온 PDF: 요소 ops 없이 슬라이스만 갱신된 번역/편집을 받는다.
        const d=doc;                    // 14.9 · 노트 전환 후 이어지는 리로드를 차단
        if(!d||!d.__ref||trBusy||_impReloading) return 0;
        _impReloading=true;
        try{
            const r=await fetch('/api/import/docfile/'+encodeURIComponent(d.__ref)+'?meta=1',{cache:'no-store'});
            const m=await r.json().catch(()=>({}));
            if(!(m&&m.ok&&m.version)) return 0;
            if(doc!==d) return 0;
            const prev=d.__ver||0;
            if(!(prev && m.version>prev+0.05)){
                d.__ver=m.version;
                return 0;
            }
            let got=0;
            const n=(d.pages||[]).length;
            for(let s0=0;s0<n;s0+=LAZY_SLICE){
                if(doc!==d) return got;
                let dirty=false;
                for(let i=s0;i<Math.min(n,s0+LAZY_SLICE);i++){
                    if(d.pages[i]&&d.pages[i].__dirty){ dirty=true; break; }
                }
                if(dirty) continue;
                for(let i=s0;i<Math.min(n,s0+LAZY_SLICE);i++){
                    if(d.pages[i]&&d.pages[i].__lazy==null)
                        d.pages[i]={id:'lazy_'+i,els:[],tables:[],__lazy:1};
                }
                await loadBatch(s0);
                if(doc!==d) return got;
                for(let i=s0;i<Math.min(n,s0+LAZY_SLICE);i++){
                    if(renderedPages.has(i)) renderPageEls(i);
                }
                got++;
            }
            d.__ver=m.version;
            return got;
        }catch(e){ return 0; }
        finally{ _impReloading=false; }
    }
    async function liveDocTick(){
        if(!doc||!curNB){ _armSync(SYNC_SLOW); return; }
        // 안 보이는 탭에서는 쉬고, 편집·번역 중에는 건드리지 않는다
        if(document.hidden||document.querySelector('#pagesStage .tb.edit')||trBusy){
            _armSync(SYNC_FAST); return;
        }
        if(_syncBusy){ _armSync(); return; }
        _syncBusy=true;
        let got=0;
        try{ const ops=await pullSync(false); got=(ops&&ops.length)||0; }
        catch(e){}
        try{ got+=await reloadImportedIfNewer(); }
        catch(e){}
        finally{ _syncBusy=false; }
        // 변화가 있으면 계속 빠르게, 조용한 시간이 이어지면 서서히 늦춘다
        if(got){ _syncQuiet=0; _syncGap=SYNC_FAST; }
        else if(++_syncQuiet>=6) _syncGap=Math.min(SYNC_SLOW, _syncGap*1.6);
        _armSync();
    }
    // 다른 탭/창으로 갔다 오면 즉시 한 번 맞춘다
    document.addEventListener('visibilitychange',()=>{
        if(!document.hidden&&curNB&&doc){ _syncGap=SYNC_FAST; _armSync(120); }
    });

    // ===== 요소 단위 실시간 동기화 (구글독스식 LWW, 전체 덮어쓰기 없음) =====
    const SYNC_DEV=(()=>{ try{ let v=localStorage.getItem('sdy_dev');
        if(!v){ v='d_'+Math.random().toString(36).slice(2,10);
            localStorage.setItem('sdy_dev',v); } return v; }catch(e){ return 'd_x'; } })();
    function syncState(){
        doc.__localRev=doc.__localRev||new Map();
        doc.__lastHash=doc.__lastHash||new Map();
        doc.__base=doc.__base||new Map();      // 14.9 · 요소별 '공통 조상 html' (협업 병합용)
        doc.__baseRev=doc.__baseRev||new Map();// 14.9 · 공통 조상의 서버 rev (prevRev 전송용)
        return doc;
    }
    // 14.13 · 노트 요소 rev 시계 — 단조 증가 + pull 뒤 Lamport 캐치업.
    //   예전엔 Date.now() 원값을 써서, 시계가 몇 초 느린 기기(LTE 폰·PC 오차)의
    //   편집 rev 가 서버에 이미 있는 rev 보다 계속 작아졌다. 그러면 서버 LWW 가
    //   그 기기의 모든 이후 편집을 버려 "처음 몇 번만 동기화되고 이후엔 아예 안
    //   되고, 써 놓은 게 지워져 보이는" 증상이 생긴다. (설정 동기화는 14.9 에서
    //   이미 같은 문제를 이 방식으로 고쳤다 — 노트 편집기에만 빠져 있었다.)
    let _nbRev=Date.now();
    function _nbNow(){ _nbRev=Math.max(_nbRev+1, Date.now()+Math.random()); return _nbRev; }
    // ══════════════════════════════════════════════════════════════
    //  14.9 · 같은 텍스트상자 협업 편집 (구글독스식 3-way 병합)
    //   예전엔 상자 단위 LWW라서, 두 기기가 같은 상자를 동시에 타이핑하면
    //   한쪽 내용이 통째로 사라졌다. 이제 요소별로 '공통 조상(__base)'을
    //   기억하고, 원격 편집이 오면 3-way 병합(base·내것·상대것)으로
    //   양쪽 편집을 모두 남긴다. 충돌(같은 위치)은 결정적·대칭 규칙으로
    //   이어 붙여 양 기기가 같은 결과로 수렴한다.
    // ══════════════════════════════════════════════════════════════
    // HTML 을 '태그는 1단위, 글자는 1단위'로 쪼갠다 (태그를 반으로 자르지 않기 위함)
    function _sdyUnits(html){
        const units=[]; let buf='';
        for(let i=0;i<html.length;i++){
            const ch=html[i];
            if(ch==='<'){
                const end=html.indexOf('>',i);
                if(end>=0){ if(buf){ for(const c of buf) units.push(c); buf=''; } units.push(html.slice(i,end+1)); i=end; }
                else buf+=ch;
            }else buf+=ch;
        }
        if(buf) for(const c of buf) units.push(c);
        return units;
    }
    // base → v 의 편집 연산(들). 각 연산: {pos, del, ins[]} (base 기준, 겹치지 않음)
    function _sdyDiff(base,v){
        // 공통 접두/접미를 먼저 잘라 DP 범위를 줄인다 (덧붙임·끝삭제가 O(n)이 된다)
        const n=base.length, m=v.length;
        let p=0;
        while(p<n&&p<m&&base[p]===v[p]) p++;
        let s=0;
        while(s<n-p&&s<m-p&&base[n-1-s]===v[m-1-s]) s++;
        const bm=base.slice(p,n-s), vm=v.slice(p,m-s);
        const n2=bm.length, m2=vm.length;
        const dp=Array.from({length:n2+1},()=>new Int32Array(m2+1));
        for(let i=n2-1;i>=0;i--)
            for(let j=m2-1;j>=0;j--)
                dp[i][j]= bm[i]===vm[j] ? dp[i+1][j+1]+1 : Math.max(dp[i+1][j],dp[i][j+1]);
        const ops=[]; let i=0, j=0;
        while(i<n2&&j<m2){
            if(bm[i]===vm[j]){ i++; j++; continue; }
            const st=i, tj=j;
            while(i<n2&&j<m2&&bm[i]!==vm[j]){
                if(dp[i+1][j]>=dp[i][j+1]) i++; else j++;
            }
            ops.push({pos:p+st, del:i-st, ins:vm.slice(tj,j)});
        }
        if(i<n2) ops.push({pos:p+i, del:n2-i, ins:[]});
        else if(j<m2) ops.push({pos:p+i, del:0, ins:vm.slice(j)});
        // 인접한 '삭제'와 '삽입'을 하나의 '교체' hunk 로 합친다.
        // (안 합치면 같은 변경이 두 기기에서 중복 반영될 수 있다)
        const norm=[];
        for(const o of ops){
            if(!o.del&&!o.ins.length) continue;
            if(norm.length){
                const last=norm[norm.length-1];
                if(last.del>0&&last.ins.length===0&&o.del===0&&o.pos===last.pos+last.del){
                    last.ins=o.ins.slice(); continue;      // 삭제→삽입 = 교체
                }
                if(last.del===0&&o.del>0&&o.pos===last.pos){
                    last.del=o.del; continue;              // 삽입→삭제 = 교체
                }
            }
            norm.push({pos:o.pos, del:o.del, ins:o.ins.slice()});
        }
        return norm;
    }
    // 충돌 해소: 두 조각을 사전순으로 이어 붙인다. 병합 호출부가 (mine,theirs)를
    // 내용 기준으로 정렬해 부르므로 양 기기가 항상 같은 결과로 수렴한다.
    function _sdyResolve(a,b){
        const A=a.join(''),B=b.join('');
        return A<=B ? a.concat(b) : b.concat(a);
    }
    // hunk 들을 base[start..end) 구간에 적용해 그 구간의 '한쪽 버전 내용'을 만든다
    function _sdyApplyHunks(base,start,end,hunks,fromIdx){
        const out=[]; let p=start, k=fromIdx;
        while(k<hunks.length && hunks[k].pos<end){
            const h=hunks[k++];
            const delStart=Math.max(start,h.pos);
            const delEnd=Math.min(end, h.pos+h.del);
            out.push(...base.slice(p,delStart));
            out.push(...h.ins);
            p=delEnd;
        }
        out.push(...base.slice(p,end));
        return out;
    }
    // 3-way 병합: 두 diff(hunk 목록)를 base 위에서 합친다. 겹치는 구간만 충돌.
    function _sdyMerge3(o,a,b){
        const ha=_sdyDiff(o,a), hb=_sdyDiff(o,b);
        const res=[]; let pos=0, i=0, j=0;
        while(i<ha.length||j<hb.length){
            const A=i<ha.length?ha[i]:null;
            const B=j<hb.length?hb[j]:null;
            if(A&&(!B||A.pos+A.del<=B.pos)){
                res.push(...o.slice(pos,A.pos)); res.push(...A.ins);
                pos=A.pos+A.del; i++; continue;
            }
            if(B&&(!A||B.pos+B.del<=A.pos)){
                res.push(...o.slice(pos,B.pos)); res.push(...B.ins);
                pos=B.pos+B.del; j++; continue;
            }
            // 겹침 → 충돌 구간 [start,end) 확정 (연쇄 겹침까지 확장)
            const start=Math.min(A.pos,B.pos);
            let end=Math.max(A.pos+A.del,B.pos+B.del);
            const i0=i, j0=j;
            for(;;){
                let ext=false;
                while(i<ha.length&&ha[i].pos<end){ end=Math.max(end,ha[i].pos+ha[i].del); i++; ext=true; }
                while(j<hb.length&&hb[j].pos<end){ end=Math.max(end,hb[j].pos+hb[j].del); j++; ext=true; }
                if(!ext) break;
            }
            const ca=_sdyApplyHunks(o,start,end,ha,i0);
            const cb=_sdyApplyHunks(o,start,end,hb,j0);
            res.push(...o.slice(pos,start));
            res.push(...(ca.join('')===cb.join('') ? ca : _sdyResolve(ca,cb)));
            pos=end;
        }
        res.push(...o.slice(pos));
        return res;
    }
    function mergeText3(baseHtml,mineHtml,theirsHtml){
        const o=_sdyUnits(baseHtml||''), a=_sdyUnits(mineHtml||''), b=_sdyUnits(theirsHtml||'');
        return _sdyMerge3(o,a,b).join('');
    }
    function _elById(id){
        const loc=findElLoc(id); if(!loc) return null;
        return doc.pages[loc.i].els[loc.k];
    }
    // 내가 이 상자를 마지막 확정 상태 이후로 바꿨는가
    function _tbHasLocal(id){
        if(!doc||!doc.__base||!doc.__base.has(id)) return false;
        const el=_elById(id); if(!el) return false;
        return (el.html||'')!==doc.__base.get(id);
    }
    // ── 캐럿(커서) 유틸: textContent 기준 오프셋 ──
    function _tbCaretTextOffset(c){
        try{
            const sel=window.getSelection();
            if(sel&&sel.anchorNode&&c.contains(sel.anchorNode)){
                const walker=document.createTreeWalker(c,NodeFilter.SHOW_TEXT,null);
                let acc=0,n;
                while((n=walker.nextNode())){
                    if(n===sel.anchorNode) return acc+sel.anchorOffset;
                    acc+=n.nodeValue.length;
                }
            }
        }catch(e){}
        return (c.textContent||'').length;
    }
    function _tbSetCaretTextOffset(c,off){
        try{
            const walker=document.createTreeWalker(c,NodeFilter.SHOW_TEXT,null);
            let acc=0,n;
            while((n=walker.nextNode())){
                const len=n.nodeValue.length;
                if(acc+len>=off){
                    const r=document.createRange();
                    r.setStart(n,Math.max(0,off-acc)); r.collapse(true);
                    const sel=window.getSelection(); sel.removeAllRanges(); sel.addRange(r);
                    return;
                }
                acc+=len;
            }
        }catch(e){}
        try{
            const r=document.createRange();
            if(c.childNodes.length) r.setStartAfter(c.lastChild); else r.setStart(c,0);
            r.collapse(true);
            const sel=window.getSelection(); sel.removeAllRanges(); sel.addRange(r);
        }catch(e){}
    }
    // 편집 중인 상자 DOM 에 새 html 을 넣되, 내 커서를 최대한 보존한다
    function _tbApplyToActiveBox(id,newHtml){
        const box=document.querySelector('#pagesStage .tb.edit[data-id="'+id+'"]');
        if(!box) return false;
        const c=box.querySelector('.tb-content'); if(!c) return false;
        const off=_tbCaretTextOffset(c);
        const mineText=c.textContent||'';
        c.innerHTML=newHtml;
        const newText=c.textContent||'';
        let no=off;
        if(mineText!==newText){
            for(const e of _sdyDiff(Array.from(mineText),Array.from(newText))){
                if(e.pos<off) no+= e.ins.length - e.del;
            }
            if(no<0) no=0; if(no>newText.length) no=newText.length;
        }
        _tbSetCaretTextOffset(c,no);
        const em=!newText.trim();
        if(em) c.setAttribute('data-empty','true'); else c.removeAttribute('data-empty');
        box.classList.toggle('empty',em);
        return true;
    }
    // 원격 텍스트 op 를 내 로컬 편집과 3-way 병합한다. 변경 있으면 true.
    function _tbMergeRemote(op){
        const id=op.data.id, el=_elById(id); if(!el) return false;
        const theirs=op.data.html||'';
        const mine=el.html||'';
        const hasBase=doc.__base&&doc.__base.has(id);
        const base=hasBase?doc.__base.get(id):undefined;
        let merged;
        if(base===undefined || mine===base){
            merged=theirs;   // 로컬 변경 없음 → 원격 그대로 수용
        }else{
            const big=Math.max(base.length,mine.length,theirs.length);
            if(big>20000){ merged=theirs; }                     // 초대형 상자는 LWW 폴백
            else{                                               // (mine,theirs)를 내용 기준 정렬해
                const lo=mine<=theirs?mine:theirs;              //  부르면 양 기기가 같은 입력으로
                const hi=mine<=theirs?theirs:mine;              //  같은 병합 결과를 얻어 수렴한다.
                merged=mergeText3(base,lo,hi);
            }
        }
        // 원격 서식/스타일은 반영하되, 편집 중인 기하(x,y,w,h)는 내 것을 유지
        ['fontSize','font','align','color','bg','ls','wsp','lg','tight','tbl','locked','fit','fitDown'].forEach(k=>{
            if(op.data[k]!==undefined) el[k]=op.data[k];
        });
        const isActive=document.querySelector('#pagesStage .tb.edit[data-id="'+id+'"]')!==null;
        if(merged!==mine){
            el.html=merged;
            if(isActive) _tbApplyToActiveBox(id,merged);
            doc.__lastHash.delete(id);          // 병합본을 다시 push 하도록
            doc.__base.set(id,theirs);          // rebase: 내 편집은 이제 상대것 위에
            if(doc.__baseRev) doc.__baseRev.set(id, op.rev||0);
            return true;
        }
        doc.__base.set(id,theirs);
        if(doc.__baseRev) doc.__baseRev.set(id, op.rev||0);
        if(hasBase) doc.__lastHash.set(id,JSON.stringify(el));
        return false;
    }
    async function initSync(){
        if(!doc||!curNB) return;
        // 14.14 · 노트 전환 중 이전 노트의 initSync 가 이어지면 새 노트 맵을
        //   비우거나 엉뚱한 ops 를 푸시할 수 있다. 시작 시점 신원을 고정.
        const _d0=doc, _nb0=curNB.id;
        syncState();
        doc.__localRev.clear(); doc.__lastHash.clear();
        doc.__base.clear(); doc.__baseRev.clear();
        doc.__pagesRev=0; doc.__since=0;
        const pulled=await pullSync(false);
        if(doc!==_d0||!curNB||curNB.id!==_nb0) return;
        // 원격에서 받은 요소는 해시 등록(재푸시 방지),
        // 서버에 없던 로컬 요소는 초기 상태로 푸시(양방향 기반 공유)
        const remoteIds=new Set((pulled||[]).map(o=>o.id));
        const ops=[];
        const skipPush=!!doc.__ref; // 가져온 PDF: 슬라이스가 원본. 열자마자 원문을 푸시하면 번역이 덮인다.
        (doc.pages||[]).forEach((pg,pi)=>{(pg.els||[]).forEach(el=>{
            doc.__lastHash.set(el.id,JSON.stringify(el));
            doc.__base.set(el.id, el.html||'');   // 14.9 · 초기 공통 조상 = 현재 내용
            doc.__baseRev.set(el.id, doc.__localRev.get(el.id)||0);
            if(skipPush) return;
            if(!remoteIds.has(el.id)){
                const rev=_nbNow();
                doc.__localRev.set(el.id,rev);
                ops.push({id:el.id,kind:'put',page:pi,rev,data:el,dev:SYNC_DEV});
            }
        });});
        doc.__lastPages=(doc.pages||[]).map(p=>p.id).join(',');
        if(doc!==_d0||!curNB||curNB.id!==_nb0) return;
        if(ops.length) await pushOps(ops);
        // pull 로 본문이 채워졌을 수 있으니 다시 한 번 강제 페인트
        if(doc===_d0) try{ ensureVisiblePagesRendered(); }catch(e){}
    }
    async function startSlicePrefill(){
        const d=doc;                    // 14.9 · 노트 전환 후 이어지는 프리필을 차단
        if(!d||!d.__ref) return;
        try{
            const mr=await fetch('/api/import/docfile/'+encodeURIComponent(d.__ref)
                +'?meta=1',{cache:'no-store'});
            const m=await mr.json().catch(()=>({}));
            const total=m.total||0; if(!total) return;
            if(doc!==d) return;
            const loaded=new Set();
            (d.pages||[]).forEach((p,i)=>{
                if(p.__lazy==null) loaded.add(Math.floor(i/LAZY_SLICE)*LAZY_SLICE); });
            const q=[]; for(let s=0;s<total;s+=LAZY_SLICE) if(!loaded.has(s)) q.push(s);
            let k=0;
            const worker=async()=>{
                while(k<q.length){
                    if(doc!==d) return; // 14.9 · 그 사이 다른 노트를 열었으면 중단
                    const s=q[k++];
                    try{
                        const dd=await fetchSlice(d.__ref,s,(d.pages||[]).length);
                        if(doc!==d) return;
                        if(dd&&Array.isArray(dd.pages)){
                            dd.pages.forEach((p,j)=>{
                                const i=s+j;
                                if(i<(d.pages||[]).length&&d.pages[i].__lazy!=null&&!d.pages[i].__dirty){
                                    d.pages[i]=p;
                                    if(doc===d&&renderedPages.has(i)) renderPageEls(i);
                                }
                            });
                        }
                    }catch(e){}
                }
            };
            await Promise.all(Array.from({length:Math.min(4,q.length)},worker));
        }catch(e){}
    }
    async function pullSync(init){
        try{
            if(!curNB||!doc) return [];
            // 14.13 · 노트 전환 경쟁 방지: pull 사이에 다른 노트를 열면 응답 ops 가
            //   새 노트의 doc 에 적용돼 '다른 문서 내용이 덮어 나오는' 사고가 난다.
            //   (push 는 14.6 에서 막았지만 pull 에는 가드가 없었다)
            const _d0=doc, _nb0=curNB.id;
            // 14.8 · since(전역 커서)로 걸러내지 않는다. rev 는 각 기기의 시계로
            //   찍히므로, 시계가 조금만 느린 기기의 편집은 '이미 지난 rev'로 오인돼
            //   영영 안 받아지던 버그가 있었다. 항상 전체를 받고, 아래 __localRev
            //   (요소별 LWW)로 이미 반영한 것/내 최신 편집만 걸러낸다.
            const r=await fetch('/api/sync/pull?nb='+encodeURIComponent(curNB.id)
                +'&since=0',{cache:'no-store'});
            const d=await r.json(); if(!r.ok||!d.ok) return [];
            if(doc!==_d0||!curNB||curNB.id!==_nb0) return [];
            // 14.13 · Lamport 시계 캐치업: 서버가 본 최대 rev 로 내 시계를 올려,
            //   시계가 느린 기기의 다음 편집도 서버 LWW 에서 이기게 한다.
            _nbRev=Math.max(_nbRev, d.version||0);
            let ops=(d.ops||[]).slice().sort((a,b)=>(a.rev||0)-(b.rev||0));
            // 14.15 · 서버 pull 은 __pages__ 를 별도 필드(pages)로 돌려준다.
            //   ops 에는 pages 가 포함되지 않으므로, 처음 열거나 늦게 pull 한
            //   기기는 추가/삭제된 페이지를 전혀 못 받았다. 여기서 상태 페이지를
            //   __pages__ op 으로 합성해 맨 앞에 붙여 같은 적용 경로를 태운다.
            {
                const rp=(d&&d.pages)||null;
                if(rp && parseFloat(rp.rev||0) > (doc.__pagesRev||0)){
                    ops=[{id:'__pages__',kind:'pages',dev:'server',
                          rev:parseFloat(rp.rev||0),
                          ids:Array.isArray(rp.ids)?rp.ids:[]}, ...ops];
                }
            }
            // 14.13 · __pages__ op(페이지 목록)을 요소 op 보다 먼저 적용한다.
            //   새 페이지가 생긴 직후의 요소 op 이 페이지 목록보다 먼저 오면
            //   upsertEl 이 index 를 '마지막 페이지'로 잘라 붙여, 한 페이지의
            //   내용이 엉뚱한 페이지/문서 위에 복사돼 보였다.
            const _pgs=ops.filter(o=>o.id==='__pages__');
            const ordered=_pgs.length?_pgs.concat(ops.filter(o=>o.id!=='__pages__')):ops;
            _stCacheReset=false;
            let changed=false; const chPages=new Set();

            // 현재 로컬 사용자가 편집 중인 텍스트 상자 ID 파악
            const activeEditEl=document.querySelector('#pagesStage .tb.edit');
            const activeEditId=activeEditEl?activeEditEl.dataset.id:null;
            const activeEditPage=activeEditEl?parseInt(activeEditEl.dataset.pageIdx,10):-1;

            for(const op of ordered){
                if(doc!==_d0) return [];   // 14.13 · 루프 안 await(loadBatch) 너머로 노트가 바뀌면 중단
                if(op.id==='__pages__'){
                    if((op.rev||0)>(doc.__pagesRev||0)){
                        applyPagesOp(op);
                        // 14.15 · 방금 받은 페이지 목록을 '_lastPages' 에 반영해
                        //   같은 목록을 곧장 재푸시(pages rev 소모)하지 않는다.
                        if(doc) doc.__lastPages=(doc.pages||[]).map(p=>p.id).join(',');
                        changed=true; chPages.add(-1);
                    }
                    continue;
                }
                const local=doc.__localRev.get(op.id)||0;
                const isText=op.data&&op.data.type==='text';
                if(isText){
                    // 14.9 · 텍스트는 서버가 3-way 병합한다. 내 rev 와 같아도
                    //  내용이 다르면(=서버가 병합한 결과) 적용하고, 같으면(echo) 건너뛴다.
                    if((op.rev||0)<local) continue;
                    if((op.rev||0)===local){
                        const el=_elById(op.data.id);
                        if(!el||(el.html||'')===(op.data.html||'')) continue;
                    }
                }else{
                    if((op.rev||0)<=local) continue;
                }
                // 14.8 · 삭제 대신 반영한 rev 를 기억한다. since=0 로 매번 전체를
                //  받으므로, 이미 반영한 원격 op 를 또 적용하는 낭비/깜빡임을 막는다.
                doc.__localRev.set(op.id, op.rev||0);
                const activeBox=activeEditId&&op.id===activeEditId;
                const hasLocal=isText&&_tbHasLocal(op.id);
                if(op.del){
                    // 14.9 · 내가 편집 중이거나 로컬 수정이 있는 텍스트상자의 원격
                    //  삭제는 무시하고 내 최신본을 다시 올려 상자를 되살린다.
                    if(activeBox||hasLocal){
                        doc.__lastHash.delete(op.id);
                        doc.__base.delete(op.id); doc.__baseRev.delete(op.id);
                        queueOps();
                        continue;
                    }
                    if(removeElById(op.id)){ changed=true; chPages.add(op.page||0);
                        doc.__lastHash.delete(op.id);
                        doc.__base.delete(op.id); doc.__baseRev.delete(op.id); }
                }else if(op.data){
                    if(isText&&(activeBox||hasLocal)&&_elById(op.data.id)){
                        // 14.9 · 협업 병합: 내/상대 편집을 모두 남긴다
                        if(_tbMergeRemote(op)){ changed=true; chPages.add(op.page||0); queueOps(); }
                    }else if(await upsertEl(op.data,op.page||0)){
                        changed=true; chPages.add(op.page||0);
                        doc.__lastHash.set(op.data.id,JSON.stringify(op.data));
                        if(isText){
                            doc.__base.set(op.data.id, op.data.html||'');
                            doc.__baseRev.set(op.data.id, op.rev||0);
                        }
                    }
                }
            }
            if(doc!==_d0) return [];   // 14.13 · 마지막 await 뒤에도 노트가 같은지 확인
            doc.__since=d.version||0;
            if(changed){
                if(chPages.has(-1)){
                    renderPages();
                }else{
                    chPages.forEach(pi=>{
                        if(renderedPages.has(pi)){
                            if(activeEditEl&&activeEditPage===pi){
                                _selectiveRenderPage(pi,activeEditId);
                            }else{
                                renderPageEls(pi);
                            }
                        }
                    });
                    // 14.14 · pull 로 새 요소가 들어왔는데 해당 쪽이 아직 IO 로
                    //   안 그려져 있으면 강제 페인트 (빈 종이 유지 방지)
                    try{ ensureVisiblePagesRendered(); }catch(e){}
                }
            }
            // 요소 ops 가 비어도 가져온 문서 슬라이스(번역)가 갱신됐을 수 있다.
            if(doc.__ref && !trBusy){
                try{ await reloadImportedIfNewer(); }catch(e){}
            }
            return ops;
        }catch(e){ console.warn('sync pull 실패',e); return []; }
    }

    function _selectiveRenderPage(idx, activeId){
        const paper=paperAt(idx); if(!paper) return;
        const txtL=paper.querySelector('.layer-text');
        const svg=paper.querySelector('.layer-stroke');
        const imgL=paper.querySelector('.layer-img');
        const els=(doc.pages&&doc.pages[idx]&&doc.pages[idx].els)||[];
        els.forEach(el=>{
            if(el.id===activeId) return;
            let domEl=paper.querySelector(`[data-id="${el.id}"]`);
            if(domEl){
                if(el.type==='text'){
                    domEl.style.left=el.x+'px'; domEl.style.top=el.y+'px';
                    domEl.style.width=el.w+'px'; domEl.style.height=el.h+'px';
                    const c=domEl.querySelector('.tb-content');
                    if(c&&c.innerHTML!==el.html) c.innerHTML=el.html||'';
                }
            }else{
                if(el.type==='text'&&txtL) txtL.appendChild(buildTextEl(el,idx));
                else if(el.type==='stroke'&&svg) svg.appendChild(buildStrokeEl(el,idx));
                else if(el.type==='image'&&imgL) imgL.appendChild(buildImageEl(el,idx));
                else if(el.type==='latex'&&txtL) txtL.appendChild(buildLatexEl(el,idx));
            }
        });
        const currentDomEls=paper.querySelectorAll('[data-id]');
        const validIds=new Set(els.map(e=>e.id));
        currentDomEls.forEach(d=>{
            if(d.dataset.id!==activeId&&!validIds.has(d.dataset.id)) d.remove();
        });
    }
    async function retryPage(idx){
        const d=doc;                    // 14.9 · 노트 전환 후 이어지는 재시도를 차단
        if(!d||!d.__ref) return;
        // 14.12 · renderVersion 도 함께 검증
        if(window._renderVersion !== (d&&d.__rv)) return;
        const s0=Math.floor(idx/LAZY_SLICE)*LAZY_SLICE;
        try{
            const dd=await fetchSlice(d.__ref,s0,(d.pages||[]).length);
            if(doc!==d) return;
            if(window._renderVersion !== (d&&d.__rv)) return;
            if(dd&&Array.isArray(dd.pages)){
                dd.pages.forEach((p,j)=>{ const i=s0+j;
                    if(i>=(d.pages||[]).length) return;
                    const cur=d.pages[i];
                    if(cur&&(cur.__dirty||(cur.__lazy==null&&(cur.els||[]).length))) return;
                    d.pages[i]=p; });
            }
        }catch(e){}
        // renderPageEls 에서도 검증하므로 여기서는 doc===d 만 확인
        if(doc===d) renderPageEls(idx);
    }
    function rehashAll(){
        doc.__lastHash.clear();
        (doc.pages||[]).forEach(pg=>(pg.els||[]).forEach(el=>{
            doc.__lastHash.set(el.id,JSON.stringify(el)); }));
        doc.__lastPages=(doc.pages||[]).map(p=>p.id).join(',');
    }
    function findElLoc(id){
        for(let i=0;i<(doc.pages||[]).length;i++){
            const els=doc.pages[i].els||[];
            const k=els.findIndex(e=>e.id===id);
            if(k>=0) return {i,k};
        }
        return null;
    }
    function removeElById(id){
        const loc=findElLoc(id); if(!loc) return false;
        doc.pages[loc.i].els.splice(loc.k,1); return true;
    }
    async function upsertEl(data,page){
        let pi=Math.min(page,(doc.pages||[]).length-1);
        if(pi<0) return false;
        if(doc.pages[pi]&&doc.pages[pi].__lazy!=null) await loadBatch(pi);
        const loc=findElLoc(data.id);
        if(loc){
            if(loc.i!==pi){
                doc.pages[loc.i].els.splice(loc.k,1);
                (doc.pages[pi].els=doc.pages[pi].els||[]).push(data);
            }else{
                doc.pages[loc.i].els[loc.k]=data;
            }
        }else{
            (doc.pages[pi].els=doc.pages[pi].els||[]).push(data);
        }
        return true;
    }
    function applyPagesOp(op){
        doc.__pagesRev=op.rev||0;
        const ids=op.ids||[];
        const oldPages=(doc.pages||[]).slice();
        const byId={}; oldPages.forEach(p=>{ if(p&&p.id) byId[p.id]=p; });
        // 14.14 · 페이지 id 가 기기마다 다르게 찍힌 경우(옛 버그·복제·충돌),
        //   id 로 못 찾으면 같은 자리(index)에 있던 본문을 살려 빈 페이지로
        //   교체하지 않는다. 예전엔 byId 미스 → {id,els:[]} 로 바꿔
        //   메모 채널에 있던 글·그림이 실시간 pull 한 번에 통째로 사라졌다.
        doc.pages=ids.map((id,i)=>{
            if(byId[id]) return byId[id];
            const old=oldPages[i];
            const hasBody=old&&(
                ((old.els||[]).length)>0||
                ((old.tables||[]).length)>0||
                ((old.notes||[]).length)>0||
                old.__lazy!=null
            );
            if(hasBody){
                // 서버 순서의 id 로만 맞추고 본문·lazy 마커는 유지
                if(old.id!==id) old.id=id;
                return old;
            }
            return {id,els:[],tables:[]};
        });
    }
    function genOps(){
        syncState();
        const ops=[];
        const seen=new Set();
        (doc.pages||[]).forEach((pg,pi)=>{
            (pg.els||[]).forEach(el=>{
                seen.add(el.id);
                const h=JSON.stringify(el);
                if(doc.__lastHash.get(el.id)!==h){
                    doc.__lastHash.set(el.id,h);
                    const rev=_nbNow();
                    doc.__localRev.set(el.id,rev);
                    ops.push({id:el.id,kind:'put',page:pi,rev,data:el,dev:SYNC_DEV,
                              prevRev:(doc.__baseRev&&doc.__baseRev.get(el.id))||0});
                }
            });
        });
        doc.__lastHash.forEach((h,id)=>{
            if(!seen.has(id)){
                const rev=_nbNow();
                doc.__localRev.set(id,rev);
                ops.push({id,kind:'del',rev,dev:SYNC_DEV});
                doc.__lastHash.delete(id);
            }
        });
        const ph=(doc.pages||[]).map(p=>p.id).join(',');
        if(doc.__lastPages!==ph){
            doc.__lastPages=ph;
            const rev=_nbNow();
            doc.__pagesRev=rev;
            ops.push({id:'__pages__',kind:'pages',rev,
                ids:(doc.pages||[]).map(p=>p.id),dev:SYNC_DEV});
        }
        return ops;
    }
    let opsTimer=null;
    function queueOps(){
        clearTimeout(opsTimer);
        // 400ms → 180ms: 상대 화면에 더 빨리 뜬다.
        // (그래도 묶어서 보내므로 타자 칠 때마다 요청이 나가진 않는다)
        opsTimer=setTimeout(pushOps,180);
        try{ syncBoost(); }catch(e){}
    }
    async function pushOps(pre){
        if(!doc||!curNB) return;
        const d0=doc;
        const ops=pre||genOps();
        if(!ops.length) return;
        // 14.6 · 노트 id 를 시작 시점에 고정한다. 전송 중 다른 노트로 넘어가면
        //  curNB.id 가 바뀌어 이 노트의 요소 ops 가 엉뚱한 노트로 저장되던 버그 방지.
        const nbId=curNB.id;
        const send=async(batch)=>{
            for(let attempt=0; attempt<3; attempt++){
                try{
                    const r=await fetch('/api/sync/push',{method:'POST',
                        headers:{'Content-Type':'application/json'},
                        body:JSON.stringify({nb:nbId,ops:batch})});
                    const d=await r.json().catch(()=>({}));
                    if(r.ok&&d.ok){
                        // 14.7 · 서버 전역 version 으로 doc.__since 를 올리지 않는다.
                        //  예전엔 여기서 since 를 서버 version(모든 요소의 최대 rev)으로
                        //  끌어올려서, 그 사이 다른 기기가 올린 rev 를 '이미 본 것'으로
                        //  오인해 실시간 동시 편집에서 상대 변경이 안 보였다.
                        // 14.9 · 수용된 텍스트 put 은 공통 조상(__base)으로 확정한다.
                        const acc=new Set(Array.isArray(d.accepted)?d.accepted:batch.map(o=>o.id));
                        batch.forEach(o=>{
                            if(acc.has(o.id)&&o.kind==='put'&&o.data&&o.data.type==='text'&&doc&&doc.__base){
                                doc.__base.set(o.id, o.data.html||'');
                                if(doc.__baseRev) doc.__baseRev.set(o.id, parseFloat(o.rev||0)||0);
                            }
                        });
                        return true;
                    }
                }catch(e){}
                await new Promise(res=>setTimeout(res, 250*(attempt+1)));
            }
            return false;
        };
        const CHUNK_OPS=40;
        const failedIds=[];
        for(let i=0;i<ops.length;i+=CHUNK_OPS){
            const batch=ops.slice(i,i+CHUNK_OPS);
            if(!(await send(batch))) failedIds.push(...batch.filter(o=>o.kind==='put').map(o=>o.id));
        }
        // 14.13 · 전송 실패한 put 은 '이미 보낸 상태' 표시(__lastHash)를 걷어낸다.
        //   genOps 가 보내기 전에 해시를 갱신하므로, LTE 순단처럼 push 가 실패하면
        //   편집이 영영 재전송되지 않고 뒤늦은 pull 이 서버 쪽 옛 내용으로 화면을
        //   덮어 '써 놓은 게 지워진' 것처럼 보였다.
        if(failedIds.length){
            failedIds.forEach(id=>{ try{ d0.__lastHash.delete(id); }catch(e){} });
            if(doc===d0&&curNB&&curNB.id===nbId)
                setTimeout(()=>{ try{ if(doc===d0&&curNB&&curNB.id===nbId) pushOps(); }catch(e){} },3000);
        }
        // 14.7 · push 직후 pull 로 맞춘다. 내 ops 는 __localRev 로 건너뛰고,
        //  그 사이 온 다른 기기의 변경만 받아 적용해 동시 편집이 어긋나지 않게 한다.
        try{ if(curNB&&curNB.id===nbId) await pullSync(false); }catch(e){}
        try{ queueImportedSave(); }catch(e){}
    }

    // ============ 실시간 커서 공유 ============
    // 같은 노트를 여러 사람이 열면 서로의 마우스를 색깔 화살표로 보여준다.
    const LIVE_ME=(()=>{ try{
        let v=localStorage.getItem('sdy_uid');
        if(!v){ v='u_'+Math.random().toString(36).slice(2,10); localStorage.setItem('sdy_uid',v); }
        return v;
    }catch(e){ return 'u_'+Math.random().toString(36).slice(2,10); } })();
    // 이름을 따로 정하지 않았으면 '푸른 두루미' 같은 이름을 하나 지어 준다.
    const LIVE_ADJ=['연보라','복숭아빛','민트색','하늘색','살구색','라벤더','코랄빛',
                    '레몬색','장미빛','청포도','피치','시나몬','솜사탕','아이보리',
                    '라일락','청옥','버터','멜론','구름빛','연분홍'];
    const LIVE_ANI=['까치','참새','박새','멧비둘기','직박구리','제비','백로','왜가리',
                    '뻐꾸기','물총새','두루미','기러기','청둥오리','저어새','꾀꼬리',
                    '동박새','오목눈이','수리부엉이','팔색조','호반새','파랑새','후투티',
                    '원앙','종달새'];
    function makeLiveName(){
        const a=LIVE_ADJ[Math.floor(Math.random()*LIVE_ADJ.length)];
        const b=LIVE_ANI[Math.floor(Math.random()*LIVE_ANI.length)];
        return a+' '+b;
    }
    function liveName(){
        try{
            let v=localStorage.getItem('sdy_uname_v2');
            if(!v||!v.trim()||v==='사용자'||v==='익명'){
                v=makeLiveName();
                localStorage.setItem('sdy_uname_v2',v);
            }
            return v;
        }catch(e){ return makeLiveName(); }
    }
    let liveTimer=null, liveRateTimer=null, liveLast={x:null,y:null,page:0},
        liveOn=false, liveMoved=false, _liveBusy=false, _liveQueued=false,
        _liveLastPoll=0;
    // 상대가 있을 때는 25fps로 왕복하고, 혼자일 때도 600ms마다 가볍게 확인한다.
    // 내 마우스가 멈췄다고 polling까지 4초 멈추면 움직이는 상대 커서가 내 화면에서
    // 4초씩 얼어 보였던 것이 '현재 위치가 바로 안 오는' 핵심 원인이었다.
    const LIVE_RATE_MS=40, LIVE_DISCOVER_MS=600, LIVE_HEARTBEAT_MS=4000;
    const LIVE_MOVE_EVENT=('PointerEvent' in window)?'pointermove':'mousemove';
    const livePeerCount={};        // 노트별 동시 접속자 수

    function startLive(){
        if(liveOn||!curNB) return;
        liveOn=true; liveMoved=true; _liveLastPoll=0;
        document.addEventListener(LIVE_MOVE_EVENT,onLiveMove,{passive:true});
        liveTimer=setInterval(livePing,LIVE_HEARTBEAT_MS);
        clearInterval(liveRateTimer);
        liveRateTimer=setInterval(liveFastTick,LIVE_RATE_MS);
        livePing();
    }
    function stopLive(){
        if(!liveOn) return;
        liveOn=false;
        document.removeEventListener(LIVE_MOVE_EVENT,onLiveMove);
        clearInterval(liveTimer); liveTimer=null;
        clearInterval(liveRateTimer); liveRateTimer=null;
        _liveBusy=false; _liveQueued=false;
        const bd=document.getElementById('liveBadge'); if(bd) bd.style.display='none';
        const nb=curNB&&curNB.id;
        if(nb) fetch('/api/live/leave',{method:'POST',
            headers:{'Content-Type':'application/json'},
            body:JSON.stringify({note:nb,uid:LIVE_ME}),keepalive:true}).catch(()=>{});
        document.querySelectorAll('.live-cur').forEach(n=>n.remove());
    }
    // 상대가 보이는 동안에는 내가 가만히 있어도 계속 받아야 한다. 혼자일 때만
    // 발견 주기로 낮춰 서버와 배터리 부담을 줄인다.
    function liveFastTick(){
        if(!liveOn||!curNB) return;
        const now=performance.now();
        const hasPeer=(livePeerCount[curNB.id]||1)>1;
        if(!liveMoved && !hasPeer && !liveAct() && now-_liveLastPoll<LIVE_DISCOVER_MS) return;
        liveMoved=false; _liveLastPoll=now;
        livePing();
    }
    function onLiveMove(e){
        const paper=e.target.closest&&e.target.closest('#pagesStage .paper');
        if(!paper) return;
        // 고주사율 마우스/펜은 한 이벤트에 좌표가 여럿 묶인다. 가장 최신 좌표를
        // 사용해야 커서가 한 프레임 뒤를 따라오지 않는다.
        const samples=typeof e.getCoalescedEvents==='function'?e.getCoalescedEvents():null;
        const point=samples&&samples.length?samples[samples.length-1]:e;
        const pi=+paper.dataset.pageIdx||0,p=pageLocal(point,pi);
        liveLast={ x:p.x,y:p.y,page:pi };
        liveMoved=true;
    }
    // 지금 하고 있는 일을 한 마디로 (다른 사람 화면에 함께 표시)
    function liveAct(){
        try{
            if(document.querySelector('.tb.edit')) return '글 쓰는 중';
            if(typeof penActive!=='undefined'&&penActive) return '그리는 중';
            if(typeof eraserActive!=='undefined'&&eraserActive) return '지우는 중';
            if(typeof textToolActive!=='undefined'&&textToolActive) return '글상자 놓는 중';
            if(typeof activeTbl!=='undefined'&&activeTbl) return '표 다루는 중';
            if(typeof drag!=='undefined'&&drag) return '옮기는 중';
            if(typeof findOpen!=='undefined'&&findOpen) return '찾는 중';
            if(String(getSelection()||'').trim()) return '글 고르는 중';
            return '';
        }catch(e){ return ''; }
    }
    async function livePing(){
        if(!liveOn||!curNB) return;
        // 응답이 뒤섞여 커서가 뒤로 튀지 않게 하나씩 직렬 전송한다.
        // 이동 중 연속 호출은 busy 면 다음 완료 직후 최신 좌표로 한 번 이어 보낸다.
        if(_liveBusy){ _liveQueued=true; return; }
        const noteId=curNB.id;       // await 사이 노트 전환 시 옛 응답을 새 문서에 그리지 않음
        _liveBusy=true;
        try{
            const r=await fetch('/api/live/ping',{method:'POST',
                headers:{'Content-Type':'application/json'},
                body:JSON.stringify({note:noteId,uid:LIVE_ME,name:liveName(),
                    x:liveLast.x,y:liveLast.y,page:liveLast.page,on:true,
                    act:liveAct(),ts:Date.now()})});
            const d=await r.json().catch(()=>({}));
            if(!liveOn||!curNB||curNB.id!==noteId) return;
            if(d&&d.ok){
                // 5.35: 표시 순서를 매번 완전 랜덤으로 (같은 순서 고정 방지)
                const peers=(d.peers||[]).slice();
                for(let i=peers.length-1;i>0;i--){
                    const j=(Math.random()*(i+1))|0;
                    const t=peers[i]; peers[i]=peers[j]; peers[j]=t;
                }
                drawPeers(peers);
                const n=peers.length+1;
                const bd=document.getElementById('liveBadge');
                const nm=document.getElementById('liveNum');
                if(bd&&nm){ nm.textContent=n; bd.style.display=n>1?'inline-flex':'none'; }
                livePeerCount[noteId]=n;
            }
        }catch(e){ /* 서버 없으면 조용히 무시 */ }
        finally{
            _liveBusy=false;
            if(_liveQueued && liveOn){
                _liveQueued=false;
                setTimeout(()=>{ if(liveOn) livePing(); },0);
            }
        }
    }
    function drawPeers(peers){
        const stage=document.getElementById('pagesStage');
        if(!stage) return;
        const seen=new Set();
        peers.forEach(p=>{
            if(p.x==null||p.y==null) return;
            seen.add(p.uid);
            const paper=paperAt(p.page||0);
            if(!paper) return;
            let layer=document.getElementById('liveLayer');
            if(!layer||!layer.isConnected){
                layer=document.createElement('div');
                layer.id='liveLayer';
                layer.style.cssText='position:fixed;left:0;top:0;width:100%;height:100%;'+
                                    'pointer-events:none;z-index:1050;';
                document.body.appendChild(layer);
            }
            let n=document.getElementById('live_'+p.uid);
            const isNew=!n;
            if(!n){
                n=document.createElement('div');
                n.id='live_'+p.uid; n.className='live-cur';
                n.innerHTML='<svg viewBox="0 0 24 24" width="20" height="20">'+
                    '<path d="M4 2 L20 12 L13 13 L16 21 L13 22 L10 14 L4 18 Z" '+
                    'fill="currentColor" stroke="#475569" stroke-width="1.4"/></svg>'+
                    '<span class="live-nm"></span>';
                layer.appendChild(n);
            }
            n.style.color=p.color||'#ef4444';
            n.style.zIndex=String(1+((Math.random()*40)|0));   // 5.35: 겹침 순서도 매번 랜덤
            const nmEl=n.querySelector('.live-nm');
            nmEl.textContent=(p.name||'익명')+(p.act?' · '+p.act:'');
            nmEl.style.background=p.color||'#ef4444';
            const pr=paper.getBoundingClientRect(), ps=paperSize();
            // pageScale은 루트 90% zoom과 전환 중 배율을 모른다. 실제 종이 사각형으로
            // 문서 좌표→화면 좌표를 구한 뒤 fixed 레이어의 CSS px로 변환한다.
            const screenX=pr.left+(Number(p.x)||0)*(pr.width/Math.max(1,ps.w));
            const screenY=pr.top +(Number(p.y)||0)*(pr.height/Math.max(1,ps.h));
            const x=_clawCss(screenX), y=_clawCss(screenY);
            if(isNew) n.style.transition='none';
            n.style.setProperty('--live-x',x.toFixed(2)+'px');
            n.style.setProperty('--live-y',y.toFixed(2)+'px');
            if(isNew){
                // 첫 등장만 원점에서 날아오지 않게 즉시 놓고, 다음 프레임부터 보간.
                void n.offsetWidth;
                n.style.transition='';
            }
        });
        document.querySelectorAll('.live-cur').forEach(n=>{
            if(!seen.has(n.id.replace('live_',''))) n.remove();
        });
    }
    addEventListener('beforeunload',()=>{ if(liveOn) stopLive(); });

    async function renderPageCanvas(pageIdx,opt){
        opt=opt||{};
        const size=paperSize();
        const page=JSON.parse(JSON.stringify(doc.pages[pageIdx]));
        if(opt.onlyIds) page.els=(page.els||[]).filter(e=>opt.onlyIds.has(e.id));
        (page.els||[]).forEach(el=>{ if(el.type==='text') el.html=fixDarkColors(el.html); });
        for(const el of page.els||[]){
            if(el.type==='image'||el.type==='legacyDraw') el.url=await toDataURL(el.url);
        }

        const sc=Math.max(2,Math.min(3,window.devicePixelRatio||2));
        const c=document.createElement('canvas');
        c.width=Math.ceil(size.w*sc); c.height=Math.ceil(size.h*sc);
        const ctx=c.getContext('2d');
        ctx.scale(sc,sc);
        if(!opt.transparent){
            ctx.fillStyle=(doc&&doc.tint)?doc.tint:'#ffffff';
            ctx.fillRect(0,0,size.w,size.h);
            // ① 종이 배경 — 캔버스에 직접 (SVG 실패와 무관하게 항상 그려짐)
            drawPaperBg(ctx,doc.paper,size);
        }

        // ② 이미지 — 캔버스에 직접 (foreignObject 안 거침 → 훨씬 안정적)
        for(const el of page.els||[]){
            if(el.type==='image'&&el.url){
                try{
                    const im=await loadImg(el.url);
                    ctx.drawImage(im,el.x,el.y,el.w,el.h);
                }catch(e){ console.warn('이미지 건너뜀',e); }
            }else if(el.type==='legacyDraw'&&el.url){
                try{
                    const im=await loadImg(el.url);
                    ctx.drawImage(im,0,0,size.w,size.h);
                }catch(e){}
            }
        }

        // ③ 펜 획 — 캔버스 경로로 직접
        (page.els||[]).forEach(st=>{
            if(st.type!=='stroke') return;
            drawStrokeOnCanvas(ctx,st);
        });

        // ④ 텍스트 — foreignObject(서식 유지). 실패하면 캔버스 텍스트로 폴백.
        const texts=(page.els||[]).filter(e=>e.type==='text'&&(e.html||'').trim());
        const formulas=(page.els||[]).filter(e=>e.type==='latex'&&(e.latex||'').trim());
        if(texts.length||formulas.length){
            let done=false;
            try{
                let body='';
                texts.forEach(el=>{
                    const inner=el.tight
                        ? `width:100%;height:100%;padding:0;box-sizing:border-box;`+
                          `font-size:${el.fontSize||16}px;line-height:1;color:${el.__c||'#111111'};`+
                          `overflow:visible;font-family:${fontCSS(el.font||'noto')};`+
                          `text-align:${el.align||'left'};position:relative;`
                        : `width:100%;height:100%;padding:8px 12px;box-sizing:border-box;`+
                          `font-size:${el.fontSize||16}px;line-height:1.5;color:${el.__c||'#111111'};white-space:pre-wrap;`+
                          `word-break:break-word;overflow:hidden;font-family:${fontCSS(el.font||'noto')};`+
                          `text-align:${el.align||'left'};`;
                    body+=`<div style="position:absolute;left:${el.x}px;top:${el.y}px;width:${el.w}px;height:${el.h}px;">`+
                          `<div style="${inner}">`+
                          htmlToXhtml(el.html)+`</div></div>`;
                });
                formulas.forEach(el=>{
                    let mh;
                    // 9.0 · 내보낼 때도 화면과 똑같은 KaTeX(HTML+MathML)로 그린다.
                    //  mathml 만 쓰면 브라우저 기본 수식 글꼴로 대체돼 폭이 달라지고
                    //  그만큼 옆 본문 위로 번져 글자가 겹쳐 보였다.
                    try{ mh=window.katex?katex.renderToString(el.latex||'',{displayMode:!!el.displayMath,throwOnError:false,strict:'ignore',output:'html'}):esc(el.latex||''); }
                    catch(e){ mh=esc(el.latex||''); }
                    // 가져온 수식은 원문 잉크 상자를 넘지 않도록 넘치는 만큼 축소해 그린다.
                    const imp=!!el.imported;
                    const bw=imp?(el.inkW||el.w):el.w, bh=imp?(el.inkH||el.h):el.h;
                    const k=imp?Math.min(1,(latexFitScale(el)||1)):1;
                    const fs=Math.max(6,(el.fontSize||20)*k);
                    body+=`<div style="position:absolute;left:${el.x}px;top:${el.y}px;width:${bw}px;height:${bh}px;`+
                          `display:flex;align-items:center;${el.displayMath?'justify-content:center;':''}font-size:${fs}px;`+
                          `line-height:1.05;font-family:'Times New Roman',serif;color:#111;`+
                          `overflow:${imp?'hidden':'visible'};">${htmlToXhtml(mh)}</div>`;
                });
                const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${size.w}" height="${size.h}" viewBox="0 0 ${size.w} ${size.h}">`+
                    `<foreignObject x="0" y="0" width="${size.w}" height="${size.h}">`+
                    `<div xmlns="http://www.w3.org/1999/xhtml" style="width:${size.w}px;height:${size.h}px;position:relative;`+
                    `font-family:'Noto Sans KR',sans-serif;">${body}</div></foreignObject></svg>`;
                const img=await svgToImage(svg);
                ctx.drawImage(img,0,0,size.w,size.h);
                done=true;
            }catch(e){
                console.warn('텍스트 SVG 렌더 실패 → 캔버스 폴백',e);
            }
            if(!done){
                texts.forEach(el=>drawTextOnCanvas(ctx,el));
                formulas.forEach(el=>{
                    ctx.save();ctx.fillStyle='#111';
                    // 9.0 · 폴백에서도 원문 잉크 폭을 넘지 않게 글씨를 줄여 그린다.
                    const bw=Math.max(8,(el.imported?(el.inkW||el.w):el.w));
                    let fs=el.fontSize||20;
                    ctx.font=`${fs}px "Times New Roman",serif`;
                    const raw=(el.latex||'').replace(/[{}\\]|\$/g,'');
                    const tw=ctx.measureText(raw).width||1;
                    if(tw>bw){ fs=Math.max(6,fs*(bw/tw)); ctx.font=`${fs}px "Times New Roman",serif`; }
                    ctx.textBaseline='middle';ctx.textAlign=el.displayMath?'center':'left';
                    ctx.fillText(raw,el.displayMath?el.x+bw/2:el.x,el.y+(el.imported?(el.inkH||el.h):el.h)/2);
                    ctx.restore();
                });
            }
        }
        return c;
    }

    function loadImg(src){
        return new Promise((res,rej)=>{
            const i=new Image();
            i.onload=()=>res(i);
            i.onerror=rej;
            i.src=src;
        });
    }

    function drawStrokeOnCanvas(ctx,st){
        const pts=st.pts||[];
        if(!pts.length) return;
        ctx.save();
        ctx.translate(st.dx||0, st.dy||0);
        ctx.strokeStyle=st.color; ctx.lineWidth=st.size;
        if(st.opacity!=null) ctx.globalAlpha=st.opacity;
        ctx.lineCap='round'; ctx.lineJoin='round';
        ctx.beginPath();
        ctx.moveTo(pts[0][0],pts[0][1]);
        if(st.sharp&&!isEllipsePts(pts)){
            for(let i=1;i<pts.length;i++) ctx.lineTo(pts[i][0],pts[i][1]);
        }else{
            for(let i=1;i<pts.length-1;i++){
                const mx=(pts[i][0]+pts[i+1][0])/2, my=(pts[i][1]+pts[i+1][1])/2;
                ctx.quadraticCurveTo(pts[i][0],pts[i][1],mx,my);
            }
            const last=pts[pts.length-1];
            ctx.lineTo(last[0],last[1]);
        }
        ctx.stroke();
        ctx.restore();
    }

    // 서식 없는 순수 텍스트 폴백 (SVG 렌더가 막혔을 때도 글자는 남긴다)
    function drawTextOnCanvas(ctx,el){
        const tmp=document.createElement('div');
        tmp.innerHTML=(el.html||'').replace(/<br\s*\/?>/gi,'\n').replace(/<\/(div|p)>/gi,'\n');
        const text=(tmp.textContent||'').replace(/\u00a0/g,' ');
        if(!text.trim()) return;
        // 단어 상자(tight): 패딩·줄바꿈 없이 상자 중앙에 한 줄로
        if(el.tight){
            const fs=el.fontSize||16;
            ctx.save();
            ctx.fillStyle='#111111';
            ctx.font=`${fs}px ${fontCSS(el.font||'noto')}`;
            ctx.textBaseline='middle';
            const al=el.align||'left';
            ctx.textAlign=al==='center'?'center':al==='right'?'right':'left';
            const ox=al==='center'?el.x+el.w/2:al==='right'?el.x+el.w:el.x;
            ctx.fillText(text.replace(/\s+/g,' '), ox, el.y+el.h/2);
            ctx.restore();
            return;
        }
        const fs=el.fontSize||16, lh=fs*1.5;
        ctx.save();
        ctx.fillStyle='#111111';
        ctx.font=`${fs}px ${fontCSS(el.font||'noto')}`;
        ctx.textBaseline='top';
        const al=el.align||'left';
        ctx.textAlign=al==='center'?'center':al==='right'?'right':'left';
        const maxW=el.w-24;
        const ox=al==='center'?el.x+el.w/2:al==='right'?el.x+el.w-12:el.x+12;
        let y=el.y+8;
        text.split('\n').forEach(para=>{
            let line='';
            for(const ch of para){
                if(ctx.measureText(line+ch).width>maxW && line){
                    ctx.fillText(line, ox, y); y+=lh; line=ch;
                }else line+=ch;
            }
            if(line) { ctx.fillText(line, ox, y); y+=lh; }
        });
        ctx.restore();
    }

    function drawPaperBg(ctx,type,size){
        ctx.save();
        if(type==='lined'){
            ctx.strokeStyle='#e8e8e8'; ctx.lineWidth=1;
            for(let y=47.5;y<size.h;y+=32){
                ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(size.w,y); ctx.stroke();
            }
        }else if(type==='grid'){
            ctx.strokeStyle='#e8e8e8'; ctx.lineWidth=1;
            for(let y=0.5;y<size.h;y+=32){ ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(size.w,y); ctx.stroke(); }
            for(let x=0.5;x<size.w;x+=32){ ctx.beginPath(); ctx.moveTo(x,0); ctx.lineTo(x,size.h); ctx.stroke(); }
        }else if(type==='dotted'){
            ctx.fillStyle='#cfcfcf';
            for(let y=12;y<size.h;y+=24)
                for(let x=12;x<size.w;x+=24){ ctx.beginPath(); ctx.arc(x,y,1,0,6.284); ctx.fill(); }
        }
        ctx.restore();
    }

    // 종이 배경을 SVG 도형으로 직접 그린다 (화면 CSS와 동일한 간격/색)
    function paperBgSVG(type,size){
        let out='';
        if(type==='lined'){
            for(let y=47.5;y<size.h;y+=32) out+=`<line x1="0" y1="${y}" x2="${size.w}" y2="${y}" stroke="#e8e8e8" stroke-width="1"/>`;
        }else if(type==='grid'){
            for(let y=0.5;y<size.h;y+=32) out+=`<line x1="0" y1="${y}" x2="${size.w}" y2="${y}" stroke="#e8e8e8" stroke-width="1"/>`;
            for(let x=0.5;x<size.w;x+=32) out+=`<line x1="${x}" y1="0" x2="${x}" y2="${size.h}" stroke="#e8e8e8" stroke-width="1"/>`;
        }else if(type==='dotted'){
            for(let y=12;y<size.h;y+=24) for(let x=12;x<size.w;x+=24) out+=`<circle cx="${x}" cy="${y}" r="1" fill="#cfcfcf"/>`;
        }
        return out;
    }

    function downloadBlob(blob,name){
        const url=URL.createObjectURL(blob);
        const a=document.createElement('a');
        a.href=url; a.download=name;
        document.body.appendChild(a); a.click(); a.remove();
        setTimeout(()=>URL.revokeObjectURL(url),4000);
    }
    function canvasToBlob(c,type,q){
        return new Promise(res=>{
            if(c.toBlob) c.toBlob(b=>res(b),type,q);
            else{
                const d=c.toDataURL(type,q), bin=atob(d.split(',')[1]);
                const u=new Uint8Array(bin.length);
                for(let i=0;i<bin.length;i++) u[i]=bin.charCodeAt(i);
                res(new Blob([u],{type}));
            }
        });
    }
    function safeTitle(){
        return ((curNB&&curNB.title)||'노트').replace(/[\\/:*?"<>|]/g,'').trim()||'노트';
    }

    // 내보내기 진행 표시
    function expProgress(cur,total,label){
        const el=document.getElementById('expProg');
        if(!el) return;
        if(cur<0){ el.style.display='none'; return; }
        el.style.display='flex';
        el.querySelector('.ep-txt').textContent=label||`내보내는 중... ${cur}/${total}`;
        el.querySelector('.ep-fill').style.width=total?Math.round(cur/total*100)+'%':'0%';
    }

    function openExportModal(){
        if(!doc){ toast('노트를 먼저 열어주세요'); return; }
        document.getElementById('expInfo').textContent=`총 ${doc.pages.length}페이지 · 현재 ${curPageIdx+1}페이지`;
        document.getElementById('exportModal').style.display='flex';
        openNav(closeExportModal);
    }
    function closeExportModal(){ document.getElementById('exportModal').style.display='none'; navDrop(closeExportModal); }

    async function exportCurrentJPG(){
        if(!doc) return;
        if(penActive) finishDrawing();
        commitEditingText();
        expProgress(0,1);
        try{
            const c=await renderPageCanvas(curPageIdx);
            const blob=await canvasToBlob(c,'image/jpeg',0.95);
            downloadBlob(blob, `${safeTitle()}_${curPageIdx+1}.jpg`);
            toast('현재 페이지 저장 완료 ✓',1600);
        }catch(e){ console.error(e); toast('내보내기 실패: '+(e.message||e),3000); }
        finally{ expProgress(-1); }
    }

    async function copyPageToClipboard(){
        if(!doc) return;
        if(penActive) finishDrawing();
        commitEditingText();
        expProgress(0,1,'클립보드로 복사 중...');
        try{
            const c=await renderPageCanvas(curPageIdx);
            const blob=await canvasToBlob(c,'image/png');
            if(navigator.clipboard&&window.ClipboardItem){
                await navigator.clipboard.write([new ClipboardItem({'image/png':blob})]);
                toast('클립보드에 복사됨 ✓',1600);
            }else{
                downloadBlob(blob,`${safeTitle()}_${curPageIdx+1}.png`);
                toast('클립보드 미지원 → 파일로 저장됨',2200);
            }
        }catch(e){ console.error(e); toast('복사 실패: '+(e.message||e),3000); }
        finally{ expProgress(-1); }
    }

    async function exportJPG(){
        if(!doc){ toast('노트를 먼저 열어주세요'); return; }
        if(penActive) finishDrawing();
        commitEditingText();
        const n=doc.pages.length;
        expProgress(0,n);
        try{
            const title=safeTitle();
            for(let i=0;i<n;i++){
                expProgress(i,n);
                const c=await renderPageCanvas(i);
                const blob=await canvasToBlob(c,'image/jpeg',0.95);
                if(!blob) throw new Error('이미지 생성 실패');
                downloadBlob(blob, n>1?`${title}_${i+1}.jpg`:`${title}.jpg`);
                await new Promise(r=>setTimeout(r,320));   // 브라우저 다중 다운로드 여유
            }
            toast(`JPG ${n}장 저장 완료 ✓`,1800);
        }catch(e){
            console.error('JPG 내보내기 실패:',e);
            toast('내보내기 실패: '+(e.message||e),3200);
        }finally{ expProgress(-1); }
    }

    // 진짜 PDF 파일을 직접 생성 (외부 라이브러리/팝업 없이)
    function buildPDF(pages,w,h){
        // pages: [{jpg:Uint8Array}]
        const enc=new TextEncoder();
        const chunks=[]; let len=0;
        const push=(d)=>{ const u=(typeof d==='string')?enc.encode(d):d; chunks.push(u); len+=u.length; return len; };
        const offsets=[];
        push('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n');

        const nPages=pages.length;
        const objTotal=2+nPages*3;           // catalog, pages, then (page,content,image)*n
        const startObj=(i)=>{ offsets[i]=len; push(`${i} 0 obj\n`); };
        const endObj=()=>push('endobj\n');

        startObj(1);
        push(`<< /Type /Catalog /Pages 2 0 R >>\n`); endObj();

        const kids=[]; for(let i=0;i<nPages;i++) kids.push(`${3+i*3} 0 R`);
        startObj(2);
        push(`<< /Type /Pages /Count ${nPages} /Kids [${kids.join(' ')}] >>\n`); endObj();

        for(let i=0;i<nPages;i++){
            const pageObj=3+i*3, contentObj=pageObj+1, imgObj=pageObj+2;
            startObj(pageObj);
            push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${w} ${h}] `+
                 `/Resources << /XObject << /Im0 ${imgObj} 0 R >> >> /Contents ${contentObj} 0 R >>\n`);
            endObj();

            const stream=`q\n${w} 0 0 ${h} 0 0 cm\n/Im0 Do\nQ\n`;
            startObj(contentObj);
            push(`<< /Length ${stream.length} >>\nstream\n${stream}endstream\n`); endObj();

            const jpg=pages[i].jpg;
            startObj(imgObj);
            push(`<< /Type /XObject /Subtype /Image /Width ${pages[i].w} /Height ${pages[i].h} `+
                 `/ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpg.length} >>\nstream\n`);
            push(jpg);
            push('\nendstream\n'); endObj();
        }

        const xrefPos=len;
        let xref=`xref\n0 ${objTotal+1}\n0000000000 65535 f \n`;
        for(let i=1;i<=objTotal;i++){
            xref+=String(offsets[i]||0).padStart(10,'0')+' 00000 n \n';
        }
        push(xref);
        push(`trailer\n<< /Size ${objTotal+1} /Root 1 0 R >>\nstartxref\n${xrefPos}\n%%EOF\n`);

        const out=new Uint8Array(len); let o=0;
        chunks.forEach(c=>{ out.set(c,o); o+=c.length; });
        return new Blob([out],{type:'application/pdf'});
    }

    async function exportPDF(){
        if(!doc){ toast('노트를 먼저 열어주세요'); return; }
        if(penActive) finishDrawing();
        commitEditingText();
        const n=doc.pages.length;
        expProgress(0,n);
        try{
            const size=paperSize();
            const pages=[];
            for(let i=0;i<n;i++){
                expProgress(i,n);
                const c=await renderPageCanvas(i);
                const blob=await canvasToBlob(c,'image/jpeg',0.92);
                const buf=new Uint8Array(await blob.arrayBuffer());
                pages.push({jpg:buf,w:c.width,h:c.height});
            }
            expProgress(n,n,'PDF 만드는 중...');
            const pdf=buildPDF(pages,size.w,size.h);
            downloadBlob(pdf, safeTitle()+'.pdf');
            toast(`PDF 저장 완료 ✓ (${n}쪽)`,2000);
            fetch('/api/notifications/event',{method:'POST',headers:{'Content-Type':'application/json'},
                body:JSON.stringify({kind:'pdf',event:'pdf_'+Date.now().toString(36),
                    title:'PDF를 만들었어요',message:`${safeTitle()} · ${n}쪽 저장 완료`})}).catch(()=>{});
        }catch(e){
            console.error('PDF 내보내기 실패:',e);
            toast('PDF 실패: '+(e.message||e),3200);
        }finally{ expProgress(-1); }
    }


    // ============ 에디터 우클릭 메뉴 ============
    let ctxTarget=null;   // {kind:'blank'|'el'|'text', pageIdx, x, y, el}
    // ── 우클릭 메뉴 ────────────────────────────────────────
    // 항목이 {sub:'번역', items:[...]} 이면 하위 메뉴로 접힌다.
    // 접힌 묶음을 누르면 그 자리에서 펼쳐진다 (창을 새로 띄우지 않음).
    let _ctxItems=null, _ctxOpenSub=null;
    function ctxRender(){
        const m=document.getElementById('ctxMenu');
        const rowHTML=(it)=>{
            if(it==='-') return '<div class="ctx-sep"></div>';
            if(it.sub){
                const on=_ctxOpenSub===it.sub;
                let h=`<div class="ctx-item ctx-group${on?' open':''}" data-sub="${esc(it.sub)}">`+
                      `<i class="${it.i||'ri-more-line'}"></i> ${esc(it.sub)}`+
                      `<i class="ri-arrow-right-s-line ctx-caret"></i></div>`;
                if(on) h+='<div class="ctx-subwrap">'+it.items.map(rowHTML).join('')+'</div>';
                return h;
            }
            return `<div class="ctx-item${it.danger?' danger':''}" data-a="${it.a}">`+
                   `<i class="${it.i}"></i> ${it.t}`+
                   (it.k?`<span class="ctx-key">${it.k}</span>`:'')+
                   `</div>`;
        };
        m.innerHTML=_ctxItems.map(rowHTML).join('');
        m.querySelectorAll('.ctx-item[data-a]').forEach(n=>{
            n.onclick=(ev)=>{ ev.stopPropagation(); closeCtxMenu(); editorAction(n.dataset.a); };
        });
        m.querySelectorAll('.ctx-item[data-sub]').forEach(n=>{
            n.onclick=(ev)=>{ ev.stopPropagation();
                _ctxOpenSub=(_ctxOpenSub===n.dataset.sub)?null:n.dataset.sub;
                ctxRender(); ctxPlace(true); };
        });
    }
    // 화면 안에 반드시 들어오도록 놓는다.
    //  · 위/아래가 잘리던 문제: 아래로 넘치면 위로 붙이고, 그래도 길면
    //    스스로 스크롤되게 최대 높이를 준다 (예전엔 top 이 음수가 돼 잘렸다).
    //  · 확대(zoom)를 켜면 메뉴도 같은 비율로 커진다.
    function ctxPlace(keepAnchor){
        const m=document.getElementById('ctxMenu');
        const pad=8;
        // 9.0 · 우클릭 메뉴는 종이 확대율을 따라가지 않는다.
        //  예전에는 pageScale 을 그대로 써서, 종이를 2~3배로 키워 보면
        //  메뉴까지 같이 부풀어 화면을 다 덮었다. 메뉴는 '화면 UI' 이므로
        //  종이가 아무리 커져도 항상 읽기 좋은 고정 크기로 둔다.
        //  터치 기기에서만 손가락에 맞춰 아주 살짝 키운다.
        const touch=matchMedia('(pointer:coarse)').matches;
        const z=touch?1.06:1;
        m.style.setProperty('--ctxz', z.toFixed(3));
        m.style.maxHeight='';
        // lastMouse(화면 px)와 offsetWidth(메뉴가 쓰는 CSS px)는 사이트 기본
        // 배율(90%) 때문에 단위가 다르다. 전부 CSS px 로 맞춰 재야 메뉴가
        // 눌린 바로 그 자리에 뜨고 화면 밖으로 나가지 않는다.
        const vw=uiCss(window.innerWidth), vh=uiCss(window.innerHeight);
        const maxH=vh-pad*2;
        if(m.offsetHeight>maxH) m.style.maxHeight=maxH+'px';
        const w=m.offsetWidth||210, h=m.offsetHeight||300;
        const ax=(keepAnchor&&_ctxAnchor)?_ctxAnchor.x:lastMouse.clientX;
        const ay=(keepAnchor&&_ctxAnchor)?_ctxAnchor.y:lastMouse.clientY;
        _ctxAnchor={x:ax,y:ay};
        let x=uiCss(ax), y=uiCss(ay);
        // 가로: 오른쪽에 자리가 없으면 왼쪽으로 펼친다
        let L=(x+w+pad>vw)? x-w : x;
        L=Math.max(pad, Math.min(L, vw-w-pad));
        // 세로: 아래가 모자라면 위로 올리되, 절대 음수로 가지 않는다
        let T=(y+h+pad>vh)? y-h : y;
        T=Math.max(pad, Math.min(T, vh-h-pad));
        m.style.left=Math.round(L)+'px';
        m.style.top =Math.round(T)+'px';
    }
    let _ctxAnchor=null;
    function editorMenu(items){
        _ctxItems=items; _ctxOpenSub=null; _ctxAnchor=null;
        const m=document.getElementById('ctxMenu');
        ctxRender();
        m.classList.add('show');
        ctxPlace(false);
    }

    function onEditorContext(e){
        if(!doc) return;
        const paper=e.target.closest('#pagesStage .paper');
        if(!paper) return;
        e.preventDefault();
        closePops();
        const pageIdx=+paper.dataset.pageIdx;
        curPageIdx=pageIdx; updatePageInfo();
        const p=pageLocal(e,pageIdx),px=p.x,py=p.y;
        lastMouse.clientX=e.clientX; lastMouse.clientY=e.clientY;
        lastMouse.pageIdx=pageIdx; lastMouse.x=px; lastMouse.y=py;

        // ① 글자를 드래그해 고른 상태 (편집 중이 아니어도 동작)
        //    우클릭 순간 브라우저가 선택을 지우는 경우가 있어,
        //    직전에 저장해 둔 선택(savedRange)까지 함께 살펴본다.
        const editing=document.querySelector('.tb.edit');
        let sel=window.getSelection();
        let selHost=(sel&&!sel.isCollapsed&&sel.anchorNode)
            ? (sel.anchorNode.nodeType===1?sel.anchorNode:sel.anchorNode.parentElement)
            : null;
        let selBox=selHost?selHost.closest('.tb-content'):null;
        let selText=selBox?String(sel):'';
        if((!selBox||!selText.trim()) && savedRange && savedHost
           && document.body.contains(savedHost) && String(savedRange).trim()){
            // 저장된 선택을 되살려 그대로 이어서 쓴다
            selBox=savedHost;
            selText=String(savedRange);
            const s2=window.getSelection();
            s2.removeAllRanges(); s2.addRange(savedRange.cloneRange());
            sel=s2;
        }
        if(selBox && selText.trim()){
            // 편집 모드가 아니었다면 지금 진입시켜 그 자리에서 바로 고칠 수 있게 한다
            const w=selBox.closest('.tb');
            if(w && !w.classList.contains('edit')){
                const r0=sel.getRangeAt(0).cloneRange();
                enterEdit(w,true);
                enableTextSelect(selBox);
                const s2=window.getSelection();
                s2.removeAllRanges(); s2.addRange(r0);
            }
            saveSel();
            const txt=selText.trim();
            const short=txt.length>12?txt.slice(0,12)+'…':txt;
            ctxTarget={kind:'text',pageIdx,el:selBox.closest('.tb')};
            editorMenu([
                {a:'copy',   i:'ri-file-copy-line', t:'복사',      k:'Ctrl+C'},
                {a:'cut',    i:'ri-scissors-line',  t:'잘라내기',   k:'Ctrl+X'},
                {a:'bold',   i:'ri-bold',           t:'굵게',      k:'Ctrl+B'},
                {a:'hl',     i:'ri-mark-pen-line',  t:'형광펜'},
                {a:'sel-find',  i:'ri-search-line', t:`'${esc(short)}' 찾기`},
                '-',
                {sub:'서식', i:'ri-font-color', items:[
                    {a:'italic', i:'ri-italic',        t:'기울임',  k:'Ctrl+I'},
                    {a:'under',  i:'ri-underline',     t:'밑줄',   k:'Ctrl+U'},
                    {a:'strike', i:'ri-strikethrough', t:'취소선'},
                    {a:'color',  i:'ri-font-color',    t:'글자색 적용'},
                    {a:'clear',  i:'ri-format-clear',  t:'서식 지우기'},
                ]},
                {sub:'번역', i:'ri-translate-2', items:[
                    {a:'tr-sel-ko', i:'ri-translate-2', t:'한국어로'},
                    {a:'tr-sel-en', i:'ri-translate',   t:'영어로'},
                    {a:'tr-sel-ja', i:'ri-translate',   t:'일본어로'},
                    {a:'tr-sel-zh', i:'ri-translate',   t:'중국어로'},
                ]},
                {sub:'더보기', i:'ri-more-line', items:[
                    {a:'sel-clip',  i:'ri-inbox-archive-line', t:'모아두기에 담기'},
                    {a:'sel-upper', i:'ri-font-size-2', t:'영문 대문자로'},
                    {a:'sel-lower', i:'ri-font-size',   t:'영문 소문자로'},
                    {a:'sel-link',  i:'ri-link',        t:'링크 걸기'},
                    {a:'sel-count', i:'ri-calculator-line', t:'글자 수 세기'},
                    {a:'sel-newbox',i:'ri-text-block',  t:'새 글상자로 빼내기'},
                ]},
            ]);
            return;
        }

        // ② 요소 위
        const host=e.target.closest('.tb')||e.target.closest('.paper-img')||e.target.closest('.stroke-g');
        if(host){
            const kind=host.classList.contains('latex-box')?'latex'
                      :host.classList.contains('tb')?'text-el'
                      :host.classList.contains('paper-img')?'img':'stroke';
            // 다중 선택 상태에서 그 안의 요소를 우클릭하면 선택을 유지한다
            const inMulti=multiSel.some(m=>m.node===host);
            deselectAll(true);
            if(!inMulti) clearMulti();
            host.classList.add('sel');
            selected={type:kind==='img'?'image':(kind==='stroke'?'stroke':'text'),el:host};
            ctxTarget={kind:'el',pageIdx,el:host,elKind:kind};
            const multi=multiSel.length>1;
            const items=[
                {a:'el-copy',  i:'ri-file-copy-line', t:'복사', k:'Ctrl+C'},
                {a:'el-cut',   i:'ri-scissors-line',  t:'잘라내기', k:'Ctrl+X'},
                {a:'el-dup',   i:'ri-file-copy-2-line', t:'복제', k:'Ctrl+J'},
            ];
            if(kind==='text-el' && !multi) items.push({a:'el-edit', i:'ri-edit-line', t:'내용 편집'});
            if(kind==='latex' && !multi) items.push({a:'latex-edit', i:'ri-function-line', t:'LaTeX 수식 편집'});
            items.push('-');

            // 표 안이면 표 편집을 하위 메뉴로
            {
                const hel=findEl(pageIdx,host.dataset.id);
                const tid=(hel&&hel.tbl&&hel.tbl.tid)||null;
                if(tid){
                    setActiveTbl(pageIdx,tid,(hel.tbl.r)||0,(hel.tbl.c)||0);
                    items.push({sub:'표 편집', i:'ri-table-line', items:[
                        {a:'tbl-row-up',   i:'ri-insert-row-top',      t:'위에 행 추가'},
                        {a:'tbl-row-down', i:'ri-insert-row-bottom',   t:'아래에 행 추가'},
                        {a:'tbl-col-left', i:'ri-insert-column-left',  t:'왼쪽에 열 추가'},
                        {a:'tbl-col-right',i:'ri-insert-column-right', t:'오른쪽에 열 추가'},
                        {a:'tbl-fit',      i:'ri-layout-column-line',  t:'열 너비 고르게'},
                        {a:'tbl-del-row',  i:'ri-delete-row',    t:'이 행 삭제', danger:true},
                        {a:'tbl-del-col',  i:'ri-delete-column', t:'이 열 삭제', danger:true},
                        {a:'tbl-del',      i:'ri-delete-bin-6-line', t:'표 전체 삭제', danger:true},
                    ]});
                }
            }
            if(kind==='text-el'){
                items.push({sub:'정렬·서식', i:'ri-align-left', items:[
                    {a:'el-align-left',   i:'ri-align-left',   t:'왼쪽 정렬'},
                    {a:'el-align-center', i:'ri-align-center', t:'가운데 정렬'},
                    {a:'el-align-right',  i:'ri-align-right',  t:'오른쪽 정렬'},
                    {a:'el-clearfmt',     i:'ri-format-clear', t:'이 상자 서식 지우기'},
                ]});
                const tr=[
                    {a:'tr-ko', i:'ri-translate-2', t:'이 상자 → 한국어'},
                    {a:'tr-en', i:'ri-translate',   t:'이 상자 → 영어'},
                ];
                if(multi){
                    tr.push({a:'tr-sel-all-ko', i:'ri-translate-2', t:`선택 ${multiSel.length}개 → 한국어`});
                    tr.push({a:'tr-sel-all-en', i:'ri-translate',   t:`선택 ${multiSel.length}개 → 영어`});
                }
                tr.push({a:'trpg-ko', i:'ri-file-list-3-line', t:'이 페이지 → 한국어'});
                tr.push({a:'trpg-en', i:'ri-file-list-3-line', t:'이 페이지 → 영어'});
                tr.push({a:'trdoc-ko', i:'ri-book-open-line', t:'문서 전체 → 한국어'});
                tr.push({a:'trdoc-en', i:'ri-book-open-line', t:'문서 전체 → 영어'});
                items.push({sub:'번역', i:'ri-translate-2', items:tr});
            }
            if(multi){
                items.push({sub:'여러 개 맞춤', i:'ri-align-item-left-line', items:[
                    {a:'al-left',    i:'ri-align-item-left-line',     t:'왼쪽 맞춤'},
                    {a:'al-hcenter', i:'ri-align-item-horizontal-center-line', t:'가로 가운데'},
                    {a:'al-right',   i:'ri-align-item-right-line',    t:'오른쪽 맞춤'},
                    {a:'al-top',     i:'ri-align-item-top-line',      t:'위쪽 맞춤'},
                    {a:'al-vcenter', i:'ri-align-item-vertical-center-line', t:'세로 가운데'},
                    {a:'al-bottom',  i:'ri-align-item-bottom-line',   t:'아래쪽 맞춤'},
                    ...(multiSel.length>2?[
                        {a:'al-hdist', i:'ri-space', t:'가로 균등 배치'},
                        {a:'al-vdist', i:'ri-space', t:'세로 균등 배치'}]:[]),
                ]});
            }
            // 기타: 순서·잠금·스티커·묶기
            const more=[
                {a:'el-front', i:'ri-bring-to-front', t:'맨 앞으로'},
                {a:'el-back',  i:'ri-send-to-back',   t:'맨 뒤로'},
                {a:'el-sticker', i:'ri-sticky-note-line', t:'스티커로 만들기'},
            ];
            if(!multi){
                more.push({a:'el-lock', i:'ri-lock-2-line',
                    t:(findEl(pageIdx,host.dataset.id)||{}).locked?'잠금 풀기':'움직이지 않게 잠그기'});
            }else{
                more.push({a:'el-sticker-rep', i:'ri-image-add-line', t:'스티커로 합치기'});
                more.push({a:'el-group', i:'ri-links-line', t:'객체 묶기'});
            }
            if(selectionHasGroup()) more.push({a:'el-ungroup', i:'ri-link-unlink', t:'묶음 해제'});
            if(kind==='img'){
                const im=findEl(pageIdx,host.dataset.id);
                const lk=!(im&&im.freeRatio);
                more.push({a:'el-ratio', i:lk?'ri-lock-line':'ri-lock-unlock-line',
                           t:lk?'비율 고정 해제':'비율 고정하기'});
            }
            items.push({sub:'더보기', i:'ri-more-line', items:more});
            items.push('-',{a:'el-del', i:'ri-delete-bin-6-line', t:'삭제', k:'Del', danger:true});
            editorMenu(items);
            return;
        }

        // ③ 빈 종이
        ctxTarget={kind:'blank',pageIdx,x:px,y:py};
        editorMenu([
            {a:'new-text', i:'ri-text',           t:'텍스트 상자'},
            {a:'paste',    i:'ri-clipboard-line', t:'붙여넣기', k:'Ctrl+V'},
            {a:'img',      i:'ri-image-add-line', t:'이미지 넣기'},
            {a:'new-latex',i:'ri-function-line',  t:'LaTeX 수식 넣기'},
            {a:'new-table',i:'ri-table-line',     t:'표 넣기'},
            {a:'pen',      i:'ri-pen-nib-line',   t:'펜 / 도형'},
            '-',
            {sub:'페이지', i:'ri-file-list-3-line', items:[
                {a:'select-all',i:'ri-checkbox-multiple-line', t:'이 페이지 전체 선택', k:'Ctrl+A'},
                {a:'page-dup', i:'ri-file-copy-line', t:'페이지 복제', k:'Ctrl+D'},
                {a:'page-add', i:'ri-file-add-line',  t:'페이지 추가', k:'Ctrl+Enter'},
            ]},
            {sub:'번역', i:'ri-translate-2', items:[
                {a:'trpg-ko', i:'ri-file-list-3-line', t:'이 페이지 → 한국어'},
                {a:'trpg-en', i:'ri-file-list-3-line', t:'이 페이지 → 영어'},
                {a:'trdoc-ko', i:'ri-book-open-line', t:'문서 전체 → 한국어'},
                {a:'trdoc-en', i:'ri-book-open-line', t:'문서 전체 → 영어'},
            ]},
            {a:'export',   i:'ri-download-2-line',t:'내보내기',   k:'Ctrl+E'},
        ]);
    }

    async function editorAction(a){
        const t=ctxTarget; if(!t) return;
        const pi=t.pageIdx;
        if(a==='new-text'){
            const c=clampEl(t.x-TB_W/2,t.y-TB_H/2,TB_W,TB_H);
            addTextBox(pi,c.x,c.y);
        }
        else if(a==='paste'){
            try{
                const items=await navigator.clipboard.read();
                for(const it of items){
                    const imgType=it.types.find(x=>x.startsWith('image/'));
                    if(imgType){
                        const bl=await it.getType(imgType);
                        await uploadImgs([new File([bl],'paste.png',{type:imgType})],true);
                        return;
                    }
                }
                const txt=await navigator.clipboard.readText();
                if(txt&&txt.trim()){
                    const s=paperSize();
                    const w=Math.min(s.w-96,Math.max(220,Math.min(560,txt.length*11)));
                    const h=Math.max(52,txt.split(/\n/).length*(curFontSize*1.5)+26);
                    const c=clampEl(t.x-w/2,t.y-h/2,w,h);
                    pushHistory();
                    doc.pages[pi].els.push({type:'text',id:uid('t'),x:Math.round(c.x),y:Math.round(c.y),
                        w:Math.round(w),h:Math.round(h),html:esc(txt).replace(/\n/g,'<br>'),fontSize:curFontSize});
                    renderPageEls(pi); saveDoc();
                }else toast('클립보드가 비어 있습니다',1400);
            }catch(err){ toast('Ctrl+V 로 붙여넣어 주세요',1800); }
        }
        else if(a==='img'){ triggerImgUpload({pageIdx:pi,x:t.x,y:t.y}); }
        else if(a==='new-latex'){ openLatexModal(); _latexAnchor={pageIdx:pi,x:t.x,y:t.y}; }
        else if(a==='latex-edit'){ openLatexModal(t.el.dataset.id,pi); }
        else if(a==='pen'){ togglePen(); }
        else if(a==='page-dup'){ duplicatePage(); }
        else if(a==='page-add'){ addPage(); }
        else if(a==='export'){ openExportModal(); }
        else if(a==='copy'){
            const sel=window.getSelection();
            const txt=sel?String(sel):'';
            if(txt.trim()){
                (navigator.clipboard&&navigator.clipboard.writeText
                    ? navigator.clipboard.writeText(txt).catch(()=>document.execCommand('copy'))
                    : Promise.resolve(document.execCommand('copy')))
                .then(()=>toast('텍스트 복사됨',1200));
            }else document.execCommand('copy');
        }
        else if(a==='cut'){ document.execCommand('cut'); const w=t.el; if(w) syncTextEl(w); }
        else if(a==='bold'){ execFmt('bold'); }
        else if(a==='italic'){ execFmt('italic'); }
        else if(a==='under'){ execFmt('underline'); }
        else if(a==='color'){ applyTextColor(currentTextColor); }
        else if(a==='hl'){ applyHighlight(currentHlColor); }
        else if(a==='clear'){ clearFmt(); }
        else if(a==='el-del'){
            pushHistory();
            const gone=(doc.pages[pi].els||[]).filter(x=>x.id===t.el.dataset.id);
            doc.pages[pi].els=doc.pages[pi].els.filter(x=>x.id!==t.el.dataset.id);
            t.el.remove(); selected=null; saveDoc();
            purgeElements(gone);
        }
        else if(a==='select-all'){ selectAllOnPage(); }
        else if(a&&a.startsWith('al-')){ alignSelection(a.slice(3)); }
        else if(a==='el-copy'){ copyElements(false); }
        else if(a==='el-cut'){  copyElements(true); }
        else if(a==='el-align-left'||a==='el-align-center'||a==='el-align-right'){
            setAlign(a.replace('el-align-',''));
        }
        else if(a==='el-dup'){
            pushHistory();
            const src=findEl(pi,t.el.dataset.id);
            const cp=JSON.parse(JSON.stringify(src));
            cp.id=uid(cp.type[0]);
            if(cp.type==='stroke'){ cp.dx=(cp.dx||0)+16; cp.dy=(cp.dy||0)+16; }
            else { cp.x=Math.min(paperSize().w-cp.w, cp.x+16); cp.y=Math.min(paperSize().h-cp.h, cp.y+16); }
            doc.pages[pi].els.push(cp);
            renderPageEls(pi); saveDoc(); toast('복제됨',1000);
        }
        else if(a==='el-front'||a==='el-back'){
            pushHistory();
            const arr=doc.pages[pi].els;
            const i=arr.findIndex(x=>x.id===t.el.dataset.id);
            if(i>=0){
                const [it]=arr.splice(i,1);
                if(a==='el-front') arr.push(it); else arr.unshift(it);
                renderPageEls(pi); saveDoc();
                toast(a==='el-front'?'맨 앞으로':'맨 뒤로',900);
            }
        }
        else if(a==='el-edit'){ enterEdit(t.el,false); }
        else if(a==='el-clearfmt'){
            pushHistory();
            const c=t.el.querySelector('.tb-content');
            const el=findEl(pi,t.el.dataset.id);
            if(c&&el){
                c.innerHTML=stripFormatting(c.innerHTML);
                el.html=c.innerHTML;
                saveDoc(); toast('서식 지움',1200);
            }
        }
        else if(a==='new-table'){
            const v=prompt('표 크기를 입력하세요 (행 x 열)','3 x 3');
            if(v){ const m=String(v).match(/(\d+)\s*[x\u00d7,\s]\s*(\d+)/);
                   if(m) insertTable(+m[1],+m[2],pi,lastMouse.x,lastMouse.y);
                   else toast('예: 3 x 4 형식으로 입력해 주세요',2200); }
        }
        else if(a==='tbl-row-up'){ tblAdd('row',-1); }
        else if(a==='tbl-row-down'){ tblAdd('row',1); }
        else if(a==='tbl-col-left'){ tblAdd('col',-1); }
        else if(a==='tbl-col-right'){ tblAdd('col',1); }
        else if(a==='tbl-del-row'){ tblDel('row'); }
        else if(a==='tbl-del-col'){ tblDel('col'); }
        else if(a==='tbl-fit'){ tblFit(); }
        else if(a==='tbl-del'){ tblDelAll(); }
        else if(a==='el-lock'){ toggleLockEl(); }
        else if(a==='el-sticker'){ makeSticker(false); }
        else if(a==='el-sticker-rep'){ makeSticker(true); }
        else if(a==='el-group'){ groupSelection(); }
        else if(a==='el-ungroup'){ ungroupSelection(); }
            else if(a==='tr-ko'||a==='tr-en'){ translateElement(t.el,a==='tr-ko'?'ko':'en'); }
            else if(a==='tr-sel-all-ko') translateSelection('ko');
            else if(a==='tr-sel-all-en') translateSelection('en');
            else if(a==='trpg-ko') translatePageAction(t.pageIdx,'ko');
            else if(a==='trpg-en') translatePageAction(t.pageIdx,'en');
            else if(a==='trdoc-ko') translateDocAction('ko');
            else if(a==='trdoc-en') translateDocAction('en');
        else if(a==='tr-sel-ko') translateSelectedText('ko');
        else if(a==='tr-sel-en') translateSelectedText('en');
        else if(a==='tr-sel-ja') translateSelectedText('ja');
        else if(a==='tr-sel-zh') translateSelectedText('zh-CN');
        else if(a==='strike'){ withSelection(()=>document.execCommand('strikeThrough',false,null)); }
        else if(a==='sel-upper'||a==='sel-lower'){
            const up=(a==='sel-upper');
            withSelection(()=>{
                const s=window.getSelection(); if(!s||s.isCollapsed) return;
                const txt=String(s);
                document.execCommand('insertText',false, up?txt.toUpperCase():txt.toLowerCase());
            });
            toast(up?'대문자로 바꿨습니다':'소문자로 바꿨습니다',1400);
        }
        else if(a==='sel-link'){
            const s=window.getSelection();
            const cur=String(s||'').trim();
            const url=prompt('연결할 주소를 입력하세요', /^https?:\/\//i.test(cur)?cur:'https://');
            if(url&&url.trim()){
                withSelection(()=>document.execCommand('createLink',false,url.trim()));
                toast('링크를 걸었습니다',1400);
            }
        }
        else if(a==='sel-find'){
            const q=String(window.getSelection()||'').trim();
            if(!q) return;
            openFind();
            const inp=document.getElementById('findInput');
            inp.value=q; runFind(q);
        }
        else if(a==='sel-count'){ countSelection(); }
        else if(a==='sel-clip'){ clipAdd(); if(sidePanel!=='clip') openPanel('clip'); }
        else if(a==='sel-newbox'){
            const s=window.getSelection();
            const txt=String(s||'').trim();
            if(!txt) return;
            pushHistory();
            const size=paperSize();
            const w=Math.min(size.w-96,Math.max(220,Math.min(520,txt.length*11)));
            const h=Math.max(52,Math.ceil(txt.length*11/w)*(curFontSize*1.6)+24);
            doc.pages[pi].els.push({type:'text',id:uid('t'),
                x:Math.round(lastMouse.x||80), y:Math.round((lastMouse.y||100)+30),
                w:Math.round(w), h:Math.round(h), html:esc(txt),
                fontSize:curFontSize, font:curFont});
            renderPageEls(pi); saveDoc();
            toast('새 글상자로 빼냈습니다',1600);
        }
        else if(a==='el-ratio'){
            const el=findEl(pi,t.el.dataset.id);
            el.freeRatio=!el.freeRatio;
            renderPageEls(pi); saveDoc();
            toast(el.freeRatio
                ? '비율 자유 · 꼭짓점으로도 자유롭게 조절'
                : '비율 고정 · 꼭짓점=비율유지, 변중앙=자유', 1800);
        }
    }
    // 우클릭 직전에 현재 선택을 확보해 둔다 (브라우저가 지우기 전에)
    document.addEventListener('mousedown',e=>{ if(e.button===2) saveSel(); },true);
    document.addEventListener('contextmenu',onEditorContext);

    // ============ 카드 컨텍스트 메뉴 / 부가 기능 ============
    let ctxNB=null;
    function openCardMenu(e,nb){
        ctxNB=nb;
        const cfg=getCfg(nb.id);
        const m=document.getElementById('ctxMenu');
        m.innerHTML=`
            <div class="ctx-item" onclick="ctxAction('open')"><i class="ri-external-link-line"></i> 열기</div>
            <div class="ctx-item" onclick="ctxAction('pin')"><i class="ri-pushpin-2-line"></i> ${cfg.pinned?'고정 해제':'상단 고정'}</div>
            <div class="ctx-item" onclick="ctxAction('rename')"><i class="ri-edit-line"></i> 이름 변경</div>
            <div class="ctx-item" onclick="ctxAction('duplicate')"><i class="ri-file-copy-line"></i> 노트 복제</div>
            <div class="ctx-item" onclick="ctxAction('info')"><i class="ri-information-line"></i> 노트 정보</div>
            <div class="ctx-sep"></div>
            <div class="ctx-item" onclick="ctxAction('lock')"><i class="ri-lock-2-line"></i> ${(cfg.lock&&cfg.lock.enc)?(adminMode?'잠금 해제':'비밀번호 해제'):'비밀번호 잠금'}</div>
            <div class="ctx-item" onclick="ctxAction('export')"><i class="ri-download-2-line"></i> 백업(JSON) 내보내기</div>
            <div class="ctx-sep"></div>
            <div class="ctx-item danger" onclick="ctxAction('delete')"><i class="ri-delete-bin-6-line"></i> 휴지통으로 이동</div>`;
        m.classList.add('show');
        // 화면 밖으로 나가지 않게 (예전엔 위쪽이 잘릴 수 있었다)
        lastMouse.clientX=e.clientX; lastMouse.clientY=e.clientY;
        _ctxAnchor=null;
        ctxPlace(false);
    }
    function closeCtxMenu(){
        const m=document.getElementById('ctxMenu');
        if(m){ m.classList.remove('show'); m.style.display=''; }
    }
    function ctxMenuOpen(){
        const m=document.getElementById('ctxMenu');
        return !!m && m.classList.contains('show');
    }
    // 메뉴 밖을 누르면(좌·우 버튼 모두) 닫는다.
    // 우클릭은 mousedown 단계에서 먼저 닫아 두고, 새 메뉴는 contextmenu 에서 다시 열린다.
    document.addEventListener('mousedown',e=>{
        if(e.target.closest('.ctx-menu')||e.target.closest('.card-menu')) return;
        closeCtxMenu();
    },true);
    document.addEventListener('click',e=>{
        if(!e.target.closest('.ctx-menu')&&!e.target.closest('.card-menu')) closeCtxMenu();
    });
    document.addEventListener('scroll',closeCtxMenu,true);
    document.addEventListener('wheel',()=>{ if(ctxMenuOpen()) closeCtxMenu(); },{passive:true});
    addEventListener('blur',closeCtxMenu);
    addEventListener('resize',closeCtxMenu);

    async function ctxAction(act){
        const nb=ctxNB; closeCtxMenu();
        if(!nb) return;
        const cfg=getCfg(nb.id);
        if(act==='info'){ showNoteInfo(nb); return; }
        if(act==='open'){ openNB(nb); }
        else if(act==='pin'){ cfg.pinned=!cfg.pinned; setCfg(nb.id,cfg); pushSettingsNow(); notebooks=sortNBs(notebooks); renderGrid(); toast(cfg.pinned?'상단에 고정됨 📌':'고정 해제됨'); }
        else if(act==='rename'){
            const t=prompt('새 이름',nb.title||'새 노트');
            if(t&&t.trim()){
                const want=t.trim();
                nb.title=uniqueTitle(want,noteFolder(nb.id),nb.id);
                if(nb.title!==want) toast(`같은 이름이 있어 '${nb.title}' 로 저장했어요`,2200);
                if(String(nb.id).startsWith('local_')) saveLocalNBs();
                else if(SB){ syncStart(); try{ await SB.from('notebooks').update({title:nb.title,updated_at:new Date().toISOString()}).eq('id',nb.id); }catch(e){} syncEnd(); }
                renderGrid(); toast('이름 변경됨');
            }
        }
        else if(act==='duplicate'){ await duplicateNote(nb); }
        else if(act==='lock'){
            if(cfg.lock&&cfg.lock.enc){
                if(adminMode){
                    // 관리자: 위탁(escrow)으로 바로 잠금 해제
                    if(!confirm(`"${nb.title||'새 노트'}" 의 잠금을 해제할까요?`)) return;
                    if(await removeNoteLockFromCard(nb.id)){ renderGrid(); toast('잠금 해제됨 🔓'); }
                }else{
                    toast('노트를 열어서 해제해주세요',2200); openNB(nb);
                }
            }
            else { openNB(nb).then(()=>setTimeout(lockCurrentNote,350)); }
        }
        else if(act==='export'){ exportNoteJSON(nb); }
        else if(act==='delete'){
            if(isLocked(nb.id)&&!isUnlocked(nb.id)&&!adminMode){
                toast('🔒 잠긴 노트는 삭제할 수 없습니다. 먼저 잠금을 해제하세요',2600); return;
            }
            // 항상 휴지통으로 (영구 삭제 없음 — 30일 후 자동 삭제)
            if(!confirm(`"${nb.title||'새 노트'}" 을(를) 휴지통으로 이동할까요?`)) return;
            const _c=document.querySelector('.note-card[data-nb-id="'+nb.id+'"]');
            playClawThrow(_c, ()=>{
                moveToTrash(nb.id);
                renderGrid(); toast('휴지통으로 이동했습니다 · 30일 후 자동 삭제');
            });
        }
        else if(act==='restore'){
            restoreFromTrash(nb.id);
            renderGrid(); toast('복원했습니다');
            setTimeout(()=>{ const c=document.querySelector('.note-card[data-nb-id="'+nb.id+'"]'); if(c) playClawDrop(c); },80);
        }
    }

    async function duplicateNote(nb){
        if(isLocked(nb.id)&&!isUnlocked(nb.id)){ toast('잠긴 노트는 복제할 수 없습니다'); return; }
        const src=await loadDocAsync(nb.id);
        const copy=JSON.parse(JSON.stringify(src));
        // 요소 id 재발급 (충돌 방지)
        (copy.pages||[]).forEach(pg=>{ pg.id=blankPage().id; (pg.els||[]).forEach(el=>{ el.id=uid(el.type[0]); }); });
        const title=uniqueTitle(nb.title||'새 노트',noteFolder(nb.id),null);
        syncStart();
        try{
            if(SB&&!String(nb.id).startsWith('local_')){
                const{data}=await SB.from('notebooks').insert([{title,color:nb.color||'#4f6ef7'}]).select().single();
                if(data){
                    await SB.from('memos').insert([{notebook_id:data.id,content:'',font_size:S.defFS}]);
                    persistDoc(data.id,copy); notebooks.push(data);
                    const fsrc=noteFolder(nb.id); if(fsrc) setNoteFolder(data.id,fsrc);
                }
            }else{
                const id='local_'+Date.now();
                const nnb={id,title,color:nb.color||'#4f6ef7',created_at:new Date().toISOString(),updated_at:new Date().toISOString()};
                persistDoc(id,copy); notebooks.push(nnb); saveLocalNBs();
                const fsrc=noteFolder(nb.id); if(fsrc) setNoteFolder(id,fsrc);
            }
            notebooks=sortNBs(notebooks); renderGrid(); toast('노트 복제됨');
        }catch(e){ console.error(e); toast('복제 실패'); }
        finally{ syncEnd(); }
    }

    async function exportNoteJSON(nb){
        if(isLocked(nb.id)&&!isUnlocked(nb.id)){ toast('잠긴 노트는 먼저 열어주세요'); return; }
        const d=await loadDocAsync(nb.id);
        const blob=new Blob([JSON.stringify({title:nb.title,doc:d,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});
        const a=document.createElement('a');
        a.href=URL.createObjectURL(blob);
        a.download=(nb.title||'노트').replace(/[^가-힣a-zA-Z0-9_ -]/g,'')+'.json';
        a.click();
        setTimeout(()=>URL.revokeObjectURL(a.href),1000);
        toast('백업 파일 저장됨');
    }

    // 현재 페이지 복제
    function duplicatePage(){
        if(!doc) return;
        pushHistory();
        const copy=JSON.parse(JSON.stringify(doc.pages[curPageIdx]));
        copy.id=blankPage().id;
        (copy.els||[]).forEach(el=>{ el.id=uid(el.type[0]); });
        // 표도 새 id 로 (원본과 섞이지 않게)
        const remap={};
        (copy.tables||[]).forEach(t=>{ const n='tb_'+Math.random().toString(36).slice(2,9);
                                       remap[t.id]=n; t.id=n; t.group='g_'+n; });
        (copy.els||[]).forEach(el=>{ if(el.tbl&&remap[el.tbl.tid]){ el.tbl.tid=remap[el.tbl.tid];
                                       el.group='g_'+el.tbl.tid; } });
        doc.pages.splice(curPageIdx+1,0,copy);
        curPageIdx++;
        renderPages(); saveDoc(); toast('페이지 복제됨');
    }

