    P.coverV=Date.now();
    await loadList(); renderTitle(); renderListPop();
    const t=P.list.find(x=>x.id===TAG_EDIT);
    const im=$('mpTagCover');
    im.onerror=()=>{ im.onerror=null; im.src=DEF_COVER; };
